__d(function(e,a,n,r,s,i,l){s.exports={id:"la-casa-delle-finestre-01",storyId:"la-casa-delle-finestre",number:1,title:"The grid",titleIt:"La griglia",difficultyLevel:2,locationIds:["san-quirico-sul-nera","via-della-scuola","mansarda-irene","scuola-media"],characterIds:["irene-colombo","loredana"],events:[{id:"ev-la-casa-delle-finestre-01",summary:"Irene arrives, moves into the attic opposite the closed school, and sees three lights on one line of windows.",characterIds:["irene-colombo","loredana"],locationIds:["san-quirico-sul-nera","via-della-scuola","mansarda-irene","scuola-media"],rememberedFacts:["Irene has just arrived in San Quirico sul Nera","Irene lives opposite the abandoned school","The school has been closed for two years","At night a light appears in one window, then another, then a third","The three windows are on the same horizontal line"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Irene arriva a San Quirico sul Nera nel pomeriggio.",speakerId:null,kind:"narration",lemmas:["irene","arrivare","a","san","quirico","sul","nera","nel","pomeriggio"]},{id:"s02",text:"Il paese \xe8 piccolo.",speakerId:null,kind:"narration",lemmas:["il","paese","essere","piccolo"]},{id:"s03",text:"Irene cerca Via della Scuola a piedi.",speakerId:null,kind:"narration",lemmas:["irene","cercare","via","della","scuola","a","piedi"]},{id:"s04",text:"La valigia \xe8 pesante, per\xf2 cammina.",speakerId:null,kind:"narration",lemmas:["la","valigia","essere","pesante","pero","camminare"]},{id:"s05",text:"La strada \xe8 stretta e c'\xe8 poco rumore.",speakerId:null,kind:"narration",lemmas:["la","strada","essere","stretto","e","ce","poco","rumore"]},{id:"s06",text:"Loredana sta davanti alla porta della casa.",speakerId:null,kind:"narration",lemmas:["loredana","stare","davanti","alla","porta","della","casa"]}]},{id:"p2",order:2,sentences:[{id:"s07",text:"Buonasera.",speakerId:"loredana",kind:"dialogue",lemmas:["buonasera"]},{id:"s08",text:"Lei \xe8 Irene Colombo?",speakerId:"loredana",kind:"dialogue",lemmas:["lei","essere","irene","colombo"]},{id:"s09",text:"S\xec.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes"]},{id:"s10",text:"Arrivo adesso.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["arrivare","adesso"]},{id:"s11",text:"Bene.",speakerId:"loredana",kind:"dialogue",lemmas:["bene"]},{id:"s12",text:"La casa \xe8 questa.",speakerId:"loredana",kind:"dialogue",lemmas:["la","casa","essere","questo"]},{id:"s13",text:"Lei sta di sopra, in mansarda.",speakerId:"loredana",kind:"dialogue",lemmas:["lei","stare","di","sopra","in","mansarda"]},{id:"s14",text:"Le scale sono a sinistra.",speakerId:"loredana",kind:"dialogue",lemmas:["le","scala","essere","a","sinistra"]},{id:"s15",text:"Io sto al piano di sotto.",speakerId:"loredana",kind:"dialogue",lemmas:["io","stare","al","piano","di","sotto"]},{id:"s16",text:"Se serve, bussa.",speakerId:"loredana",kind:"dialogue",lemmas:["se","servire","bussare"]},{id:"s17",text:"La strada \xe8 tranquilla, di giorno e di sera.",speakerId:"loredana",kind:"dialogue",lemmas:["la","strada","essere","tranquillo","di","giorno","e","di","sera"]}]},{id:"p3",order:3,sentences:[{id:"s18",text:"Irene sale le scale con la valigia.",speakerId:null,kind:"narration",lemmas:["irene","salire","le","scala","con","la","valigia"]},{id:"s19",text:"Apre la porta della mansarda.",speakerId:null,kind:"narration",lemmas:["aprire","la","porta","della","mansarda"]},{id:"s20",text:"La stanza \xe8 piccola, per\xf2 c'\xe8 una finestra grande sulla strada.",speakerId:null,kind:"narration",lemmas:["la","stanza","essere","piccolo","pero","ce","una","finestra","grande","sulla","strada"]},{id:"s21",text:"C'\xe8 un letto, un tavolo e una sedia.",speakerId:null,kind:"narration",lemmas:["ce","un","letto","un","tavolo","e","una","sedia"]},{id:"s22",text:"Irene lascia la valigia vicino al letto.",speakerId:null,kind:"narration",lemmas:["irene","lasciare","la","valigia","vicino","al","letto"]},{id:"s23",text:"Poi apre la finestra e guarda fuori.",speakerId:null,kind:"narration",lemmas:["poi","aprire","la","finestra","e","guardare","fuori"]}]},{id:"p4",order:4,sentences:[{id:"s24",text:"Di fronte c'\xe8 un edificio grande.",speakerId:null,kind:"narration",lemmas:["di","fronte","ce","un","edificio","grande"]},{id:"s25",text:"Ha molte finestre.",speakerId:null,kind:"narration",lemmas:["avere","molto","finestra"]},{id:"s26",text:"Una sopra l'altra, una accanto all'altra.",speakerId:null,kind:"narration",lemmas:["una","sopra","altro","una","accanto","altro"]},{id:"s27",text:"Sembra una griglia.",speakerId:null,kind:"narration",lemmas:["sembrare","una","griglia"]},{id:"s28",text:"Che cosa \xe8 quella casa di fronte?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["che","cosa","essere","quello","casa","di","fronte"]},{id:"s29",text:"\xc8 la scuola media.",speakerId:"loredana",kind:"dialogue",lemmas:["essere","la","scuola","medio"]},{id:"s30",text:"\xc8 chiusa da due anni.",speakerId:"loredana",kind:"dialogue",lemmas:["essere","chiudere","da","due","anno"]},{id:"s31",text:"Nessuno entra.",speakerId:"loredana",kind:"dialogue",lemmas:["nessuno","entrare"]},{id:"s32",text:"Di giorno le finestre sono scure.",speakerId:null,kind:"narration",lemmas:["di","giorno","le","finestra","essere","scuro"]},{id:"s33",text:"Irene guarda la scuola per un minuto.",speakerId:null,kind:"narration",lemmas:["irene","guardare","la","scuola","per","un","minuto"]},{id:"s34",text:"Non vede nessuno alle finestre.",speakerId:null,kind:"narration",lemmas:["non","vedere","nessuno","alle","finestra"]},{id:"s35",text:"Poi chiude la finestra perch\xe9 fa fresco.",speakerId:null,kind:"narration",lemmas:["poi","chiudere","la","finestra","perche","fare","fresco"]}]},{id:"p5",order:5,sentences:[{id:"s36",text:"Quando \xe8 sera, Irene \xe8 sola nella mansarda.",speakerId:null,kind:"narration",lemmas:["quando","essere","sera","irene","essere","solo","nella","mansarda"]},{id:"s37",text:"Accende una luce in casa e mangia qualcosa.",speakerId:null,kind:"narration",lemmas:["accendere","una","luce","in","casa","e","mangiare","qualcosa"]},{id:"s38",text:"Poi torna alla finestra.",speakerId:null,kind:"narration",lemmas:["poi","tornare","alla","finestra"]},{id:"s39",text:"Fuori era buio.",speakerId:null,kind:"narration",lemmas:["fuori","essere","buio"]},{id:"s40",text:"La scuola sembrava vuota.",speakerId:null,kind:"narration",lemmas:["la","scuola","sembrare","vuoto"]},{id:"s41",text:"Nessuno camminava in strada.",speakerId:null,kind:"narration",lemmas:["nessuno","camminare","in","strada"]},{id:"s42",text:"Irene resta l\xec e guarda.",speakerId:null,kind:"narration",lemmas:["irene","restare","li","e","guardare"]},{id:"s43",text:"Non c'\xe8 una macchina.",speakerId:null,kind:"narration",lemmas:["non","ce","una","macchina"]},{id:"s44",text:"Non c'\xe8 una voce.",speakerId:null,kind:"narration",lemmas:["non","ce","una","voce"]}]},{id:"p6",order:6,sentences:[{id:"s45",text:"Mentre guarda, vede una luce.",speakerId:null,kind:"narration",lemmas:["mentre","guardare","vedere","una","luce"]},{id:"s46",text:"C'\xe8 una luce in una finestra, al secondo piano.",speakerId:null,kind:"narration",lemmas:["ce","una","luce","in","una","finestra","al","secondo","piano"]},{id:"s47",text:"Non \xe8 forte.",speakerId:null,kind:"narration",lemmas:["non","essere","forte"]},{id:"s48",text:"Per\xf2 c'\xe8.",speakerId:null,kind:"narration",lemmas:["pero","ce"]},{id:"s49",text:"Irene ha visto la luce e non si muove.",speakerId:null,kind:"narration",lemmas:["irene","avere","vedere","la","luce","e","non","si","muovere"]},{id:"s50",text:"Aspetta un minuto, poi due.",speakerId:null,kind:"narration",lemmas:["aspettare","un","minuto","poi","due"]},{id:"s51",text:"La luce si spegne.",speakerId:null,kind:"narration",lemmas:["la","luce","si","spegnere"]},{id:"s52",text:"Poi si accende in un'altra finestra.",speakerId:null,kind:"narration",lemmas:["poi","si","accendere","in","altro","finestra"]},{id:"s53",text:"Non \xe8 la stessa finestra.",speakerId:null,kind:"narration",lemmas:["non","essere","la","stesso","finestra"]},{id:"s54",text:"\xc8 sulla stessa riga.",speakerId:null,kind:"narration",lemmas:["essere","sulla","stesso","riga"]}]},{id:"p7",order:7,sentences:[{id:"s55",text:"Qualcuno?",speakerId:null,kind:"narration",lemmas:["qualcuno"]},{id:"s56",text:"Irene non vede nessuno in strada.",speakerId:null,kind:"narration",lemmas:["irene","non","vedere","nessuno","in","strada"]},{id:"s57",text:"Quindi prende un quaderno e una penna.",speakerId:null,kind:"narration",lemmas:["quindi","prendere","un","quaderno","e","una","penna"]},{id:"s58",text:"Scrive: prima una finestra, poi un'altra.",speakerId:null,kind:"narration",lemmas:["scrivere","prima","una","finestra","poi","altro"]},{id:"s59",text:"Scrive anche l'ora.",speakerId:null,kind:"narration",lemmas:["scrivere","anche","ora"]},{id:"s60",text:"\xc8 tardi.",speakerId:null,kind:"narration",lemmas:["essere","tardi"]},{id:"s61",text:"Aspetta ancora.",speakerId:null,kind:"narration",lemmas:["aspettare","ancora"]},{id:"s62",text:"Poi vede una terza luce.",speakerId:null,kind:"narration",lemmas:["poi","vedere","una","terzo","luce"]},{id:"s63",text:"Tre finestre.",speakerId:null,kind:"narration",lemmas:["tre","finestra"]},{id:"s64",text:"Irene guarda ancora.",speakerId:null,kind:"narration",lemmas:["irene","guardare","ancora"]},{id:"s65",text:"Le tre finestre sono sulla stessa linea orizzontale.",speakerId:null,kind:"narration",lemmas:["le","tre","finestra","essere","sulla","stesso","linea","orizzontale"]},{id:"s66",text:"Non \xe8 una linea su e gi\xf9.",speakerId:null,kind:"narration",lemmas:["non","essere","una","linea","su","e","giu"]},{id:"s67",text:"\xc8 una linea a destra e a sinistra.",speakerId:null,kind:"narration",lemmas:["essere","una","linea","a","destra","e","a","sinistra"]},{id:"s68",text:"Non capisce.",speakerId:null,kind:"narration",lemmas:["non","capire"]},{id:"s69",text:"Per\xf2 scrive anche questo.",speakerId:null,kind:"narration",lemmas:["pero","scrivere","anche","questo"]}]}],questions:[{id:"ch01_q01",chapterId:"la-casa-delle-finestre-01",type:"direct",question:"Where has Irene just arrived?",choices:["San Quirico sul Nera","Rome","Pietralba"],correctChoice:0,explanation:"She arrives in San Quirico sul Nera in the afternoon.",difficulty:2},{id:"ch01_q02",chapterId:"la-casa-delle-finestre-01",type:"event",question:"What building is opposite Irene\u2019s attic?",choices:["The closed middle school","The town hall","A hotel"],correctChoice:0,explanation:"Loredana says it is the scuola media, closed for two years.",difficulty:2},{id:"ch01_q03",chapterId:"la-casa-delle-finestre-01",type:"direct",question:"How long has the school been closed?",choices:["Two years","Two weeks","It is still open"],correctChoice:0,explanation:"Loredana says it has been closed for two years. Nobody goes in.",difficulty:2},{id:"ch01_q04",chapterId:"la-casa-delle-finestre-01",type:"inference",question:"What does Irene notice at night?",choices:["Lights in three windows on the same line","A fire in the street","Someone knocking at her door"],correctChoice:0,explanation:"A light appears, moves, then a third light. The three windows are on one horizontal line.",difficulty:2}]}},1004,[]);
__d(function(e,a,n,r,s,i,o){s.exports={id:"la-casa-delle-finestre-02",storyId:"la-casa-delle-finestre",number:2,title:"The closed school",titleIt:"La scuola chiusa",difficultyLevel:2,locationIds:["via-della-scuola","mansarda-irene","scuola-media","cortile-scuola"],characterIds:["irene-colombo","loredana","quinto-belli"],events:[{id:"ev-la-casa-delle-finestre-02",summary:"By day the school looks empty. Loredana says it is unsafe after an earthquake. A man waters dead plants; he looks up at last night\u2019s windows and leaves.",characterIds:["irene-colombo","loredana","quinto-belli"],locationIds:["via-della-scuola","mansarda-irene","scuola-media","cortile-scuola"],rememberedFacts:["By day the school looks empty and shut","Loredana says it is unsafe after an earthquake and nobody goes in","A man named Quinto, once the caretaker, waters plants that are dead","Quinto looks up at the same line of windows, then walks away"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Stamattina Irene ha aperto la finestra.",speakerId:null,kind:"narration",lemmas:["stamattina","irene","avere","aprire","la","finestra"]},{id:"s02",text:"Ha guardato la scuola di fronte per un minuto.",speakerId:null,kind:"narration",lemmas:["avere","guardare","la","scuola","di","fronte","per","un","minuto"]},{id:"s03",text:"Di giorno la scuola sembra vuota.",speakerId:null,kind:"narration",lemmas:["di","giorno","la","scuola","sembrare","vuoto"]},{id:"s04",text:"Le porte sono chiuse.",speakerId:null,kind:"narration",lemmas:["le","porta","essere","chiudere"]},{id:"s05",text:"Le finestre della riga sono scure.",speakerId:null,kind:"narration",lemmas:["le","finestra","della","riga","essere","scuro"]},{id:"s06",text:"Irene ha preso il quaderno dal tavolo.",speakerId:null,kind:"narration",lemmas:["irene","avere","prendere","il","quaderno","dal","tavolo"]},{id:"s07",text:"Ieri sera c'era una luce, poi un'altra, poi una terza.",speakerId:null,kind:"narration",lemmas:["ieri","sera","ce","una","luce","poi","altro","poi","una","terzo"]},{id:"s08",text:"Stamattina non c'\xe8 nessuna luce.",speakerId:null,kind:"narration",lemmas:["stamattina","non","ce","nessuno","luce"]},{id:"s09",text:"Per\xf2 ha scritto l'ora.",speakerId:null,kind:"narration",lemmas:["pero","avere","scrivere","ora"]},{id:"s10",text:"Quindi non \xe8 un sogno.",speakerId:null,kind:"narration",lemmas:["quindi","non","essere","un","sogno"]},{id:"s11",text:"La scuola era una scuola.",speakerId:null,kind:"narration",lemmas:["la","scuola","essere","una","scuola"]},{id:"s12",text:"Adesso sembra solo un edificio chiuso.",speakerId:null,kind:"narration",lemmas:["adesso","sembrare","solo","un","edificio","chiudere"]}]},{id:"p2",order:2,sentences:[{id:"s13",text:"Irene scende le scale.",speakerId:null,kind:"narration",lemmas:["irene","scendere","le","scala"]},{id:"s14",text:"Loredana \xe8 in cucina con il caff\xe8.",speakerId:null,kind:"narration",lemmas:["loredana","essere","in","cucina","con","il","caffe"]},{id:"s15",text:"Buongiorno.",speakerId:"loredana",kind:"dialogue",lemmas:["buongiorno"]},{id:"s16",text:"Ha dormito?",speakerId:"loredana",kind:"dialogue",lemmas:["avere","dormire"]},{id:"s17",text:"S\xec, grazie.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes","grazie"]},{id:"s18",text:"Per\xf2 ho una domanda.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["pero","avere","una","domanda"]},{id:"s19",text:"La scuola \xe8 davvero vuota?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["la","scuola","essere","davvero","vuoto"]},{id:"s20",text:"Loredana non guarda Irene.",speakerId:null,kind:"narration",lemmas:["loredana","non","guardare","irene"]},{id:"s21",text:"Parla in fretta, come una lezione.",speakerId:null,kind:"narration",lemmas:["parlare","in","fretta","come","una","lezione"]},{id:"s22",text:"C'\xe8 stato un terremoto.",speakerId:"loredana",kind:"dialogue",lemmas:["ce","essere","un","terremoto"]},{id:"s23",text:"Due anni fa.",speakerId:"loredana",kind:"dialogue",lemmas:["due","anno","fa"]},{id:"s24",text:"La scuola non \xe8 sicura.",speakerId:"loredana",kind:"dialogue",lemmas:["la","scuola","non","essere","sicuro"]},{id:"s25",text:"Non si entra.",speakerId:"loredana",kind:"dialogue",lemmas:["non","si","entrare"]},{id:"s26",text:"Nessuno entra.",speakerId:"loredana",kind:"dialogue",lemmas:["nessuno","entrare"]},{id:"s27",text:"Tutti dicono cos\xec.",speakerId:"loredana",kind:"dialogue",lemmas:["tutto","dire","cosi"]},{id:"s28",text:"Irene ascolta e quasi crede.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","e","quasi","credere"]},{id:"s29",text:"Di giorno questa storia sembra vera.",speakerId:null,kind:"narration",lemmas:["di","giorno","questo","storia","sembrare","vero"]}]},{id:"p3",order:3,sentences:[{id:"s30",text:"Irene esce in strada.",speakerId:null,kind:"narration",lemmas:["irene","uscire","in","strada"]},{id:"s31",text:"Il sole \xe8 gi\xe0 alto.",speakerId:null,kind:"narration",lemmas:["il","sole","essere","gia","alto"]},{id:"s32",text:"Cammina fino alla scuola.",speakerId:null,kind:"narration",lemmas:["camminare","fino","alla","scuola"]},{id:"s33",text:"Una donna passa con una borsa.",speakerId:null,kind:"narration",lemmas:["una","donna","passare","con","una","borsa"]},{id:"s34",text:"Scusi, la scuola \xe8 chiusa, vero?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["scusare","la","scuola","essere","chiudere","vero"]},{id:"s35",text:"La donna risponde in fretta.",speakerId:null,kind:"narration",lemmas:["la","donna","rispondere","in","fretta"]},{id:"s36",text:"\xc8 vuota. Non si entra. Nessuno entra.",speakerId:null,kind:"narration",lemmas:["essere","vuoto","non","si","entrare","nessuno","entrare"]},{id:"s37",text:"Poi la donna cammina via.",speakerId:null,kind:"narration",lemmas:["poi","la","donna","camminare","via"]},{id:"s38",text:"Le parole sono le stesse di Loredana.",speakerId:null,kind:"narration",lemmas:["le","parola","essere","le","stesso","di","loredana"]},{id:"s39",text:"Irene resta un momento.",speakerId:null,kind:"narration",lemmas:["irene","restare","un","momento"]},{id:"s40",text:"Poi va alla porta grande.",speakerId:null,kind:"narration",lemmas:["poi","andare","alla","porta","grande"]},{id:"s41",text:"La porta \xe8 chiusa.",speakerId:null,kind:"narration",lemmas:["la","porta","essere","chiudere"]},{id:"s42",text:"Irene non prova ad aprire.",speakerId:null,kind:"narration",lemmas:["irene","non","provare","ad","aprire"]},{id:"s43",text:"Il cancello del cortile \xe8 chiuso anche lui.",speakerId:null,kind:"narration",lemmas:["il","cancello","del","cortile","essere","chiudere","anche","lui"]}]},{id:"p4",order:4,sentences:[{id:"s44",text:"C'\xe8 un cortile dietro un cancello.",speakerId:null,kind:"narration",lemmas:["ce","un","cortile","dietro","un","cancello"]},{id:"s45",text:"Irene guarda il cortile.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","cortile"]},{id:"s46",text:"C'\xe8 un uomo con i capelli grigi.",speakerId:null,kind:"narration",lemmas:["ce","un","uomo","con","i","capello","grigio"]},{id:"s47",text:"Ha dell'acqua in una tanica.",speakerId:null,kind:"narration",lemmas:["avere","acqua","in","una","tanica"]},{id:"s48",text:"Annaffia le piante vicino al muro.",speakerId:null,kind:"narration",lemmas:["annaffiare","le","pianta","vicino","al","muro"]},{id:"s49",text:"Per\xf2 le piante sono morte.",speakerId:null,kind:"narration",lemmas:["pero","le","pianta","essere","morire"]},{id:"s50",text:"Sono gialle e secche.",speakerId:null,kind:"narration",lemmas:["essere","giallo","e","secco"]},{id:"s51",text:"L'acqua cade sulla terra secca e non serve.",speakerId:null,kind:"narration",lemmas:["acqua","cadere","sulla","terra","secco","e","non","servire"]},{id:"s52",text:"L'uomo annaffia ancora.",speakerId:null,kind:"narration",lemmas:["uomo","annaffiare","ancora"]},{id:"s53",text:"Se la scuola \xe8 vuota, perch\xe9 l'acqua?",speakerId:null,kind:"narration",lemmas:["se","la","scuola","essere","vuoto","perche","acqua"]},{id:"s54",text:"Irene quasi crede ancora a Loredana.",speakerId:null,kind:"narration",lemmas:["irene","quasi","credere","ancora","a","loredana"]},{id:"s55",text:"Per\xf2 l'uomo \xe8 l\xec, di giorno.",speakerId:null,kind:"narration",lemmas:["pero","uomo","essere","li","di","giorno"]},{id:"s56",text:"L'acqua \xe8 vera.",speakerId:null,kind:"narration",lemmas:["acqua","essere","vero"]},{id:"s57",text:"Le piante morte sono vere.",speakerId:null,kind:"narration",lemmas:["le","pianta","morire","essere","vero"]}]},{id:"p5",order:5,sentences:[{id:"s58",text:"Loredana \xe8 alla finestra di sotto.",speakerId:null,kind:"narration",lemmas:["loredana","essere","alla","finestra","di","sotto"]},{id:"s59",text:"\xc8 Quinto.",speakerId:"loredana",kind:"dialogue",lemmas:["essere","quinto"]},{id:"s60",text:"Era il custode.",speakerId:"loredana",kind:"dialogue",lemmas:["essere","il","custode"]},{id:"s61",text:"Irene non gli parla.",speakerId:null,kind:"narration",lemmas:["irene","non","gli","parlare"]},{id:"s62",text:"Guarda in alto, verso la riga di ieri sera.",speakerId:null,kind:"narration",lemmas:["guardare","in","alto","verso","la","riga","di","ieri","sera"]},{id:"s63",text:"Irene conta tre finestre scure.",speakerId:null,kind:"narration",lemmas:["irene","contare","tre","finestra","scuro"]},{id:"s64",text:"Le tre finestre sono buie.",speakerId:null,kind:"narration",lemmas:["le","tre","finestra","essere","buio"]},{id:"s65",text:"Non c'\xe8 una luce.",speakerId:null,kind:"narration",lemmas:["non","ce","una","luce"]},{id:"s66",text:"Quinto alza la testa.",speakerId:null,kind:"narration",lemmas:["quinto","alzare","la","testa"]},{id:"s67",text:"Guarda le stesse finestre.",speakerId:null,kind:"narration",lemmas:["guardare","le","stesso","finestra"]},{id:"s68",text:"Non guarda Irene.",speakerId:null,kind:"narration",lemmas:["non","guardare","irene"]},{id:"s69",text:"Poi prende la tanica e cammina via.",speakerId:null,kind:"narration",lemmas:["poi","prendere","la","tanica","e","camminare","via"]},{id:"s70",text:"Non dice niente a Irene.",speakerId:null,kind:"narration",lemmas:["non","dire","niente","a","irene"]}]}],questions:[{id:"ch02_q01",chapterId:"la-casa-delle-finestre-02",type:"direct",question:"What does Loredana say about the school?",choices:["It is unsafe after an earthquake. Nobody goes in.","It will open again next week.","A teacher still lives there."],correctChoice:0,explanation:"She says there was an earthquake two years ago. The school is not safe. You do not go in.",difficulty:2},{id:"ch02_q02",chapterId:"la-casa-delle-finestre-02",type:"event",question:"What does the man in the courtyard do?",choices:["He waters plants that are already dead","He opens the school door","He paints the windows"],correctChoice:0,explanation:"He waters yellow, dry plants. The water falls on dry earth.",difficulty:2},{id:"ch02_q03",chapterId:"la-casa-delle-finestre-02",type:"character",question:"Who is the man, according to Loredana?",choices:["Quinto, who was the caretaker","Mimmo, who makes videos","Piva, the maresciallo"],correctChoice:0,explanation:"Loredana says: that\u2019s Quinto. He was the custode.",difficulty:2},{id:"ch02_q04",chapterId:"la-casa-delle-finestre-02",type:"inference",question:"What does Quinto do before he walks away?",choices:["He looks up at the same line of windows","He calls Irene over","He turns on a light"],correctChoice:0,explanation:"Irene looks at last night\u2019s dark row. Quinto raises his head and looks at the same windows.",difficulty:2}]}},1005,[]);
__d(function(e,a,n,r,l,i,o){l.exports={id:"la-casa-delle-finestre-03",storyId:"la-casa-delle-finestre",number:3,title:"The contract",titleIt:"Il contratto",difficultyLevel:2,locationIds:["comune","ufficio-alme","scatole-comune"],characterIds:["irene-colombo","alme"],events:[{id:"ev-la-casa-delle-finestre-03",summary:"Irene starts a short contract at the comune. She must scan leftover school papers. One folder says do not scan. She does not open it. Alme tells her to bring anything odd to her, not to the others.",characterIds:["irene-colombo","alme"],locationIds:["comune","ufficio-alme","scatole-comune"],rememberedFacts:["Irene works a short contract at the comune","She must scan old school papers","Dottoressa Alme is polite and in charge of this work","One folder is marked non scansionare","Alme says: if you find anything odd, come to me, not to the others"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Il giorno dopo Irene va al comune.",speakerId:null,kind:"narration",lemmas:["il","giorno","dopo","irene","andare","al","comune"]},{id:"s02",text:"Il comune \xe8 in piazza, non lontano dalla scuola.",speakerId:null,kind:"narration",lemmas:["il","comune","essere","in","piazza","non","lontano","dalla","scuola"]},{id:"s03",text:"Stamattina le finestre della scuola sono di nuovo scure.",speakerId:null,kind:"narration",lemmas:["stamattina","le","finestra","della","scuola","essere","di","nuovo","scuro"]},{id:"s04",text:"Irene non si ferma.",speakerId:null,kind:"narration",lemmas:["irene","non","si","fermare"]},{id:"s05",text:"Cammina fino alla porta del comune e entra.",speakerId:null,kind:"narration",lemmas:["camminare","fino","alla","porta","del","comune","e","entrare"]},{id:"s06",text:"Ha un contratto breve.",speakerId:null,kind:"narration",lemmas:["avere","un","contratto","breve"]},{id:"s07",text:"Oggi \xe8 il primo giorno.",speakerId:null,kind:"narration",lemmas:["oggi","essere","il","primo","giorno"]},{id:"s08",text:"Dalle nove deve essere qui.",speakerId:null,kind:"narration",lemmas:["dalle","nove","dovere","essere","qui"]}]},{id:"p2",order:2,sentences:[{id:"s09",text:"L'ufficio \xe8 piccolo e tranquillo.",speakerId:null,kind:"narration",lemmas:["ufficio","essere","piccolo","e","tranquillo"]},{id:"s10",text:"C'\xe8 una donna dietro una scrivania.",speakerId:null,kind:"narration",lemmas:["ce","una","donna","dietro","una","scrivania"]},{id:"s11",text:"Sorride.",speakerId:null,kind:"narration",lemmas:["sorridere"]},{id:"s12",text:"Buongiorno, Dottoressa Alme.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["buongiorno","dottoressa","alme"]},{id:"s13",text:"Buongiorno, Irene.",speakerId:"alme",kind:"dialogue",lemmas:["buongiorno","irene"]},{id:"s14",text:"Si sieda.",speakerId:"alme",kind:"dialogue",lemmas:["si","sedere"]},{id:"s15",text:"Irene si siede.",speakerId:null,kind:"narration",lemmas:["irene","si","sedere"]},{id:"s16",text:"Firma il contratto sulla scrivania.",speakerId:null,kind:"narration",lemmas:["firmare","il","contratto","sulla","scrivania"]},{id:"s17",text:"Alme tiene una copia.",speakerId:null,kind:"narration",lemmas:["alme","tenere","una","copia"]},{id:"s18",text:"Irene tiene l'altra copia del contratto.",speakerId:null,kind:"narration",lemmas:["irene","tenere","altro","copia","del","contratto"]},{id:"s19",text:"Io sono la dirigente, per queste carte.",speakerId:"alme",kind:"dialogue",lemmas:["io","essere","la","dirigente","per","questo","carta"]},{id:"s20",text:"Il contratto \xe8 per due mesi.",speakerId:"alme",kind:"dialogue",lemmas:["il","contratto","essere","per","due","mese"]},{id:"s21",text:"Poi vediamo.",speakerId:"alme",kind:"dialogue",lemmas:["poi","vedere"]},{id:"s22",text:"Lei scansiona le carte vecchie del comune.",speakerId:"alme",kind:"dialogue",lemmas:["lei","scansionare","le","carta","vecchio","del","comune"]},{id:"s23",text:"Anche quello che resta della scuola.",speakerId:"alme",kind:"dialogue",lemmas:["anche","quello","che","restare","della","scuola"]},{id:"s24",text:"Niente di importante.",speakerId:"alme",kind:"dialogue",lemmas:["niente","di","importante"]},{id:"s25",text:"Quello che \xe8 rimasto, insomma.",speakerId:"alme",kind:"dialogue",lemmas:["quello","che","essere","rimanere","insomma"]},{id:"s26",text:"Alme sorride ancora.",speakerId:null,kind:"narration",lemmas:["alme","sorridere","ancora"]},{id:"s27",text:"Irene ascolta e dice poco.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","e","dire","poco"]},{id:"s28",text:"Va bene.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["andare","bene"]},{id:"s29",text:"Io lavoro con le carte.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["io","lavorare","con","le","carta"]},{id:"s30",text:"Perfetto.",speakerId:"alme",kind:"dialogue",lemmas:["perfetto"]},{id:"s31",text:"Questo \xe8 il suo lavoro, allora.",speakerId:null,kind:"narration",lemmas:["questo","essere","il","suo","lavoro","allora"]}]},{id:"p3",order:3,sentences:[{id:"s32",text:"Le scatole sono gi\xf9.",speakerId:"alme",kind:"dialogue",lemmas:["le","scatola","essere","giu"]},{id:"s33",text:"C'\xe8 anche uno scanner, su un tavolo.",speakerId:"alme",kind:"dialogue",lemmas:["ce","anche","uno","scanner","su","un","tavolo"]},{id:"s34",text:"Irene scende con Alme.",speakerId:null,kind:"narration",lemmas:["irene","scendere","con","alme"]},{id:"s35",text:"C'\xe8 polvere e c'\xe8 poca luce.",speakerId:null,kind:"narration",lemmas:["ce","polvere","e","ce","poco","luce"]},{id:"s36",text:"Ci sono molte cartelle e molte scatole.",speakerId:null,kind:"narration",lemmas:["ci","essere","molto","cartella","e","molto","scatola"]},{id:"s37",text:"Alme indica una scatola vicino allo scanner.",speakerId:null,kind:"narration",lemmas:["alme","indicare","una","scatola","vicino","allo","scanner"]},{id:"s38",text:"Inizia da qui.",speakerId:"alme",kind:"dialogue",lemmas:["iniziare","da","qui"]},{id:"s39",text:"Carte della scuola, anni vecchi.",speakerId:"alme",kind:"dialogue",lemmas:["carta","della","scuola","anno","vecchio"]},{id:"s40",text:"Le scansiona e basta.",speakerId:"alme",kind:"dialogue",lemmas:["le","scansionare","e","basta"]},{id:"s41",text:"Non deve leggere tutto.",speakerId:"alme",kind:"dialogue",lemmas:["non","dovere","leggere","tutto"]},{id:"s42",text:"Alme torna su, ancora con il sorriso.",speakerId:null,kind:"narration",lemmas:["alme","tornare","su","ancora","con","il","sorriso"]},{id:"s43",text:"Irene resta sola con le scatole.",speakerId:null,kind:"narration",lemmas:["irene","restare","solo","con","le","scatola"]}]},{id:"p4",order:4,sentences:[{id:"s44",text:"Irene apre la prima cartella.",speakerId:null,kind:"narration",lemmas:["irene","aprire","la","primo","cartella"]},{id:"s45",text:"Ci sono liste e fogli semplici.",speakerId:null,kind:"narration",lemmas:["ci","essere","lista","e","foglio","semplice"]},{id:"s46",text:"Date, classi, niente di strano.",speakerId:null,kind:"narration",lemmas:["data","classe","niente","di","strano"]},{id:"s47",text:"Mette il foglio sullo scanner.",speakerId:null,kind:"narration",lemmas:["mettere","il","foglio","sullo","scanner"]},{id:"s48",text:"Ha scansionato tre cartelle.",speakerId:null,kind:"narration",lemmas:["avere","scansionare","tre","cartella"]},{id:"s49",text:"Il lavoro \xe8 lento, per\xf2 \xe8 chiaro.",speakerId:null,kind:"narration",lemmas:["il","lavoro","essere","lento","pero","essere","chiaro"]},{id:"s50",text:"Passa quasi un'ora.",speakerId:null,kind:"narration",lemmas:["passare","quasi","ora"]},{id:"s51",text:"Poi vede un'altra scatola, pi\xf9 in fondo.",speakerId:null,kind:"narration",lemmas:["poi","vedere","altro","scatola","piu","in","fondo"]},{id:"s52",text:"Non \xe8 la scatola di Alme.",speakerId:null,kind:"narration",lemmas:["non","essere","la","scatola","di","alme"]},{id:"s53",text:"C'\xe8 una cartella sopra le altre.",speakerId:null,kind:"narration",lemmas:["ce","una","cartella","sopra","le","altro"]},{id:"s54",text:"Sulla copertina c'\xe8 una riga a penna nera.",speakerId:null,kind:"narration",lemmas:["sulla","copertina","ce","una","riga","a","penna","nero"]},{id:"s55",text:"Non scansionare.",speakerId:null,kind:"narration",lemmas:["non","scansionare"]},{id:"s56",text:"Irene legge due volte.",speakerId:null,kind:"narration",lemmas:["irene","leggere","due","volta"]},{id:"s57",text:"La mano \xe8 sulla cartella.",speakerId:null,kind:"narration",lemmas:["la","mano","essere","sulla","cartella"]},{id:"s58",text:"Dovrei aprire questa cartella?",speakerId:null,kind:"narration",lemmas:["dovere","aprire","questo","cartella"]},{id:"s59",text:"Dovrei chiedere ad Alme adesso?",speakerId:null,kind:"narration",lemmas:["dovere","chiedere","ad","alme","adesso"]},{id:"s60",text:"Per\xf2 Alme ha detto: le scansiona e basta.",speakerId:null,kind:"narration",lemmas:["pero","alme","avere","dire","le","scansionare","e","basta"]},{id:"s61",text:"Irene non apre la cartella.",speakerId:null,kind:"narration",lemmas:["irene","non","aprire","la","cartella"]},{id:"s62",text:"La mette da parte, chiusa.",speakerId:null,kind:"narration",lemmas:["la","mettere","da","parte","chiudere"]},{id:"s63",text:"Prende un'altra cartella, normale.",speakerId:null,kind:"narration",lemmas:["prendere","altro","cartella","normale"]},{id:"s64",text:"Scansiona ancora per venti minuti.",speakerId:null,kind:"narration",lemmas:["scansionare","ancora","per","venti","minuto"]},{id:"s65",text:"Le carte normali sono facili.",speakerId:null,kind:"narration",lemmas:["le","carta","normale","essere","facile"]},{id:"s66",text:"La cartella chiusa resta accanto al muro.",speakerId:null,kind:"narration",lemmas:["la","cartella","chiudere","restare","accanto","al","muro"]},{id:"s67",text:"Irene ha finito tre scatole piccole, non tutte.",speakerId:null,kind:"narration",lemmas:["irene","avere","finire","tre","scatola","piccolo","non","tutto"]}]},{id:"p5",order:5,sentences:[{id:"s68",text:"Quando Irene torna su, Alme \xe8 alla porta.",speakerId:null,kind:"narration",lemmas:["quando","irene","tornare","su","alme","essere","alla","porta"]},{id:"s69",text:"Sorride.",speakerId:null,kind:"narration",lemmas:["sorridere"]},{id:"s70",text:"Tutto bene gi\xf9?",speakerId:"alme",kind:"dialogue",lemmas:["tutto","bene","giu"]},{id:"s71",text:"S\xec.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes"]},{id:"s72",text:"Ho visto una cartella.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["avere","vedere","una","cartella"]},{id:"s73",text:"C'\xe8 scritto: non scansionare.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["ce","scrivere","non","scansionare"]},{id:"s74",text:"Alme non perde il sorriso.",speakerId:null,kind:"narration",lemmas:["alme","non","perdere","il","sorriso"]},{id:"s75",text:"Quella resta l\xec.",speakerId:"alme",kind:"dialogue",lemmas:["quello","restare","li"]},{id:"s76",text:"Non \xe8 per oggi.",speakerId:"alme",kind:"dialogue",lemmas:["non","essere","per","oggi"]},{id:"s77",text:"Se trova qualcosa di strano, viene da me.",speakerId:"alme",kind:"dialogue",lemmas:["se","trovare","qualcosa","di","strano","venire","da","me"]},{id:"s78",text:"Non dagli altri.",speakerId:"alme",kind:"dialogue",lemmas:["non","dagli","altro"]},{id:"s79",text:"A mezzogiorno pu\xf2 uscire.",speakerId:"alme",kind:"dialogue",lemmas:["a","mezzogiorno","potere","uscire"]},{id:"s80",text:"Irene dice di s\xec.",speakerId:null,kind:"narration",lemmas:["irene","dire","di","si_yes"]},{id:"s81",text:"Per\xf2 pensa alla cartella chiusa, gi\xf9.",speakerId:null,kind:"narration",lemmas:["pero","pensare","alla","cartella","chiudere","giu"]},{id:"s82",text:"Non l'ha aperta.",speakerId:null,kind:"narration",lemmas:["non","l'ha","aprire"]}]}],questions:[{id:"ch03_q01",chapterId:"la-casa-delle-finestre-03",type:"direct",question:"Where does Irene start work?",choices:["At the comune","At the closed school","At Loredana\u2019s kitchen"],correctChoice:0,explanation:"She has a short contract. She goes to the town hall.",difficulty:2},{id:"ch03_q02",chapterId:"la-casa-delle-finestre-03",type:"event",question:"What must Irene do with the old school papers?",choices:["Scan them","Throw them away today","Take them home"],correctChoice:0,explanation:"Alme says she scans the old papers, including what is left from the school.",difficulty:2},{id:"ch03_q03",chapterId:"la-casa-delle-finestre-03",type:"direct",question:"What is written on one folder?",choices:["Non scansionare","Urgente","Per Quinto"],correctChoice:0,explanation:"On the cover there is a line in pen: do not scan. Irene does not open it.",difficulty:2},{id:"ch03_q04",chapterId:"la-casa-delle-finestre-03",type:"inference",question:"What does Alme tell Irene to do if she finds something odd?",choices:["Come to Alme, not to the others","Call the Carabinieri at once","Ask Quinto in the courtyard"],correctChoice:0,explanation:"Alme smiles and says: if you find anything odd, you come to me. Not to the others.",difficulty:2}]}},1006,[]);
__d(function(e,a,n,i,r,t,s){r.exports={id:"la-casa-delle-finestre-04",storyId:"la-casa-delle-finestre",number:4,title:"The notebook",titleIt:"Il quaderno",difficultyLevel:2,locationIds:["mansarda-irene","scuola-media"],characterIds:["irene-colombo"],events:[{id:"ev-la-casa-delle-finestre-04",summary:"Irene draws the school grid and numbers the windows. Tuesday night the lights follow a different order. The last light is a window that was dark on Monday.",characterIds:["irene-colombo"],locationIds:["mansarda-irene","scuola-media"],rememberedFacts:["Irene draws the fa\xe7ade and numbers the windows","She watches a second night and writes the times","The order of lights on Tuesday is not the same as Monday","Tuesday\u2019s last light is a window that was dark on Monday"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Dopo il lavoro Irene \xe8 in mansarda.",speakerId:null,kind:"narration",lemmas:["dopo","il","lavoro","irene","essere","in","mansarda"]},{id:"s02",text:"La scuola di fronte \xe8 chiusa, come di giorno.",speakerId:null,kind:"narration",lemmas:["la","scuola","di","fronte","essere","chiudere","come","di","giorno"]},{id:"s03",text:"Irene apre il quaderno sul tavolo.",speakerId:null,kind:"narration",lemmas:["irene","aprire","il","quaderno","sul","tavolo"]},{id:"s04",text:"Non vuole una storia.",speakerId:null,kind:"narration",lemmas:["non","volere","una","storia"]},{id:"s05",text:"Vuole i numeri, come sulle cartelle.",speakerId:null,kind:"narration",lemmas:["volere","i","numero","come","sulle","cartella"]},{id:"s06",text:"Prende una penna e guarda le finestre.",speakerId:null,kind:"narration",lemmas:["prendere","una","penna","e","guardare","le","finestra"]},{id:"s07",text:"Conta. Cinque finestre per piano, di fronte a lei.",speakerId:null,kind:"narration",lemmas:["contare","cinque","finestra","per","piano","di","fronte","a","lei"]},{id:"s08",text:"Disegna la scuola: tanti quadrati, una griglia.",speakerId:null,kind:"narration",lemmas:["disegnare","la","scuola","tanto","quadrato","una","griglia"]},{id:"s09",text:"Non \xe8 bello. \xc8 chiaro.",speakerId:null,kind:"narration",lemmas:["non","essere","bello","essere","chiaro"]},{id:"s10",text:"Poi mette i numeri.",speakerId:null,kind:"narration",lemmas:["poi","mettere","i","numero"]},{id:"s11",text:"Piano due, da sinistra: uno, due, tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["piano","due","da","sinistra","uno","due","tre","quattro","cinque"]},{id:"s12",text:"Piano tre: sei, sette, otto, nove, dieci.",speakerId:null,kind:"narration",lemmas:["piano","tre","sei","sette","otto","nove","dieci"]},{id:"s13",text:"La riga di luned\xec sera \xe8 tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["la","riga","di","lunedi","sera","essere","tre","quattro","cinque"]},{id:"s14",text:"Irene lo sa perch\xe9 luned\xec ha visto quella linea.",speakerId:null,kind:"narration",lemmas:["irene","lo","sapere","perche","lunedi","avere","vedere","quello","linea"]},{id:"s15",text:"Scrive luned\xec in alto sulla pagina.",speakerId:null,kind:"narration",lemmas:["scrivere","lunedi","in","alto","sulla","pagina"]},{id:"s16",text:"Irene scrive anche i tre numeri.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","anche","i","tre","numero"]}]},{id:"p2",order:2,sentences:[{id:"s17",text:"Quando \xe8 sera, Irene spegne la luce della stanza.",speakerId:null,kind:"narration",lemmas:["quando","essere","sera","irene","spegnere","la","luce","della","stanza"]},{id:"s18",text:"Lascia solo una piccola luce sul tavolo, per il quaderno.",speakerId:null,kind:"narration",lemmas:["lasciare","solo","una","piccolo","luce","sul","tavolo","per","il","quaderno"]},{id:"s19",text:"Si siede vicino alla finestra.",speakerId:null,kind:"narration",lemmas:["si","sedere","vicino","alla","finestra"]},{id:"s20",text:"Aspetta.",speakerId:null,kind:"narration",lemmas:["aspettare"]},{id:"s21",text:"Fuori la scuola sembra di nuovo vuota.",speakerId:null,kind:"narration",lemmas:["fuori","la","scuola","sembrare","di","nuovo","vuoto"]},{id:"s22",text:"Nessuno cammina in strada.",speakerId:null,kind:"narration",lemmas:["nessuno","camminare","in","strada"]},{id:"s23",text:"Irene guarda l'orologio.",speakerId:null,kind:"narration",lemmas:["irene","guardare","orologio"]},{id:"s24",text:"Sono le nove meno cinque.",speakerId:null,kind:"narration",lemmas:["essere","le","nove","meno","cinque"]},{id:"s25",text:"Aspetta ancora.",speakerId:null,kind:"narration",lemmas:["aspettare","ancora"]},{id:"s26",text:"Poi sono le nove.",speakerId:null,kind:"narration",lemmas:["poi","essere","le","nove"]}]},{id:"p3",order:3,sentences:[{id:"s27",text:"Mentre guarda, vede una luce.",speakerId:null,kind:"narration",lemmas:["mentre","guardare","vedere","una","luce"]},{id:"s28",text:"\xc8 la finestra tre, al piano due.",speakerId:null,kind:"narration",lemmas:["essere","la","finestra","tre","al","piano","due"]},{id:"s29",text:"Come luned\xec, pensa Irene.",speakerId:null,kind:"narration",lemmas:["come","lunedi","pensare","irene"]},{id:"s30",text:"Irene scrive: marted\xec, nove, finestra tre.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","martedi","nove","finestra","tre"]},{id:"s31",text:"Aspetta.",speakerId:null,kind:"narration",lemmas:["aspettare"]},{id:"s32",text:"Poi la luce si spegne.",speakerId:null,kind:"narration",lemmas:["poi","la","luce","si","spegnere"]},{id:"s33",text:"Dopo due minuti si accende un'altra finestra.",speakerId:null,kind:"narration",lemmas:["dopo","due","minuto","si","accendere","altro","finestra"]},{id:"s34",text:"\xc8 la finestra quattro.",speakerId:null,kind:"narration",lemmas:["essere","la","finestra","quattro"]},{id:"s35",text:"Ancora la stessa riga.",speakerId:null,kind:"narration",lemmas:["ancora","la","stesso","riga"]},{id:"s36",text:"Irene scrive: nove e due, finestra quattro.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","nove","e","due","finestra","quattro"]},{id:"s37",text:"Poi, di nuovo, buio.",speakerId:null,kind:"narration",lemmas:["poi","di","nuovo","buio"]},{id:"s38",text:"Irene aspetta la finestra cinque.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","la","finestra","cinque"]},{id:"s39",text:"Guarda la riga. La cinque resta scura.",speakerId:null,kind:"narration",lemmas:["guardare","la","riga","la","cinque","restare","scuro"]},{id:"s40",text:"Aspetta un minuto, poi un altro.",speakerId:null,kind:"narration",lemmas:["aspettare","un","minuto","poi","un","altro"]},{id:"s41",text:"Alle nove e dieci c'\xe8 una terza luce.",speakerId:null,kind:"narration",lemmas:["alle","nove","e","dieci","ce","una","terzo","luce"]},{id:"s42",text:"Irene guarda il disegno.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","disegno"]},{id:"s43",text:"Non \xe8 la finestra cinque.",speakerId:null,kind:"narration",lemmas:["non","essere","la","finestra","cinque"]},{id:"s44",text:"\xc8 la finestra otto, al piano tre.",speakerId:null,kind:"narration",lemmas:["essere","la","finestra","otto","al","piano","tre"]},{id:"s45",text:"Scrive: nove e dieci, finestra otto.",speakerId:null,kind:"narration",lemmas:["scrivere","nove","e","dieci","finestra","otto"]}]},{id:"p4",order:4,sentences:[{id:"s46",text:"La luce resta un poco, poi si spegne.",speakerId:null,kind:"narration",lemmas:["la","luce","restare","un","poco","poi","si","spegnere"]},{id:"s47",text:"Irene apre la pagina di luned\xec.",speakerId:null,kind:"narration",lemmas:["irene","aprire","la","pagina","di","lunedi"]},{id:"s48",text:"Luned\xec: prima tre, poi quattro, poi cinque.",speakerId:null,kind:"narration",lemmas:["lunedi","prima","tre","poi","quattro","poi","cinque"]},{id:"s49",text:"Tutta la riga, lo stesso piano.",speakerId:null,kind:"narration",lemmas:["tutto","la","riga","lo","stesso","piano"]},{id:"s50",text:"Marted\xec: prima tre, poi quattro, poi otto.",speakerId:null,kind:"narration",lemmas:["martedi","prima","tre","poi","quattro","poi","otto"]},{id:"s51",text:"L'ordine non \xe8 lo stesso.",speakerId:null,kind:"narration",lemmas:["ordine","non","essere","lo","stesso"]},{id:"s52",text:"La linea non \xe8 la stessa.",speakerId:null,kind:"narration",lemmas:["la","linea","non","essere","la","stesso"]},{id:"s53",text:"Irene confronta i due disegni.",speakerId:null,kind:"narration",lemmas:["irene","confrontare","i","due","disegno"]},{id:"s54",text:"Prima, poi, dopo: i numeri non tornano.",speakerId:null,kind:"narration",lemmas:["prima","poi","dopo","i","numero","non","tornare"]},{id:"s55",text:"Luned\xec la finestra otto era scura.",speakerId:null,kind:"narration",lemmas:["lunedi","la","finestra","otto","essere","scuro"]},{id:"s56",text:"Nessuna luce, tutta la sera.",speakerId:null,kind:"narration",lemmas:["nessuno","luce","tutto","la","sera"]},{id:"s57",text:"Marted\xec l'ultima luce \xe8 proprio l\xec.",speakerId:null,kind:"narration",lemmas:["martedi","ultimo","luce","essere","proprio","li"]},{id:"s58",text:"Irene non esce.",speakerId:null,kind:"narration",lemmas:["irene","non","uscire"]},{id:"s59",text:"Irene non capisce il perch\xe9.",speakerId:null,kind:"narration",lemmas:["irene","non","capire","il","perche"]},{id:"s60",text:"Per\xf2 scrive l'ora, il numero, il piano.",speakerId:null,kind:"narration",lemmas:["pero","scrivere","ora","il","numero","il","piano"]},{id:"s61",text:"Rilegge i tempi: nove, nove e due, nove e dieci.",speakerId:null,kind:"narration",lemmas:["rileggere","i","tempo","nove","nove","e","due","nove","e","dieci"]},{id:"s62",text:"Il piano tre, luned\xec, era tutto scuro.",speakerId:null,kind:"narration",lemmas:["il","piano","tre","lunedi","essere","tutto","scuro"]},{id:"s63",text:"Marted\xec no.",speakerId:null,kind:"narration",lemmas:["martedi","no"]},{id:"s64",text:"Chiude il quaderno.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno"]},{id:"s65",text:"Non ha una risposta.",speakerId:null,kind:"narration",lemmas:["non","avere","una","risposta"]},{id:"s66",text:"Ha solo due pagine, con i numeri.",speakerId:null,kind:"narration",lemmas:["avere","solo","due","pagina","con","i","numero"]},{id:"s67",text:"Irene lascia la penna accanto al quaderno chiuso.",speakerId:null,kind:"narration",lemmas:["irene","lasciare","la","penna","accanto","al","quaderno","chiudere"]},{id:"s68",text:"La finestra otto resta sulla pagina di marted\xec.",speakerId:null,kind:"narration",lemmas:["la","finestra","otto","restare","sulla","pagina","di","martedi"]},{id:"s69",text:"La scuola \xe8 di nuovo buia.",speakerId:null,kind:"narration",lemmas:["la","scuola","essere","di","nuovo","buio"]}]}],questions:[{id:"ch04_q01",chapterId:"la-casa-delle-finestre-04",type:"event",question:"What does Irene do with the notebook in the daytime?",choices:["She draws the school and numbers the windows","She writes a letter to Alme","She copies the non scansionare folder"],correctChoice:0,explanation:"She draws a grid and puts numbers on the floors and windows.",difficulty:2},{id:"ch04_q02",chapterId:"la-casa-delle-finestre-04",type:"direct",question:"What does she write when a light appears?",choices:["The time and the window number","Sara\u2019s name","A message to the Carabinieri"],correctChoice:0,explanation:"She writes Tuesday, nine, window three \u2014 then the later times and numbers.",difficulty:2},{id:"ch04_q03",chapterId:"la-casa-delle-finestre-04",type:"direct",question:"Is Tuesday\u2019s path the same as Monday\u2019s?",choices:["No. The order is different","Yes. It is the same three windows","There is no light on Tuesday"],correctChoice:0,explanation:"Monday is three, four, five. Tuesday is three, four, then eight.",difficulty:2},{id:"ch04_q04",chapterId:"la-casa-delle-finestre-04",type:"inference",question:"What is special about Tuesday\u2019s last light?",choices:["It is a window that was dark on Monday","It is in Irene\u2019s attic","Quinto turns it on from the courtyard"],correctChoice:0,explanation:"The last light is window eight. On Monday that window stayed dark all evening.",difficulty:2}]}},1007,[]);
__d(function(e,a,i,n,r,s,o){r.exports={id:"la-casa-delle-finestre-05",storyId:"la-casa-delle-finestre",number:5,title:"Mimmo",titleIt:"Mimmo",difficultyLevel:2,locationIds:["via-della-scuola","scuola-media","mansarda-irene"],characterIds:["irene-colombo","mimmo"],events:[{id:"ev-la-casa-delle-finestre-05",summary:"Mimmo shows a ghost video of a light in the school. The phone time is afternoon. At dusk Mimmo is gone; the real lamp starts anyway.",characterIds:["irene-colombo","mimmo"],locationIds:["via-della-scuola","scuola-media","mansarda-irene"],rememberedFacts:["A boy named Mimmo films the school for fun","He says there is a ghost","Irene almost believes the kids\u2019 story","The video time is afternoon, not night","At dusk Mimmo is gone and the real lamp starts anyway"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Il pomeriggio Irene torna dalla piazza.",speakerId:null,kind:"narration",lemmas:["il","pomeriggio","irene","tornare","dalla","piazza"]},{id:"s02",text:"Vicino alla scuola ci sono tre ragazzi.",speakerId:null,kind:"narration",lemmas:["vicino","alla","scuola","ci","essere","tre","ragazzo"]},{id:"s03",text:"Hanno un telefono e ridono.",speakerId:null,kind:"narration",lemmas:["avere","un","telefono","e","ridere"]},{id:"s04",text:"Uno \xe8 pi\xf9 grande degli altri.",speakerId:null,kind:"narration",lemmas:["uno","essere","piu","grande","degli","altro"]},{id:"s05",text:"Ha diciannove anni, o cos\xec dice.",speakerId:null,kind:"narration",lemmas:["avere","diciannove","anno","o","cosi","dire"]},{id:"s06",text:"Ha una giacca rossa e parla forte.",speakerId:null,kind:"narration",lemmas:["avere","una","giacca","rosso","e","parlare","forte"]},{id:"s07",text:"Irene cammina lento, perch\xe9 sente le parole.",speakerId:null,kind:"narration",lemmas:["irene","camminare","lento","perche","sentire","le","parola"]},{id:"s08",text:"Il ragazzo della giacca parla ai suoi amici.",speakerId:null,kind:"narration",lemmas:["il","ragazzo","della","giacca","parlare","ai","suo","amico"]},{id:"s09",text:"Dice che c'\xe8 un fantasma.",speakerId:null,kind:"narration",lemmas:["dire","che","ce","un","fantasma"]},{id:"s10",text:"Nella scuola. Alle finestre.",speakerId:null,kind:"narration",lemmas:["nella","scuola","alle","finestra"]},{id:"s11",text:"Irene ascolta perch\xe9 anche lei ha visto una luce.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","perche","anche","lei","avere","vedere","una","luce"]},{id:"s12",text:"Per un momento la storia dei ragazzi sembra possibile.",speakerId:null,kind:"narration",lemmas:["per","un","momento","la","storia","dei","ragazzo","sembrare","possibile"]}]},{id:"p2",order:2,sentences:[{id:"s13",text:"Irene si ferma.",speakerId:null,kind:"narration",lemmas:["irene","si","fermare"]},{id:"s14",text:"Quasi crede, per un momento.",speakerId:null,kind:"narration",lemmas:["quasi","credere","per","un","momento"]},{id:"s15",text:"Ha visto le luci anche lei.",speakerId:null,kind:"narration",lemmas:["avere","vedere","le","luce","anche","lei"]},{id:"s16",text:"Scusi.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["scusare"]},{id:"s17",text:"Che cosa avete visto?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["che","cosa","avere","vedere"]},{id:"s18",text:"Il ragazzo della giacca sorride.",speakerId:null,kind:"narration",lemmas:["il","ragazzo","della","giacca","sorridere"]},{id:"s19",text:"Un fantasma.",speakerId:"mimmo",kind:"dialogue",lemmas:["un","fantasma"]},{id:"s20",text:"Nella scuola vuota. Una luce.",speakerId:"mimmo",kind:"dialogue",lemmas:["nella","scuola","vuoto","una","luce"]},{id:"s21",text:"Io l'ho filmato.",speakerId:"mimmo",kind:"dialogue",lemmas:["io","avere","filmare"]},{id:"s22",text:"Mi chiamo Mimmo.",speakerId:"mimmo",kind:"dialogue",lemmas:["mi","chiamare","mimmo"]},{id:"s23",text:"Filmo la scuola per divertimento.",speakerId:"mimmo",kind:"dialogue",lemmas:["filmare","la","scuola","per","divertimento"]},{id:"s24",text:"Guarda.",speakerId:"mimmo",kind:"dialogue",lemmas:["guardare"]},{id:"s25",text:"I due amici ridono ancora.",speakerId:null,kind:"narration",lemmas:["i","due","amico","ridere","ancora"]},{id:"s26",text:"Irene non ride.",speakerId:null,kind:"narration",lemmas:["irene","non","ridere"]}]},{id:"p3",order:3,sentences:[{id:"s27",text:"Mimmo le d\xe0 il telefono.",speakerId:null,kind:"narration",lemmas:["mimmo","le","dare","il","telefono"]},{id:"s28",text:"Irene guarda il video.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","video"]},{id:"s29",text:"Lo guarda due volte.",speakerId:null,kind:"narration",lemmas:["lo","guardare","due","volta"]},{id:"s30",text:"C'\xe8 la scuola, di giorno, un po' scura.",speakerId:null,kind:"narration",lemmas:["ce","la","scuola","di","giorno","un","po","scuro"]},{id:"s31",text:"Poi una luce in una finestra, al piano due.",speakerId:null,kind:"narration",lemmas:["poi","una","luce","in","una","finestra","al","piano","due"]},{id:"s32",text:"La luce si muove e poi basta.",speakerId:null,kind:"narration",lemmas:["la","luce","si","muovere","e","poi","basta"]},{id:"s33",text:"Il video \xe8 corto.",speakerId:null,kind:"narration",lemmas:["il","video","essere","corto"]},{id:"s34",text:"Irene quasi crede di nuovo.",speakerId:null,kind:"narration",lemmas:["irene","quasi","credere","di","nuovo"]},{id:"s35",text:"Sembra la stessa finestra di luned\xec.",speakerId:null,kind:"narration",lemmas:["sembrare","la","stesso","finestra","di","lunedi"]},{id:"s36",text:"Quando l'hai fatto?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["quando","avere","fare"]},{id:"s37",text:"Di notte, ovviamente.",speakerId:"mimmo",kind:"dialogue",lemmas:["di","notte","ovviamente"]},{id:"s38",text:"C'\xe8 il fantasma di notte.",speakerId:"mimmo",kind:"dialogue",lemmas:["ce","il","fantasma","di","notte"]},{id:"s39",text:"I ragazzi dicono di s\xec.",speakerId:null,kind:"narration",lemmas:["i","ragazzo","dire","di","si_yes"]}]},{id:"p4",order:4,sentences:[{id:"s40",text:"Irene non discute.",speakerId:null,kind:"narration",lemmas:["irene","non","discutere"]},{id:"s41",text:"Guarda in basso, sul telefono.",speakerId:null,kind:"narration",lemmas:["guardare","in","basso","sul","telefono"]},{id:"s42",text:"C'\xe8 l'ora del video.",speakerId:null,kind:"narration",lemmas:["ce","ora","del","video"]},{id:"s43",text:"C'\xe8 anche il giorno, piccolo, sotto l'immagine.",speakerId:null,kind:"narration",lemmas:["ce","anche","il","giorno","piccolo","sotto","immagine"]},{id:"s44",text:"Irene legge con calma.",speakerId:null,kind:"narration",lemmas:["irene","leggere","con","calma"]},{id:"s45",text:"Non \xe8 notte.",speakerId:null,kind:"narration",lemmas:["non","essere","notte"]},{id:"s46",text:"\xc8 pomeriggio.",speakerId:null,kind:"narration",lemmas:["essere","pomeriggio"]},{id:"s47",text:"Le quattro e dieci.",speakerId:null,kind:"narration",lemmas:["le","quattro","e","dieci"]},{id:"s48",text:"Irene mostra l'ora a Mimmo.",speakerId:null,kind:"narration",lemmas:["irene","mostrare","ora","a","mimmo"]},{id:"s49",text:"Mimmo guarda e alza le spalle.",speakerId:null,kind:"narration",lemmas:["mimmo","guardare","e","alzare","le","spalla"]},{id:"s50",text:"Il telefono sbaglia.",speakerId:"mimmo",kind:"dialogue",lemmas:["il","telefono","sbagliare"]},{id:"s51",text:"Oppure \xe8 il fantasma di giorno. Meglio.",speakerId:"mimmo",kind:"dialogue",lemmas:["oppure","essere","il","fantasma","di","giorno","meglio"]},{id:"s52",text:"Gli amici ridono.",speakerId:null,kind:"narration",lemmas:["gli","amico","ridere"]},{id:"s53",text:"Irene restituisce il telefono.",speakerId:null,kind:"narration",lemmas:["irene","restituire","il","telefono"]},{id:"s54",text:"Grazie.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["grazie"]},{id:"s55",text:"Non dice altro.",speakerId:null,kind:"narration",lemmas:["non","dire","altro"]},{id:"s56",text:"Per\xf2 adesso sa una cosa.",speakerId:null,kind:"narration",lemmas:["pero","adesso","sapere","una","cosa"]},{id:"s57",text:"Quel video non \xe8 la luce di sera.",speakerId:null,kind:"narration",lemmas:["quel","video","non","essere","la","luce","di","sera"]},{id:"s58",text:"\xc8 un gioco del pomeriggio.",speakerId:null,kind:"narration",lemmas:["essere","un","gioco","del","pomeriggio"]},{id:"s59",text:"Irene guarda la scuola adesso, alle quattro e venti.",speakerId:null,kind:"narration",lemmas:["irene","guardare","la","scuola","adesso","alle","quattro","e","venti"]},{id:"s60",text:"Le finestre sono scure.",speakerId:null,kind:"narration",lemmas:["le","finestra","essere","scuro"]},{id:"s61",text:"Nessuna luce, nessun video.",speakerId:null,kind:"narration",lemmas:["nessuno","luce","nessuno","video"]}]},{id:"p5",order:5,sentences:[{id:"s62",text:"Irene va a casa.",speakerId:null,kind:"narration",lemmas:["irene","andare","a","casa"]},{id:"s63",text:"Sale in mansarda e aspetta.",speakerId:null,kind:"narration",lemmas:["salire","in","mansarda","e","aspettare"]},{id:"s64",text:"Quando \xe8 quasi sera, guarda di nuovo la strada.",speakerId:null,kind:"narration",lemmas:["quando","essere","quasi","sera","guardare","di","nuovo","la","strada"]},{id:"s65",text:"Mimmo non c'\xe8.",speakerId:null,kind:"narration",lemmas:["mimmo","non","ce"]},{id:"s66",text:"I ragazzi non ci sono.",speakerId:null,kind:"narration",lemmas:["i","ragazzo","non","ci","essere"]},{id:"s67",text:"Il telefono, le risate, il fantasma: niente.",speakerId:null,kind:"narration",lemmas:["il","telefono","le","risata","il","fantasma","niente"]},{id:"s68",text:"Irene apre il quaderno.",speakerId:null,kind:"narration",lemmas:["irene","aprire","il","quaderno"]},{id:"s69",text:"Scrive: video Mimmo, pomeriggio, quattro e dieci.",speakerId:null,kind:"narration",lemmas:["scrivere","video","mimmo","pomeriggio","quattro","e","dieci"]},{id:"s70",text:"Aspetta alla finestra.",speakerId:null,kind:"narration",lemmas:["aspettare","alla","finestra"]},{id:"s71",text:"Fuori diventa buio.",speakerId:null,kind:"narration",lemmas:["fuori","diventare","buio"]},{id:"s72",text:"Sono le otto, poi le otto e mezza.",speakerId:null,kind:"narration",lemmas:["essere","le","otto","poi","le","otto","e","mezzo"]},{id:"s73",text:"La strada \xe8 vuota.",speakerId:null,kind:"narration",lemmas:["la","strada","essere","vuoto"]},{id:"s74",text:"Poi, alle nove, c'\xe8 una luce.",speakerId:null,kind:"narration",lemmas:["poi","alle","nove","ce","una","luce"]},{id:"s75",text:"Finestra tre, piano due.",speakerId:null,kind:"narration",lemmas:["finestra","tre","piano","due"]},{id:"s76",text:"Non \xe8 un video.",speakerId:null,kind:"narration",lemmas:["non","essere","un","video"]},{id:"s77",text:"Non \xe8 pomeriggio.",speakerId:null,kind:"narration",lemmas:["non","essere","pomeriggio"]},{id:"s78",text:"Mimmo \xe8 andato via.",speakerId:null,kind:"narration",lemmas:["mimmo","essere","andare","via"]},{id:"s79",text:"La luce, per\xf2, c'\xe8 lo stesso.",speakerId:null,kind:"narration",lemmas:["la","luce","pero","ce","lo","stesso"]},{id:"s80",text:"Irene scrive l'ora.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","ora"]},{id:"s81",text:"Non scrive la parola fantasma.",speakerId:null,kind:"narration",lemmas:["non","scrivere","la","parola","fantasma"]},{id:"s82",text:"Scrive solo: nove, finestra tre, come luned\xec.",speakerId:null,kind:"narration",lemmas:["scrivere","solo","nove","finestra","tre","come","lunedi"]}]}],questions:[{id:"ch05_q01",chapterId:"la-casa-delle-finestre-05",type:"character",question:"Who films the school?",choices:["Mimmo","Quinto","Dottoressa Alme"],correctChoice:0,explanation:"Mimmo has a phone. He says he filmed a ghost.",difficulty:2},{id:"ch05_q02",chapterId:"la-casa-delle-finestre-05",type:"direct",question:"What does Mimmo say is in the school?",choices:["A ghost","A teacher who still works there","Irene\u2019s landlady"],correctChoice:0,explanation:"He says there is a fantasma. A light in the windows.",difficulty:2},{id:"ch05_q03",chapterId:"la-casa-delle-finestre-05",type:"event",question:"When was the video made, according to the phone?",choices:["In the afternoon, at ten past four","At nine at night","On Monday at dawn"],correctChoice:0,explanation:"Irene looks at the time on the phone. It is pomeriggio. Le quattro e dieci.",difficulty:2},{id:"ch05_q04",chapterId:"la-casa-delle-finestre-05",type:"inference",question:"What happens after Mimmo is gone?",choices:["At nine a light appears anyway","The school stays dark all night","Mimmo comes back with a better camera"],correctChoice:0,explanation:"At dusk the kids are gone. Then at nine there is a light. It is not a video.",difficulty:2}]}},1008,[]);
__d(function(e,a,i,n,o,t,r){o.exports={id:"la-casa-delle-finestre-06",storyId:"la-casa-delle-finestre",number:6,title:"Quinto",titleIt:"Quinto",difficultyLevel:2,locationIds:["scuola-media","cortile-scuola","via-della-scuola"],characterIds:["irene-colombo","quinto-belli"],events:[{id:"ev-la-casa-delle-finestre-06",summary:"Irene greets Quinto. He has keys and is not clear which key opens what. He says he never goes upstairs. He does not water today. He says the school is empty without looking at her.",characterIds:["irene-colombo","quinto-belli"],locationIds:["scuola-media","cortile-scuola"],rememberedFacts:["Quinto is the caretaker","He has a ring of keys","He is not clear which key opens the door","He says he does not go to the upper floors","He says the school is empty and does not look at Irene"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Il giorno dopo, nel pomeriggio, Irene passa davanti alla scuola.",speakerId:null,kind:"narration",lemmas:["il","giorno","dopo","nel","pomeriggio","irene","passare","davanti","alla","scuola"]},{id:"s02",text:"Il cancello del cortile \xe8 chiuso, come sempre.",speakerId:null,kind:"narration",lemmas:["il","cancello","del","cortile","essere","chiudere","come","sempre"]},{id:"s03",text:"Quinto \xe8 l\xec, dentro.",speakerId:null,kind:"narration",lemmas:["quinto","essere","li","dentro"]},{id:"s04",text:"Irene \xe8 fuori, in strada.",speakerId:null,kind:"narration",lemmas:["irene","essere","fuori","in","strada"]},{id:"s05",text:"Tra loro c'\xe8 il cancello.",speakerId:null,kind:"narration",lemmas:["tra","loro","ce","il","cancello"]},{id:"s06",text:"Oggi non ha la tanica.",speakerId:null,kind:"narration",lemmas:["oggi","non","avere","la","tanica"]},{id:"s07",text:"Non annaffia.",speakerId:null,kind:"narration",lemmas:["non","annaffiare"]},{id:"s08",text:"Sta vicino al muro, con le mani in tasca.",speakerId:null,kind:"narration",lemmas:["stare","vicino","al","muro","con","le","mano","in","tasca"]},{id:"s09",text:"Le piante morte sono ancora l\xec.",speakerId:null,kind:"narration",lemmas:["le","pianta","morire","essere","ancora","li"]},{id:"s10",text:"Irene si ferma.",speakerId:null,kind:"narration",lemmas:["irene","si","fermare"]},{id:"s11",text:"Buongiorno.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["buongiorno"]},{id:"s12",text:"Lei \xe8 Quinto, vero?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["lei","essere","quinto","vero"]},{id:"s13",text:"Quinto alza gli occhi.",speakerId:null,kind:"narration",lemmas:["quinto","alzare","gli","occhio"]},{id:"s14",text:"S\xec.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["si_yes"]},{id:"s15",text:"Il custode.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["il","custode"]},{id:"s16",text:"Lo sono ancora, un poco.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["lo","essere","ancora","un","poco"]},{id:"s17",text:"Da molti anni.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["da","molto","anno"]},{id:"s18",text:"Irene resta dal lato della strada.",speakerId:null,kind:"narration",lemmas:["irene","restare","dal","lato","della","strada"]},{id:"s19",text:"Non prova il cancello.",speakerId:null,kind:"narration",lemmas:["non","provare","il","cancello"]}]},{id:"p2",order:2,sentences:[{id:"s20",text:"Irene non fa molte domande.",speakerId:null,kind:"narration",lemmas:["irene","non","fare","molto","domanda"]},{id:"s21",text:"\xc8 una bella giornata.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["essere","una","bello","giornata"]},{id:"s22",text:"Non fa freddo.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["non","fare","freddo"]},{id:"s23",text:"S\xec. C'\xe8 sole.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["si_yes","ce","sole"]},{id:"s24",text:"C'\xe8 poco vento, oggi.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["ce","poco","vento","oggi"]},{id:"s25",text:"Io sto di fronte, in mansarda.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["io","stare","di","fronte","in","mansarda"]},{id:"s26",text:"Loredana me l'ha detto.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["loredana","me","avere","dire"]},{id:"s27",text:"Lavora al comune, no?",speakerId:"quinto-belli",kind:"dialogue",lemmas:["lavorare","al","comune","no"]},{id:"s28",text:"S\xec. Un contratto breve.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes","un","contratto","breve"]},{id:"s29",text:"Quinto annuisce.",speakerId:null,kind:"narration",lemmas:["quinto","annuire"]},{id:"s30",text:"Il paese \xe8 piccolo.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["il","paese","essere","piccolo"]},{id:"s31",text:"Si sa tutto.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["si","sapere","tutto"]},{id:"s32",text:"Poi tace.",speakerId:null,kind:"narration",lemmas:["poi","tacere"]},{id:"s33",text:"Oggi non c'\xe8 acqua per le piante.",speakerId:null,kind:"narration",lemmas:["oggi","non","ce","acqua","per","le","pianta"]},{id:"s34",text:"O non vuole annaffiare.",speakerId:null,kind:"narration",lemmas:["o","non","volere","annaffiare"]},{id:"s35",text:"Oggi non annaffia, signor Quinto?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["oggi","non","annaffiare","signor","quinto"]},{id:"s36",text:"Oggi no.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["oggi","no"]},{id:"s37",text:"Basta cos\xec.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["basta","cosi"]},{id:"s38",text:"Irene non chiede perch\xe9.",speakerId:null,kind:"narration",lemmas:["irene","non","chiedere","perche"]}]},{id:"p3",order:3,sentences:[{id:"s39",text:"Quinto tira fuori le mani dalle tasche.",speakerId:null,kind:"narration",lemmas:["quinto","tirare","fuori","le","mano","dalle","tasca"]},{id:"s40",text:"C'\xe8 un mazzo di chiavi.",speakerId:null,kind:"narration",lemmas:["ce","un","mazzo","di","chiave"]},{id:"s41",text:"Molte chiavi, su un anello.",speakerId:null,kind:"narration",lemmas:["molto","chiave","su","un","anello"]},{id:"s42",text:"Quinto le conta in fretta, a voce bassa.",speakerId:null,kind:"narration",lemmas:["quinto","le","contare","in","fretta","a","voce","basso"]},{id:"s43",text:"Uno, due, tre, quattro... poi smette.",speakerId:null,kind:"narration",lemmas:["uno","due","tre","quattro","poi","smettere"]},{id:"s44",text:"Alcune sono piccole. Una \xe8 grande.",speakerId:null,kind:"narration",lemmas:["alcuno","essere","piccolo","una","essere","grande"]},{id:"s45",text:"Irene guarda le chiavi, non il viso di Quinto.",speakerId:null,kind:"narration",lemmas:["irene","guardare","le","chiave","non","il","viso","di","quinto"]},{id:"s46",text:"Quelle chiavi aprono la scuola?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["quello","chiave","aprire","la","scuola"]},{id:"s47",text:"Quinto tiene il mazzo in mano.",speakerId:null,kind:"narration",lemmas:["quinto","tenere","il","mazzo","in","mano"]},{id:"s48",text:"Indica la chiave grande.",speakerId:null,kind:"narration",lemmas:["indicare","la","chiave","grande"]},{id:"s49",text:"Questa \xe8 la porta.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["questo","essere","la","porta"]},{id:"s50",text:"Aspetti.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["aspettare"]},{id:"s51",text:"Poi muove il dito.",speakerId:null,kind:"narration",lemmas:["poi","muovere","il","dito"]},{id:"s52",text:"Indica un'altra chiave, pi\xf9 piccola.",speakerId:null,kind:"narration",lemmas:["indicare","altro","chiave","piu","piccolo"]},{id:"s53",text:"No. Questa.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["no","questo"]},{id:"s54",text:"Poi cambia di nuovo.",speakerId:null,kind:"narration",lemmas:["poi","cambiare","di","nuovo"]},{id:"s55",text:"La porta grande \xe8 quest'altra.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["la","porta","grande","essere","altro"]},{id:"s56",text:"Il cancello... questa, forse.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["il","cancello","questo","forse"]},{id:"s57",text:"Irene ascolta.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare"]},{id:"s58",text:"Tre chiavi, tre risposte.",speakerId:null,kind:"narration",lemmas:["tre","chiave","tre","risposta"]},{id:"s59",text:"Non capisce quale chiave \xe8 vera.",speakerId:null,kind:"narration",lemmas:["non","capire","quale","chiave","essere","vero"]},{id:"s60",text:"Quinto rimette il mazzo in tasca in fretta.",speakerId:null,kind:"narration",lemmas:["quinto","rimettere","il","mazzo","in","tasca","in","fretta"]},{id:"s61",text:"Le chiavi fanno rumore.",speakerId:null,kind:"narration",lemmas:["le","chiave","fare","rumore"]},{id:"s62",text:"Irene sente quel rumore.",speakerId:null,kind:"narration",lemmas:["irene","sentire","quel","rumore"]}]},{id:"p4",order:4,sentences:[{id:"s63",text:"E il piano di sopra?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["e","il","piano","di","sopra"]},{id:"s64",text:"Quinto scuote la testa.",speakerId:null,kind:"narration",lemmas:["quinto","scuotere","la","testa"]},{id:"s65",text:"Non vado al piano di sopra.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["non","andare","al","piano","di","sopra"]},{id:"s66",text:"Le aule, i corridoi: no.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["le","aula","i","corridoio","no"]},{id:"s67",text:"Mai.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["mai"]},{id:"s68",text:"Non vado. Non \xe8 il mio piano.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["non","andare","non","essere","il","mio","piano"]},{id:"s69",text:"Non c'\xe8 luce, non c'\xe8 bisogno.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["non","ce","luce","non","ce","bisogno"]},{id:"s70",text:"La scuola \xe8 chiusa da due anni.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["la","scuola","essere","chiudere","da","due","anno"]},{id:"s71",text:"Irene guarda in alto, verso le finestre tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["irene","guardare","in","alto","verso","le","finestra","tre","quattro","cinque"]},{id:"s72",text:"E otto, al piano tre.",speakerId:null,kind:"narration",lemmas:["e","otto","al","piano","tre"]},{id:"s73",text:"Oggi, di giorno, sono scure.",speakerId:null,kind:"narration",lemmas:["oggi","di","giorno","essere","scuro"]},{id:"s74",text:"Quinto non segue il suo sguardo.",speakerId:null,kind:"narration",lemmas:["quinto","non","seguire","il","suo","sguardo"]},{id:"s75",text:"Guarda il cortile, o il muro, o niente.",speakerId:null,kind:"narration",lemmas:["guardare","il","cortile","o","il","muro","o","niente"]}]},{id:"p5",order:5,sentences:[{id:"s76",text:"Irene dice poco.",speakerId:null,kind:"narration",lemmas:["irene","dire","poco"]},{id:"s77",text:"Va bene.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["andare","bene"]},{id:"s78",text:"Grazie.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["grazie"]},{id:"s79",text:"Arrivederci.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["arrivederci"]},{id:"s80",text:"Quinto sta gi\xe0 voltando le spalle.",speakerId:null,kind:"narration",lemmas:["quinto","stare","gia","voltare","le","spalla"]},{id:"s81",text:"Poi parla, verso il cancello, non verso Irene.",speakerId:null,kind:"narration",lemmas:["poi","parlare","verso","il","cancello","non","verso","irene"]},{id:"s82",text:"La scuola \xe8 vuota.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["la","scuola","essere","vuoto"]},{id:"s83",text:"Non la guarda quando lo dice.",speakerId:null,kind:"narration",lemmas:["non","la","guardare","quando","lo","dire"]},{id:"s84",text:"Irene cammina verso casa.",speakerId:null,kind:"narration",lemmas:["irene","camminare","verso","casa"]},{id:"s85",text:"A casa apre il quaderno.",speakerId:null,kind:"narration",lemmas:["a","casa","aprire","il","quaderno"]},{id:"s86",text:"Scrive: chiavi. Non piano di sopra. La scuola \xe8 vuota?",speakerId:null,kind:"narration",lemmas:["scrivere","chiave","non","piano","di","sopra","la","scuola","essere","vuoto"]},{id:"s87",text:"Chiude il quaderno.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno"]}]}],questions:[{id:"ch06_q01",chapterId:"la-casa-delle-finestre-06",type:"character",question:"Who is Quinto?",choices:["The caretaker of the school","A teacher who still works there","Mimmo\u2019s father"],correctChoice:0,explanation:"He says he is the custode.",difficulty:2},{id:"ch06_q02",chapterId:"la-casa-delle-finestre-06",type:"event",question:"What does Quinto have in his hands?",choices:["A bunch of keys","The watering can","Irene\u2019s notebook"],correctChoice:0,explanation:"He takes a ring of keys from his pocket. He points to one key, then another.",difficulty:2},{id:"ch06_q03",chapterId:"la-casa-delle-finestre-06",type:"direct",question:"What does Quinto say about the upper floors?",choices:["He does not go upstairs. Never.","He sleeps there at night","Alme has the only key"],correctChoice:0,explanation:"He says: Non vado al piano di sopra. Mai.",difficulty:2},{id:"ch06_q04",chapterId:"la-casa-delle-finestre-06",type:"inference",question:"How does Quinto say \u201cLa scuola \xe8 vuota\u201d?",choices:["Toward the gate, without looking at Irene","With a smile, looking her in the eye","In a letter to Alme"],correctChoice:0,explanation:"He speaks toward the gate, not toward Irene. He does not look at her when he says it.",difficulty:2}]}},1009,[]);
__d(function(e,a,n,r,t,o,i){t.exports={id:"la-casa-delle-finestre-07",storyId:"la-casa-delle-finestre",number:7,title:"The timetable",titleIt:"L'orario",difficultyLevel:2,locationIds:["scatole-comune","mansarda-irene"],characterIds:["irene-colombo"],events:[{id:"ev-la-casa-delle-finestre-07",summary:"Irene finds an old timetable among allowed papers. The two pages coincide: light numbers and room numbers. One cell is circled: the room that faces her attic. She does not know why, or who.",characterIds:["irene-colombo"],locationIds:["scatole-comune","mansarda-irene"],rememberedFacts:["Irene finds a photocopy of an old timetable","The two pages coincide: Monday 3-4-5 and Tuesday 3-4-8 match the rooms","She still does not know who carries the lamp","One cell is circled: room two, which faces her attic"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Al comune Irene scende di nuovo alle scatole.",speakerId:null,kind:"narration",lemmas:["al","comune","irene","scendere","di","nuovo","alle","scatola"]},{id:"s02",text:"Oggi lavora sulle carte permesse, non sull'altra cartella.",speakerId:null,kind:"narration",lemmas:["oggi","lavorare","sulle","carta","permesso","non","altro","cartella"]},{id:"s03",text:"La cartella chiusa resta accanto al muro.",speakerId:null,kind:"narration",lemmas:["la","cartella","chiudere","restare","accanto","al","muro"]},{id:"s04",text:"Irene non la tocca.",speakerId:null,kind:"narration",lemmas:["irene","non","la","toccare"]},{id:"s05",text:"Apre una scatola di Alme e scansiona.",speakerId:null,kind:"narration",lemmas:["aprire","una","scatola","di","alme","e","scansionare"]},{id:"s06",text:"Liste, date, classi. Niente di strano.",speakerId:null,kind:"narration",lemmas:["lista","data","classe","niente","di","strano"]},{id:"s07",text:"Poi, in fondo, trova un foglio diverso.",speakerId:null,kind:"narration",lemmas:["poi","in","fondo","trovare","un","foglio","diverso"]},{id:"s08",text:"\xc8 una fotocopia, un po' chiara.",speakerId:null,kind:"narration",lemmas:["essere","una","fotocopia","un","po","chiaro"]},{id:"s09",text:"Irene l'ha trovata tra carte vecchie, non nella cartella vietata.",speakerId:null,kind:"narration",lemmas:["irene","avere","trovare","tra","carta","vecchio","non","nella","cartella","vietare"]},{id:"s10",text:"In alto c'\xe8 una parola: orario.",speakerId:null,kind:"narration",lemmas:["in","alto","ce","una","parola","orario"]},{id:"s11",text:"Sotto: scuola media, ultimo anno.",speakerId:null,kind:"narration",lemmas:["sotto","scuola","medio","ultimo","anno"]},{id:"s12",text:"Irene ha letto due volte.",speakerId:null,kind:"narration",lemmas:["irene","avere","leggere","due","volta"]},{id:"s13",text:"Quindi mette il foglio da parte, per dopo.",speakerId:null,kind:"narration",lemmas:["quindi","mettere","il","foglio","da","parte","per","dopo"]},{id:"s14",text:"Quando Alme passa in corridoio, Irene scansiona un'altra lista.",speakerId:null,kind:"narration",lemmas:["quando","alme","passare","in","corridoio","irene","scansionare","altro","lista"]},{id:"s15",text:"Alme ha detto: non deve leggere tutto.",speakerId:null,kind:"narration",lemmas:["alme","avere","dire","non","dovere","leggere","tutto"]},{id:"s16",text:"Per\xf2 questo \xe8 un orario. \xc8 una carta della scuola.",speakerId:null,kind:"narration",lemmas:["pero","questo","essere","un","orario","essere","una","carta","della","scuola"]}]},{id:"p2",order:2,sentences:[{id:"s17",text:"A mezzogiorno Irene esce.",speakerId:null,kind:"narration",lemmas:["a","mezzogiorno","irene","uscire"]},{id:"s18",text:"Ha messo la fotocopia tra le sue carte, con calma.",speakerId:null,kind:"narration",lemmas:["avere","mettere","la","fotocopia","tra","le","suo","carta","con","calma"]},{id:"s19",text:"\xc8 un orario vecchio, in una scatola aperta.",speakerId:null,kind:"narration",lemmas:["essere","un","orario","vecchio","in","una","scatola","aprire"]},{id:"s20",text:"A casa apre il quaderno e la fotocopia sullo stesso tavolo.",speakerId:null,kind:"narration",lemmas:["a","casa","aprire","il","quaderno","e","la","fotocopia","sullo","stesso","tavolo"]},{id:"s21",text:"Mette la fotocopia a sinistra, il quaderno a destra.",speakerId:null,kind:"narration",lemmas:["mettere","la","fotocopia","a","sinistra","il","quaderno","a","destra"]},{id:"s22",text:"Il tavolo \xe8 piccolo. Le due pagine ci stanno.",speakerId:null,kind:"narration",lemmas:["il","tavolo","essere","piccolo","le","due","pagina","ci","stare"]},{id:"s23",text:"Quando guarda l'orario, vede classi e ore.",speakerId:null,kind:"narration",lemmas:["quando","guardare","orario","vedere","classe","e","ora"]},{id:"s24",text:"Luned\xec, ore nove: classe 1A, stanza due.",speakerId:null,kind:"narration",lemmas:["lunedi","ora","nove","classe","1A","stanza","due"]},{id:"s25",text:"Poi, dopo, classe 1B, stanza tre.",speakerId:null,kind:"narration",lemmas:["poi","dopo","classe","1B","stanza","tre"]},{id:"s26",text:"Poi classe 2A, stanza quattro.",speakerId:null,kind:"narration",lemmas:["poi","classe","2A","stanza","quattro"]},{id:"s27",text:"Marted\xec, ore nove: di nuovo 1A, stanza due.",speakerId:null,kind:"narration",lemmas:["martedi","ora","nove","di","nuovo","1A","stanza","due"]},{id:"s28",text:"Poi 1B, stanza tre.",speakerId:null,kind:"narration",lemmas:["poi","1B","stanza","tre"]},{id:"s29",text:"Poi, per\xf2, classe 3C, stanza otto, piano tre.",speakerId:null,kind:"narration",lemmas:["poi","pero","classe","3C","stanza","otto","piano","tre"]}]},{id:"p3",order:3,sentences:[{id:"s30",text:"Irene prende la penna.",speakerId:null,kind:"narration",lemmas:["irene","prendere","la","penna"]},{id:"s31",text:"Mentre guarda il disegno della griglia, mette i numeri delle stanze.",speakerId:null,kind:"narration",lemmas:["mentre","guardare","il","disegno","della","griglia","mettere","i","numero","delle","stanza"]},{id:"s32",text:"Stanza due: finestra tre, piano due.",speakerId:null,kind:"narration",lemmas:["stanza","due","finestra","tre","piano","due"]},{id:"s33",text:"Stanza tre: finestra quattro.",speakerId:null,kind:"narration",lemmas:["stanza","tre","finestra","quattro"]},{id:"s34",text:"Stanza quattro: finestra cinque.",speakerId:null,kind:"narration",lemmas:["stanza","quattro","finestra","cinque"]},{id:"s35",text:"Stanza otto: finestra otto, piano tre.",speakerId:null,kind:"narration",lemmas:["stanza","otto","finestra","otto","piano","tre"]},{id:"s36",text:"Poi apre la pagina delle luci.",speakerId:null,kind:"narration",lemmas:["poi","aprire","la","pagina","delle","luce"]},{id:"s37",text:"Guarda una pagina, poi l'altra.",speakerId:null,kind:"narration",lemmas:["guardare","una","pagina","poi","altro"]},{id:"s38",text:"Luned\xec, sull'orario: stanza due, tre, quattro.",speakerId:null,kind:"narration",lemmas:["lunedi","orario","stanza","due","tre","quattro"]},{id:"s39",text:"Luned\xec, sulle luci: tre, poi quattro, poi cinque.",speakerId:null,kind:"narration",lemmas:["lunedi","sulle","luce","tre","poi","quattro","poi","cinque"]},{id:"s40",text:"Marted\xec, sull'orario: stanza due, tre, otto.",speakerId:null,kind:"narration",lemmas:["martedi","orario","stanza","due","tre","otto"]},{id:"s41",text:"Marted\xec, sulle luci: tre, poi quattro, poi otto.",speakerId:null,kind:"narration",lemmas:["martedi","sulle","luce","tre","poi","quattro","poi","otto"]},{id:"s42",text:"Le due pagine coincidono.",speakerId:null,kind:"narration",lemmas:["le","due","pagina","coincidere"]},{id:"s43",text:"Irene scrive i numeri uno sotto l'altro, senza una frase.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","i","numero","uno","sotto","altro","senza","una","frase"]},{id:"s44",text:"Irene non sa ancora perch\xe9.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","ancora","perche"]},{id:"s45",text:"Non sa chi porta la luce.",speakerId:null,kind:"narration",lemmas:["non","sapere","chi","portare","la","luce"]},{id:"s46",text:"Nessun nome sull'orario, solo classi e stanze.",speakerId:null,kind:"narration",lemmas:["nessuno","nome","orario","solo","classe","e","stanza"]}]},{id:"p4",order:4,sentences:[{id:"s47",text:"Irene rilegge il foglio una volta ancora.",speakerId:null,kind:"narration",lemmas:["irene","rileggere","il","foglio","una","volta","ancora"]},{id:"s48",text:"In una casella c'\xe8 un cerchio, a penna vecchia.",speakerId:null,kind:"narration",lemmas:["in","una","casella","ce","un","cerchio","a","penna","vecchio"]},{id:"s49",text:"Non \xe8 la sua penna.",speakerId:null,kind:"narration",lemmas:["non","essere","la","suo","penna"]},{id:"s50",text:"Il cerchio \xe8 sulla stanza due, luned\xec, ore nove.",speakerId:null,kind:"narration",lemmas:["il","cerchio","essere","sulla","stanza","due","lunedi","ora","nove"]},{id:"s51",text:"Irene guarda il disegno.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","disegno"]},{id:"s52",text:"Stanza due \xe8 finestra tre.",speakerId:null,kind:"narration",lemmas:["stanza","due","essere","finestra","tre"]},{id:"s53",text:"Finestra tre \xe8 di fronte alla mansarda.",speakerId:null,kind:"narration",lemmas:["finestra","tre","essere","di","fronte","alla","mansarda"]},{id:"s54",text:"Irene va alla finestra e guarda.",speakerId:null,kind:"narration",lemmas:["irene","andare","alla","finestra","e","guardare"]},{id:"s55",text:"S\xec. Quella stanza \xe8 proprio di fronte.",speakerId:null,kind:"narration",lemmas:["si_yes","quello","stanza","essere","proprio","di","fronte"]},{id:"s56",text:"Qualcuno ha cerchiato quella stanza, anni fa.",speakerId:null,kind:"narration",lemmas:["qualcuno","avere","cerchiare","quello","stanza","anno","fa"]},{id:"s57",text:"Irene non capisce perch\xe9.",speakerId:null,kind:"narration",lemmas:["irene","non","capire","perche"]},{id:"s58",text:"Ha solo un orario, e le luci che tornano.",speakerId:null,kind:"narration",lemmas:["avere","solo","un","orario","e","le","luce","che","tornare"]},{id:"s59",text:"Chiude il quaderno sopra la fotocopia.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno","sopra","la","fotocopia"]}]}],questions:[{id:"ch07_q01",chapterId:"la-casa-delle-finestre-07",type:"event",question:"What does Irene find in the allowed box?",choices:["A photocopy of an old timetable","The non scansionare folder already open","Quinto\u2019s keys"],correctChoice:0,explanation:"At the back of a box she finds a faint photocopy. The word at the top is orario.",difficulty:2},{id:"ch07_q02",chapterId:"la-casa-delle-finestre-07",type:"direct",question:"What does Irene notice about the two pages?",choices:["They coincide: the numbers look the same","The lights are random and do not match","They only happen on Mimmo\u2019s video"],correctChoice:0,explanation:"She looks at one page, then the other. Le due pagine coincidono. She does not know why.",difficulty:2},{id:"ch07_q03",chapterId:"la-casa-delle-finestre-07",type:"direct",question:"Does Irene know who carries the light?",choices:["No. There is no name on the timetable","Yes. It is Quinto","Yes. It is Mimmo"],correctChoice:0,explanation:"The sheet has classes and rooms, not a person\u2019s name.",difficulty:2},{id:"ch07_q04",chapterId:"la-casa-delle-finestre-07",type:"inference",question:"What is special about the circled cell?",choices:["It is room two, the room that faces Irene\u2019s attic","It tells her to call the Carabinieri","It is Alme\u2019s office number"],correctChoice:0,explanation:"The old circle is on room two at nine on Monday. That is window three, opposite the mansarda.",difficulty:2}]}},1010,[]);
__d(function(e,a,n,r,s,i,t){s.exports={id:"la-casa-delle-finestre-08",storyId:"la-casa-delle-finestre",number:8,title:"She is thinking of me",titleIt:"Lei pensa a me",locationIds:["mansarda-irene","scuola-media"],characterIds:["irene-colombo"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-08",summary:"After the two pages coincide, Irene watches on purpose. The light reaches the facing window and stops, then goes out. She feels seen. She may be wrong. She does not signal.",characterIds:["irene-colombo"],locationIds:["mansarda-irene","scuola-media"],rememberedFacts:["Irene stands at her window on purpose","The light reaches the facing window and stops","She feels seen, but she may be wrong","She does not signal back"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Le due pagine coincidono. Irene lo sa ancora.",speakerId:null,kind:"narration",lemmas:["le","due","pagina","coincidere","irene","lo","sapere","ancora"]},{id:"s02",text:"Per\xf2 le pagine non dicono se qualcuno la vede.",speakerId:null,kind:"narration",lemmas:["pero","le","pagina","non","dire","se","qualcuno","la","vedere"]},{id:"s03",text:"Di sera si mette alla finestra, di proposito.",speakerId:null,kind:"narration",lemmas:["di","sera","si","mettere","alla","finestra","di","proposito"]},{id:"s04",text:"Finestra tre \xe8 di fronte. \xc8 la stanza due, sul foglio.",speakerId:null,kind:"narration",lemmas:["finestra","tre","essere","di","fronte","essere","la","stanza","due","sul","foglio"]},{id:"s05",text:"Il quaderno resta chiuso sul tavolo, per ora.",speakerId:null,kind:"narration",lemmas:["il","quaderno","restare","chiudere","sul","tavolo","per","ora"]},{id:"s06",text:"Stasera non conta prima. Guarda solo.",speakerId:null,kind:"narration",lemmas:["stasera","non","contare","prima","guardare","solo"]},{id:"s07",text:"Ha spento la luce della stanza.",speakerId:null,kind:"narration",lemmas:["avere","spegnere","la","luce","della","stanza"]},{id:"s08",text:"Fuori \xe8 buio. Nessuno cammina in strada.",speakerId:null,kind:"narration",lemmas:["fuori","essere","buio","nessuno","camminare","in","strada"]},{id:"s09",text:"Sembra vuota, la scuola.",speakerId:null,kind:"narration",lemmas:["sembrare","vuoto","la","scuola"]},{id:"s10",text:"Irene aspetta le nove.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","le","nove"]},{id:"s11",text:"Sono le nove meno cinque. Poi le nove.",speakerId:null,kind:"narration",lemmas:["essere","le","nove","meno","cinque","poi","le","nove"]},{id:"s12",text:"Sulle pagine, a quest'ora, c'era gi\xe0 la prima luce.",speakerId:null,kind:"narration",lemmas:["sulle","pagina","a","ora","ce","gia","la","primo","luce"]}]},{id:"p2",order:2,sentences:[{id:"s13",text:"Mentre guarda, vede una luce.",speakerId:null,kind:"narration",lemmas:["mentre","guardare","vedere","una","luce"]},{id:"s14",text:"Finestra quattro, poi finestra cinque.",speakerId:null,kind:"narration",lemmas:["finestra","quattro","poi","finestra","cinque"]},{id:"s15",text:"Sulle pagine, luned\xec era tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["sulle","pagina","lunedi","essere","tre","quattro","cinque"]},{id:"s16",text:"Stasera la luce non inizia da tre.",speakerId:null,kind:"narration",lemmas:["stasera","la","luce","non","iniziare","da","tre"]},{id:"s17",text:"Irene non si muove.",speakerId:null,kind:"narration",lemmas:["irene","non","si","muovere"]},{id:"s18",text:"Poi la luce \xe8 alla finestra tre. Di fronte.",speakerId:null,kind:"narration",lemmas:["poi","la","luce","essere","alla","finestra","tre","di","fronte"]},{id:"s19",text:"Irene aspetta che vada oltre, come sulle pagine.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","che","andare","oltre","come","sulle","pagina"]},{id:"s20",text:"La luce non va oltre.",speakerId:null,kind:"narration",lemmas:["la","luce","non","andare","oltre"]},{id:"s21",text:"Si ferma.",speakerId:null,kind:"narration",lemmas:["si","fermare"]},{id:"s22",text:"Irene ricorda i numeri di luned\xec: tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["irene","ricordare","i","numero","di","lunedi","tre","quattro","cinque"]},{id:"s23",text:"Ricorda marted\xec: tre, quattro, otto.",speakerId:null,kind:"narration",lemmas:["ricordare","martedi","tre","quattro","otto"]},{id:"s24",text:"Stasera: quattro, cinque, poi tre. Poi niente.",speakerId:null,kind:"narration",lemmas:["stasera","quattro","cinque","poi","tre","poi","niente"]},{id:"s25",text:"Questa pausa non \xe8 sul foglio.",speakerId:null,kind:"narration",lemmas:["questo","pausa","non","essere","sul","foglio"]},{id:"s26",text:"Le pagine coincidono sulle stanze. Non su questa attesa.",speakerId:null,kind:"narration",lemmas:["le","pagina","coincidere","sulle","stanza","non","su","questo","attesa"]},{id:"s27",text:"Irene tiene la tenda con una mano.",speakerId:null,kind:"narration",lemmas:["irene","tenere","la","tenda","con","una","mano"]}]},{id:"p3",order:3,sentences:[{id:"s28",text:"Un minuto. Due. Tre, forse.",speakerId:null,kind:"narration",lemmas:["un","minuto","due","tre","forse"]},{id:"s29",text:"Irene conta piano, senza voce.",speakerId:null,kind:"narration",lemmas:["irene","contare","piano","senza","voce"]},{id:"s30",text:"La luce resta.",speakerId:null,kind:"narration",lemmas:["la","luce","restare"]},{id:"s31",text:"Sembra che qualcuno \xe8 l\xec.",speakerId:null,kind:"narration",lemmas:["sembrare","che","qualcuno","essere","li"]},{id:"s32",text:"Sembra che guarda verso la mansarda.",speakerId:null,kind:"narration",lemmas:["sembrare","che","guardare","verso","la","mansarda"]},{id:"s33",text:"Forse. Forse no.",speakerId:null,kind:"narration",lemmas:["forse","forse","no"]},{id:"s34",text:"Forse la luce \xe8 solo ferma.",speakerId:null,kind:"narration",lemmas:["forse","la","luce","essere","solo","fermo"]},{id:"s35",text:"Se qualcuno \xe8 l\xec, mi vede, pensa Irene.",speakerId:null,kind:"narration",lemmas:["se","qualcuno","essere","li","mi","vedere","pensare","irene"]},{id:"s36",text:"Se nessuno \xe8 l\xec, \xe8 solo una luce.",speakerId:null,kind:"narration",lemmas:["se","nessuno","essere","li","essere","solo","una","luce"]},{id:"s37",text:"Le due pagine non rispondono.",speakerId:null,kind:"narration",lemmas:["le","due","pagina","non","rispondere"]},{id:"s38",text:"Irene fa un passo indietro. Poi un altro.",speakerId:null,kind:"narration",lemmas:["irene","fare","un","passo","indietro","poi","un","altro"]},{id:"s39",text:"Non accende la sua luce. Non bussa sul vetro.",speakerId:null,kind:"narration",lemmas:["non","accendere","la","suo","luce","non","bussare","sul","vetro"]},{id:"s40",text:"Per\xf2 resta vicino alla finestra.",speakerId:null,kind:"narration",lemmas:["pero","restare","vicino","alla","finestra"]},{id:"s41",text:"Il cuore va in fretta. Le mani no, quasi.",speakerId:null,kind:"narration",lemmas:["il","cuore","andare","in","fretta","le","mano","no","quasi"]},{id:"s42",text:"Nessuno chiama. Nessuno parla.",speakerId:null,kind:"narration",lemmas:["nessuno","chiamare","nessuno","parlare"]}]},{id:"p4",order:4,sentences:[{id:"s43",text:"Poi, dopo tanto, la luce si spegne.",speakerId:null,kind:"narration",lemmas:["poi","dopo","tanto","la","luce","si","spegnere"]},{id:"s44",text:"Non va avanti. Non torna.",speakerId:null,kind:"narration",lemmas:["non","andare","avanti","non","tornare"]},{id:"s45",text:"La finestra tre \xe8 scura.",speakerId:null,kind:"narration",lemmas:["la","finestra","tre","essere","scuro"]},{id:"s46",text:"Irene aspetta ancora cinque minuti. La luce non torna.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","ancora","cinque","minuto","la","luce","non","tornare"]},{id:"s47",text:"Di fronte, niente.",speakerId:null,kind:"narration",lemmas:["di","fronte","niente"]},{id:"s48",text:"Qualcuno l'ha vista? Non lo sa.",speakerId:null,kind:"narration",lemmas:["qualcuno","avere","vedere","non","lo","sapere"]},{id:"s49",text:"Irene non sa se la pausa era per lei.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","se","la","pausa","essere","per","lei"]},{id:"s50",text:"Apre il quaderno.",speakerId:null,kind:"narration",lemmas:["aprire","il","quaderno"]},{id:"s51",text:"Scrive: finestra tre, si ferma, poi buio.",speakerId:null,kind:"narration",lemmas:["scrivere","finestra","tre","si","fermare","poi","buio"]},{id:"s52",text:"Scrive anche: non \xe8 sulle pagine.",speakerId:null,kind:"narration",lemmas:["scrivere","anche","non","essere","sulle","pagina"]},{id:"s53",text:"Poi scrive: forse per me.",speakerId:null,kind:"narration",lemmas:["poi","scrivere","forse","per","me"]},{id:"s54",text:"Poi cancella le ultime tre parole.",speakerId:null,kind:"narration",lemmas:["poi","cancellare","le","ultimo","tre","parola"]},{id:"s55",text:"Lascia la pausa. Non scrive il perch\xe9.",speakerId:null,kind:"narration",lemmas:["lasciare","la","pausa","non","scrivere","il","perche"]}]}],questions:[{id:"ch08_q01",chapterId:"la-casa-delle-finestre-08",type:"event",question:"Why does Irene stand at the window tonight?",choices:["On purpose, after the two pages coincide","Because Mimmo asked her to film","Because Alme sent her"],correctChoice:0,explanation:"The pages coincide, but they do not say whether someone sees her. She watches on purpose.",difficulty:2},{id:"ch08_q02",chapterId:"la-casa-delle-finestre-08",type:"direct",question:"What does the light do at window three?",choices:["It stops. That pause is not on the sheet","It follows Monday exactly, then goes to eight","Irene\u2019s lamp answers it"],correctChoice:0,explanation:"She waits for it to go on, as on the pages. It stops. This pause is not on the sheet.",difficulty:2},{id:"ch08_q03",chapterId:"la-casa-delle-finestre-08",type:"inference",question:"Does Irene signal back?",choices:["No. She steps back and does not knock","Yes. She knocks on the glass","Yes. She calls Piva"],correctChoice:0,explanation:"She does not turn on her light. She does not knock.",difficulty:2},{id:"ch08_q04",chapterId:"la-casa-delle-finestre-08",type:"inference",question:"What does Irene keep in the notebook?",choices:["The pause, not the why","Sara\u2019s name","A message in Morse"],correctChoice:0,explanation:"She writes \u201cmaybe for me,\u201d then erases it. She leaves the pause. She does not write the why.",difficulty:2}]}},1011,[]);
__d(function(e,a,n,i,r,o,s){r.exports={id:"la-casa-delle-finestre-09",storyId:"la-casa-delle-finestre",number:9,title:"Yesterday",titleIt:"Ieri",locationIds:["mansarda-irene","comune","scuola-media"],characterIds:["irene-colombo"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-09",summary:"The pause is not on the timetable. Tonight there is no light. In the morning Irene finds a new pack of camping batteries by the gate: the lamp uses batteries, not the school\u2019s lights.",characterIds:["irene-colombo"],locationIds:["mansarda-irene","scuola-media"],rememberedFacts:["Last night the light paused, not on the timetable","Tonight there is no light","She finds a new pack of camping batteries by the school gate","The school lights are not on; someone is using batteries"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Stamattina Irene ha aperto il quaderno.",speakerId:null,kind:"narration",lemmas:["stamattina","irene","avere","aprire","il","quaderno"]},{id:"s02",text:"Le due pagine coincidono ancora: le stanze, i numeri.",speakerId:null,kind:"narration",lemmas:["le","due","pagina","coincidere","ancora","le","stanza","i","numero"]},{id:"s03",text:"Ieri la luce non ha seguito quelle pagine.",speakerId:null,kind:"narration",lemmas:["ieri","la","luce","non","avere","seguire","quello","pagina"]},{id:"s04",text:"Ha fatto quattro, cinque, poi tre. Poi si \xe8 fermata.",speakerId:null,kind:"narration",lemmas:["avere","fare","quattro","cinque","poi","tre","poi","si","essere","fermare"]},{id:"s05",text:"Lo ha scritto: si ferma, poi buio. Non \xe8 sul foglio.",speakerId:null,kind:"narration",lemmas:["lo","avere","scrivere","si","fermare","poi","buio","non","essere","sul","foglio"]},{id:"s06",text:"Ha cancellato forse per me. Quella riga non c'\xe8 pi\xf9.",speakerId:null,kind:"narration",lemmas:["avere","cancellare","forse","per","me","quello","riga","non","ce","piu"]},{id:"s07",text:"Resta la pausa. Resta un problema, non una risposta.",speakerId:null,kind:"narration",lemmas:["restare","la","pausa","restare","un","problema","non","una","risposta"]},{id:"s08",text:"Di solito, alle nove, c'\xe8 una luce. Ieri c'era, e si \xe8 fermata.",speakerId:null,kind:"narration",lemmas:["di","solito","alle","nove","ce","una","luce","ieri","ce","e","si","essere","fermare"]},{id:"s09",text:"Irene scrive una riga nuova: stasera controllo di nuovo.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","una","riga","nuovo","stasera","controllo","di","nuovo"]},{id:"s10",text:"Mette le due pagine dell'orario sotto questa pagina.",speakerId:null,kind:"narration",lemmas:["mettere","le","due","pagina","orario","sotto","questo","pagina"]},{id:"s11",text:"Prima coincidono. Poi c'\xe8 ieri. Due fatti, uno sotto l'altro.",speakerId:null,kind:"narration",lemmas:["prima","coincidere","poi","ce","ieri","due","fatto","uno","sotto","altro"]},{id:"s12",text:"Non scrive qualcuno. Non scrive perch\xe9.",speakerId:null,kind:"narration",lemmas:["non","scrivere","qualcuno","non","scrivere","perche"]},{id:"s13",text:"Poi \xe8 andata al comune, come ogni giorno.",speakerId:null,kind:"narration",lemmas:["poi","essere","andare","al","comune","come","ogni","giorno"]}]},{id:"p2",order:2,sentences:[{id:"s14",text:"Il lavoro \xe8 stato breve, ma lei ha fatto il lavoro.",speakerId:null,kind:"narration",lemmas:["il","lavoro","essere","stato","breve","ma","lei","avere","fare","il","lavoro"]},{id:"s15",text:"Ha scansionato liste. Date, nomi, niente di strano.",speakerId:null,kind:"narration",lemmas:["avere","scansionare","lista","data","nome","niente","di","strano"]},{id:"s16",text:"La cartella chiusa era ancora l\xec, accanto al muro.",speakerId:null,kind:"narration",lemmas:["la","cartella","chiudere","essere","ancora","li","accanto","al","muro"]},{id:"s17",text:"Irene l'ha guardata. Non l'ha aperta.",speakerId:null,kind:"narration",lemmas:["irene","avere","guardare","non","avere","aprire"]},{id:"s18",text:"Ieri c'era una pausa. Oggi c'\xe8 una cartella. Non \xe8 la stessa cosa.",speakerId:null,kind:"narration",lemmas:["ieri","ce","una","pausa","oggi","ce","una","cartella","non","essere","la","stesso","cosa"]},{id:"s19",text:"Alme ha sorriso e ha detto poco.",speakerId:null,kind:"narration",lemmas:["alme","avere","sorridere","e","avere","dire","poco"]},{id:"s20",text:"Irene non ha detto la pausa. Non ha detto ieri.",speakerId:null,kind:"narration",lemmas:["irene","non","avere","dire","la","pausa","non","avere","dire","ieri"]},{id:"s21",text:"Tornando a casa, passa davanti alla scuola di giorno.",speakerId:null,kind:"narration",lemmas:["tornare","a","casa","passare","davanti","alla","scuola","di","giorno"]},{id:"s22",text:"Le finestre sono vuote. Non c'\xe8 una luce. Non serve, di giorno.",speakerId:null,kind:"narration",lemmas:["le","finestra","essere","vuoto","non","ce","una","luce","non","servire","di","giorno"]},{id:"s23",text:"Sembra vuota, come dicono tutti.",speakerId:null,kind:"narration",lemmas:["sembrare","vuoto","come","dire","tutto"]}]},{id:"p3",order:3,sentences:[{id:"s24",text:"Quando \xe8 sera, Irene \xe8 di nuovo alla finestra, di proposito.",speakerId:null,kind:"narration",lemmas:["quando","essere","sera","irene","essere","di","nuovo","alla","finestra","di","proposito"]},{id:"s25",text:"Ha spento la luce della stanza, come ieri.",speakerId:null,kind:"narration",lemmas:["avere","spegnere","la","luce","della","stanza","come","ieri"]},{id:"s26",text:"Aspetta le nove. Poi le nove e dieci. Poi le nove e venti.",speakerId:null,kind:"narration",lemmas:["aspettare","le","nove","poi","le","nove","e","dieci","poi","le","nove","e","venti"]},{id:"s27",text:"Se la pausa era per lei, stasera qualcuno torna. O no.",speakerId:null,kind:"narration",lemmas:["se","la","pausa","essere","per","lei","stasera","qualcuno","tornare","o","no"]},{id:"s28",text:"Irene non sceglie. Guarda solo.",speakerId:null,kind:"narration",lemmas:["irene","non","scegliere","guardare","solo"]},{id:"s29",text:"Stasera non c'\xe8 una luce.",speakerId:null,kind:"narration",lemmas:["stasera","non","ce","una","luce"]},{id:"s30",text:"La scuola resta buia. Tutte le finestre sono scure.",speakerId:null,kind:"narration",lemmas:["la","scuola","restare","buio","tutto","le","finestra","essere","scuro"]},{id:"s31",text:"Di solito c'\xe8 una luce. Ieri si \xe8 fermata. Stasera niente.",speakerId:null,kind:"narration",lemmas:["di","solito","ce","una","luce","ieri","si","essere","fermare","stasera","niente"]},{id:"s32",text:"Quindi ieri non era un orario. Stasera non \xe8 un orario.",speakerId:null,kind:"narration",lemmas:["quindi","ieri","non","essere","un","orario","stasera","non","essere","un","orario"]},{id:"s33",text:"Irene aspetta ancora dieci minuti. Conta, piano, senza voce.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","ancora","dieci","minuto","contare","piano","senza","voce"]},{id:"s34",text:"Nessuno cammina. Nessuna luce. Nessuna pausa.",speakerId:null,kind:"narration",lemmas:["nessuno","camminare","nessuno","luce","nessuno","pausa"]},{id:"s35",text:"Apre il quaderno. Scrive: stasera niente.",speakerId:null,kind:"narration",lemmas:["aprire","il","quaderno","scrivere","stasera","niente"]},{id:"s36",text:"Non scrive forse. Non cancella ieri.",speakerId:null,kind:"narration",lemmas:["non","scrivere","forse","non","cancellare","ieri"]},{id:"s37",text:"Quindi va a letto tardi, con due sere diverse nella testa.",speakerId:null,kind:"narration",lemmas:["quindi","andare","a","letto","tardi","con","due","sera","diverso","nella","testa"]},{id:"s38",text:"Se ha sbagliato ieri, stasera lo dimostra. Se non ha sbagliato, stasera \xe8 un altro fatto.",speakerId:null,kind:"narration",lemmas:["se","avere","sbagliare","ieri","stasera","lo","dimostrare","se","non","avere","sbagliare","stasera","essere","un","altro","fatto"]}]},{id:"p4",order:4,sentences:[{id:"s39",text:"La mattina dopo Irene passa davanti alla scuola, presto.",speakerId:null,kind:"narration",lemmas:["la","mattina","dopo","irene","passare","davanti","alla","scuola","presto"]},{id:"s40",text:"Vicino al cancello c'\xe8 una cosa per terra, nel fosso.",speakerId:null,kind:"narration",lemmas:["vicino","al","cancello","ce","una","cosa","per","terra","nel","fosso"]},{id:"s41",text:"\xc8 una confezione. Dentro c'erano pile da campeggio.",speakerId:null,kind:"narration",lemmas:["essere","una","confezione","dentro","ce","pila","da","campeggio"]},{id:"s42",text:"Ora la confezione \xe8 vuota, o quasi.",speakerId:null,kind:"narration",lemmas:["ora","la","confezione","essere","vuoto","o","quasi"]},{id:"s43",text:"Irene la prende con due dita. Non \xe8 vecchia.",speakerId:null,kind:"narration",lemmas:["irene","la","prendere","con","due","dito","non","essere","vecchio"]},{id:"s44",text:"Non c'\xe8 polvere. Non c'\xe8 pioggia secca.",speakerId:null,kind:"narration",lemmas:["non","ce","polvere","non","ce","pioggia","secco"]},{id:"s45",text:"C'\xe8 un prezzo, piccolo, e una data recente.",speakerId:null,kind:"narration",lemmas:["ce","un","prezzo","piccolo","e","una","data","recente"]},{id:"s46",text:"Qualcuno ha comprato pile questa settimana.",speakerId:null,kind:"narration",lemmas:["qualcuno","avere","comprare","pila","questo","settimana"]},{id:"s47",text:"Irene guarda le finestre. Di giorno sono vuote. Di notte, ieri, c'era una luce.",speakerId:null,kind:"narration",lemmas:["irene","guardare","le","finestra","di","giorno","essere","vuoto","di","notte","ieri","ce","una","luce"]},{id:"s48",text:"Nella scuola chiusa le luci normali non si accendono.",speakerId:null,kind:"narration",lemmas:["nella","scuola","chiudere","le","luce","normale","non","si","accendere"]},{id:"s49",text:"Quindi quella luce non era la scuola. Era una luce da campeggio, con pile.",speakerId:null,kind:"narration",lemmas:["quindi","quello","luce","non","essere","la","scuola","essere","una","luce","da","campeggio","con","pila"]},{id:"s50",text:"Non \xe8 un video. Non \xe8 un fantasma. \xc8 una cosa che si compra.",speakerId:null,kind:"narration",lemmas:["non","essere","un","video","non","essere","un","fantasma","essere","una","cosa","che","si","comprare"]},{id:"s51",text:"Ieri sera non c'era luce. Per\xf2 le pile ci sono.",speakerId:null,kind:"narration",lemmas:["ieri","sera","non","ce","luce","pero","le","pila","ci","essere"]},{id:"s52",text:"Irene mette la confezione in tasca. Non entra. Non chiama nessuno.",speakerId:null,kind:"narration",lemmas:["irene","mettere","la","confezione","in","tasca","non","entrare","non","chiamare","nessuno"]},{id:"s53",text:"Guarda il cancello chiuso, poi va al lavoro.",speakerId:null,kind:"narration",lemmas:["guardare","il","cancello","chiudere","poi","andare","al","lavoro"]},{id:"s54",text:"Mimmo ha un video di giorno. Questa confezione \xe8 per la notte.",speakerId:null,kind:"narration",lemmas:["mimmo","avere","un","video","di","giorno","questo","confezione","essere","per","la","notte"]},{id:"s55",text:"Due storie diverse. Irene tiene quella di adesso, in tasca.",speakerId:null,kind:"narration",lemmas:["due","storia","diverso","irene","tenere","quello","di","adesso","in","tasca"]}]}],questions:[{id:"ch09_q01",chapterId:"la-casa-delle-finestre-09",type:"direct",question:"What did the light do the night before last, according to Irene\u2019s notes?",choices:["It paused at window three, not on the timetable","It followed Mimmo\u2019s video","There was no light that night"],correctChoice:0,explanation:"Four, five, then three. Then it stopped. Not on the sheet.",difficulty:2},{id:"ch09_q02",chapterId:"la-casa-delle-finestre-09",type:"event",question:"What happens when Irene watches again at night?",choices:["There is no light","The light pauses again","Quinto opens the gate"],correctChoice:0,explanation:"Usually there is a light. Tonight nothing.",difficulty:2},{id:"ch09_q03",chapterId:"la-casa-delle-finestre-09",type:"direct",question:"What does Irene find by the gate?",choices:["A pack for camping batteries","Sara\u2019s keys","A letter from Alme"],correctChoice:0,explanation:"A confezione for pile da campeggio, new, by the gate.",difficulty:2},{id:"ch09_q04",chapterId:"la-casa-delle-finestre-09",type:"inference",question:"What do the batteries suggest?",choices:["Someone bought a camping light this week; the school lights are not on","The school has electricity again","Mimmo left a camera"],correctChoice:0,explanation:"Ordinary lights do not come on. The lamp uses batteries.",difficulty:2}]}},1012,[]);
__d(function(e,a,n,r,i,o,l){i.exports={id:"la-casa-delle-finestre-10",storyId:"la-casa-delle-finestre",number:10,title:"Do not scan",titleIt:"Non scansionare",locationIds:["scatole-comune","ufficio-alme"],characterIds:["irene-colombo","alme"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-10",summary:"Irene works through allowed folders first, then opens non scansionare. Sara Neri reported cracks before the closure; the paper was kept apart. Alme asks if anything is odd. Irene says no.",characterIds:["irene-colombo","alme"],locationIds:["scatole-comune"],rememberedFacts:["Irene opens the folder marked non scansionare","Sara Neri wrote that the building had cracks before the closure","The report was kept apart and not scanned with the rest","Alme asks if she found anything odd; Irene says no"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Oggi Irene \xe8 sola gi\xf9, con le scatole.",speakerId:null,kind:"narration",lemmas:["oggi","irene","essere","solo","giu","con","le","scatola"]},{id:"s02",text:"Alme \xe8 su, in ufficio. Lo scanner \xe8 acceso.",speakerId:null,kind:"narration",lemmas:["alme","essere","su","in","ufficio","lo","scanner","essere","accendere"]},{id:"s03",text:"Prima fa il lavoro permesso. \xc8 il suo lavoro.",speakerId:null,kind:"narration",lemmas:["prima","fare","il","lavoro","permesso","essere","il","suo","lavoro"]},{id:"s04",text:"Apre tre cartelle normali. Dentro ci sono liste, date, timbri.",speakerId:null,kind:"narration",lemmas:["aprire","tre","cartella","normale","dentro","ci","essere","lista","data","timbro"]},{id:"s05",text:"Scansiona una pagina, poi un'altra. Conta. Scrive i numeri sul foglio del comune.",speakerId:null,kind:"narration",lemmas:["scansionare","una","pagina","poi","altro","contare","scrivere","i","numero","sul","foglio","del","comune"]},{id:"s06",text:"Niente di strano. Carte che devono stare insieme.",speakerId:null,kind:"narration",lemmas:["niente","di","strano","carta","che","dovere","stare","insieme"]},{id:"s07",text:"Rimette le tre cartelle in ordine, con i numeri giusti.",speakerId:null,kind:"narration",lemmas:["rimettere","le","tre","cartella","in","ordine","con","i","numero","giusto"]},{id:"s08",text:"Il comune vuole un archivio pulito. Irene sa fare questo.",speakerId:null,kind:"narration",lemmas:["il","comune","volere","un","archivio","pulito","irene","sapere","fare","questo"]},{id:"s09",text:"Poi guarda la cartella chiusa, accanto al muro.",speakerId:null,kind:"narration",lemmas:["poi","guardare","la","cartella","chiudere","accanto","al","muro"]},{id:"s10",text:"Il nastro \xe8 diverso. La carta \xe8 diversa. C'\xe8 ancora la riga: non scansionare.",speakerId:null,kind:"narration",lemmas:["il","nastro","essere","diverso","la","carta","essere","diverso","ce","ancora","la","riga","non","scansionare"]},{id:"s11",text:"Le altre cartelle hanno un timbro uguale. Questa no.",speakerId:null,kind:"narration",lemmas:["le","altro","cartella","avere","un","timbro","uguale","questo","no"]},{id:"s12",text:"Manca il timbro del comune. Manca il numero della lista.",speakerId:null,kind:"narration",lemmas:["mancare","il","timbro","del","comune","mancare","il","numero","della","lista"]},{id:"s13",text:"Qualcuno l'ha tenuta fuori dal lavoro normale.",speakerId:null,kind:"narration",lemmas:["qualcuno","avere","tenere","fuori","dal","lavoro","normale"]},{id:"s14",text:"Dovrei lasciarla, pensa. Per\xf2 stamattina c'erano le pile.",speakerId:null,kind:"narration",lemmas:["dovere","lasciare","pensare","pero","stamattina","ce","le","pila"]},{id:"s15",text:"Dovrei dirlo ad Alme. Per\xf2 Alme ha detto: viene da me.",speakerId:null,kind:"narration",lemmas:["dovere","dire","ad","alme","pero","alme","avere","dire","venire","da","me"]},{id:"s16",text:"Irene aspetta un minuto. Nessuno scende le scale.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","un","minuto","nessuno","scendere","le","scala"]},{id:"s17",text:"Irene apre la cartella.",speakerId:null,kind:"narration",lemmas:["irene","aprire","la","cartella"]}]},{id:"p2",order:2,sentences:[{id:"s18",text:"Dentro c'\xe8 una relazione, non lunga. Tre pagine.",speakerId:null,kind:"narration",lemmas:["dentro","ce","una","relazione","non","lungo","tre","pagina"]},{id:"s19",text:"In alto c'\xe8 un nome: Sara Neri, insegnante.",speakerId:null,kind:"narration",lemmas:["in","alto","ce","un","nome","sara","neri","insegnante"]},{id:"s20",text:"Ha scritto delle crepe nella scuola, prima della chiusura.",speakerId:null,kind:"narration",lemmas:["avere","scrivere","delle","crepa","nella","scuola","prima","della","chiusura"]},{id:"s21",text:"Il muro non \xe8 sicuro, dice la relazione. I bambini no.",speakerId:null,kind:"narration",lemmas:["il","muro","non","essere","sicuro","dire","la","relazione","i","bambino","no"]},{id:"s22",text:"Scrive anche: prima della chiusura, non dopo.",speakerId:null,kind:"narration",lemmas:["scrivere","anche","prima","della","chiusura","non","dopo"]},{id:"s23",text:"Nelle liste del comune la scuola \xe8 chiusa da due anni.",speakerId:null,kind:"narration",lemmas:["nelle","lista","del","comune","la","scuola","essere","chiudere","da","due","anno"]},{id:"s24",text:"Questa relazione \xe8 di prima. Qualcuno ha chiuso, e ha messo via la carta.",speakerId:null,kind:"narration",lemmas:["questo","relazione","essere","di","prima","qualcuno","avere","chiudere","e","avere","mettere","via","la","carta"]},{id:"s25",text:"Irene legge la prima pagina, poi la seconda, piano.",speakerId:null,kind:"narration",lemmas:["irene","leggere","la","primo","pagina","poi","la","secondo","piano"]},{id:"s26",text:"C'\xe8 una data, due anni fa, o poco pi\xf9. C'\xe8 una firma.",speakerId:null,kind:"narration",lemmas:["ce","una","data","due","anno","fa","o","poco","piu","ce","una","firma"]},{id:"s27",text:"Nelle altre scatole la scuola \xe8 chiusa, e basta.",speakerId:null,kind:"narration",lemmas:["nelle","altro","scatola","la","scuola","essere","chiudere","e","basta"]},{id:"s28",text:"Qui la scuola non \xe8 solo chiusa. Qui c'\xe8 un muro, e una paura.",speakerId:null,kind:"narration",lemmas:["qui","la","scuola","non","essere","solo","chiudere","qui","ce","un","muro","e","una","paura"]},{id:"s29",text:"Questa carta non \xe8 con le altre. Non \xe8 stata scansionata.",speakerId:null,kind:"narration",lemmas:["questo","carta","non","essere","con","le","altro","non","essere","stato","scansionare"]},{id:"s30",text:"Qualcuno l'ha messa da parte, di proposito.",speakerId:null,kind:"narration",lemmas:["qualcuno","avere","mettere","da","parte","di","proposito"]},{id:"s31",text:"Non \xe8 giusto, pensa Irene. Per\xf2 \xe8 solo una cartella.",speakerId:null,kind:"narration",lemmas:["non","essere","giusto","pensare","irene","pero","essere","solo","una","cartella"]},{id:"s32",text:"Apre il quaderno. Copia il nome. Copia: crepe. Copia la data.",speakerId:null,kind:"narration",lemmas:["aprire","il","quaderno","copiare","il","nome","copiare","crepa","copiare","la","data"]},{id:"s33",text:"Copia anche: non scansionare. Non come ordine. Come fatto.",speakerId:null,kind:"narration",lemmas:["copiare","anche","non","scansionare","non","come","ordine","come","fatto"]},{id:"s34",text:"Non copia tutto. Non \xe8 un avvocato. \xc8 un'archivista.",speakerId:null,kind:"narration",lemmas:["non","copiare","tutto","non","essere","un","avvocato","essere","archivista"]},{id:"s35",text:"Non mette la relazione sullo scanner. La chiude. La lascia dove era.",speakerId:null,kind:"narration",lemmas:["non","mettere","la","relazione","sullo","scanner","la","chiudere","la","lasciare","dove","essere"]},{id:"s36",text:"Cerca Sara Neri nelle altre scatole, in fretta, con calma.",speakerId:null,kind:"narration",lemmas:["cercare","sara","neri","nelle","altro","scatola","in","fretta","con","calma"]},{id:"s37",text:"Liste. Non trova altre foto di lei. Non trova altre relazioni.",speakerId:null,kind:"narration",lemmas:["lista","non","trovare","altro","foto","di","lei","non","trovare","altro","relazione"]},{id:"s38",text:"Quindi non \xe8 un archivio di Sara. \xc8 una carta nascosta.",speakerId:null,kind:"narration",lemmas:["quindi","non","essere","un","archivio","di","sara","essere","una","carta","nascosto"]}]},{id:"p3",order:3,sentences:[{id:"s39",text:"Quando alza gli occhi, Alme \xe8 alla porta.",speakerId:null,kind:"narration",lemmas:["quando","alzare","gli","occhio","alme","essere","alla","porta"]},{id:"s40",text:"Sorride. Non ha detto il suo nome, gi\xf9.",speakerId:null,kind:"narration",lemmas:["sorridere","non","avere","dire","il","suo","nome","giu"]},{id:"s41",text:"Quante cartelle, oggi?",speakerId:"alme",kind:"dialogue",lemmas:["quanto","cartella","oggi"]},{id:"s42",text:"Tre. Le normali.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["tre","le","normale"]},{id:"s43",text:"Non conta la quarta. Non \xe8 nelle tre. Non \xe8 nel foglio del comune.",speakerId:null,kind:"narration",lemmas:["non","contare","la","quarto","non","essere","nelle","tre","non","essere","nel","foglio","del","comune"]},{id:"s44",text:"Tutto bene?",speakerId:"alme",kind:"dialogue",lemmas:["tutto","bene"]},{id:"s45",text:"S\xec.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes"]},{id:"s46",text:"Ha trovato qualcosa di strano?",speakerId:"alme",kind:"dialogue",lemmas:["avere","trovare","qualcosa","di","strano"]},{id:"s47",text:"Alme parla piano, con cura. Guarda le scatole, non la cartella chiusa.",speakerId:null,kind:"narration",lemmas:["alme","parlare","piano","con","cura","guardare","le","scatola","non","la","cartella","chiudere"]},{id:"s48",text:"Irene guarda la cartella, poi Alme.",speakerId:null,kind:"narration",lemmas:["irene","guardare","la","cartella","poi","alme"]},{id:"s49",text:"No.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["no"]},{id:"s50",text:"\xc8 la prima volta che dice di no, cos\xec. Una bugia, piccola, chiara.",speakerId:null,kind:"narration",lemmas:["essere","la","primo","volta","che","dire","di","no","cosi","una","bugia","piccolo","chiaro"]},{id:"s51",text:"Dovrei dirlo, pensa. Per\xf2 ha detto no.",speakerId:null,kind:"narration",lemmas:["dovere","dire","pensare","pero","avere","dire","no"]},{id:"s52",text:"Alme non perde il sorriso.",speakerId:null,kind:"narration",lemmas:["alme","non","perdere","il","sorriso"]},{id:"s53",text:"Bene. Allora su, un caff\xe8.",speakerId:"alme",kind:"dialogue",lemmas:["bene","allora","su","un","caffe"]},{id:"s54",text:"Irene sale. Beve il caff\xe8. Il nome resta gi\xf9, nella cartella, e nel quaderno.",speakerId:null,kind:"narration",lemmas:["irene","salire","bere","il","caffe","il","nome","restare","giu","nella","cartella","e","nel","quaderno"]},{id:"s55",text:"Alme parla del contratto, dei giorni, dello scanner.",speakerId:null,kind:"narration",lemmas:["alme","parlare","del","contratto","dei","giorno","dello","scanner"]},{id:"s56",text:"Se c'\xe8 qualcosa di strano, vieni da me.",speakerId:"alme",kind:"dialogue",lemmas:["se","ce","qualcosa","di","strano","venire","da","me"]},{id:"s57",text:"Lo ha gi\xe0 detto. Lo dice di nuovo.",speakerId:null,kind:"narration",lemmas:["lo","avere","gia","dire","lo","dire","di","nuovo"]},{id:"s58",text:"Irene dice di s\xec. Ha gi\xe0 detto di no, gi\xf9.",speakerId:null,kind:"narration",lemmas:["irene","dire","di","si_yes","avere","gia","dire","di","no","giu"]},{id:"s59",text:"Dopo il caff\xe8 Irene scende di nuovo, un minuto.",speakerId:null,kind:"narration",lemmas:["dopo","il","caffe","irene","scendere","di","nuovo","un","minuto"]},{id:"s60",text:"La cartella \xe8 chiusa, come prima. Il nastro \xe8 al suo posto.",speakerId:null,kind:"narration",lemmas:["la","cartella","essere","chiudere","come","prima","il","nastro","essere","al","suo","posto"]},{id:"s61",text:"Nessuno deve vedere che l'ha aperta. \xc8 un pensiero da archivista, e da bugia.",speakerId:null,kind:"narration",lemmas:["nessuno","dovere","vedere","che","avere","aprire","essere","un","pensiero","da","archivista","e","da","bugia"]},{id:"s62",text:"Risale. Alme \xe8 ancora in ufficio. Non chiede perch\xe9 \xe8 scesa.",speakerId:null,kind:"narration",lemmas:["risalire","alme","essere","ancora","in","ufficio","non","chiedere","perche","essere","scendere"]}]}],questions:[{id:"ch10_q01",chapterId:"la-casa-delle-finestre-10",type:"event",question:"What does Irene do before she opens the forbidden folder?",choices:["She scans the allowed folders first","She gives the folder to Quinto","She scans the report at once"],correctChoice:0,explanation:"First she does the allowed work. Then she opens the closed folder.",difficulty:2},{id:"ch10_q02",chapterId:"la-casa-delle-finestre-10",type:"direct",question:"Who wrote the report about cracks?",choices:["Sara Neri, a teacher","Quinto","Mimmo"],correctChoice:0,explanation:"The name at the top is Sara Neri, insegnante.",difficulty:2},{id:"ch10_q03",chapterId:"la-casa-delle-finestre-10",type:"direct",question:"How is this paper different from the others?",choices:["It was kept apart and not scanned","It has the same stamp as the rest","Alme scanned it in front of Irene"],correctChoice:0,explanation:"Someone put it aside on purpose. It has not been scanned.",difficulty:2},{id:"ch10_q04",chapterId:"la-casa-delle-finestre-10",type:"inference",question:"What does Irene say when Alme asks if she found anything odd?",choices:["No","Yes, a report by Sara","She asks Alme to call Piva"],correctChoice:0,explanation:"Alme asks carefully. Irene says no. It is her first lie.",difficulty:2}]}},1013,[]);
__d(function(e,a,n,r,s,o,i){s.exports={id:"la-casa-delle-finestre-11",storyId:"la-casa-delle-finestre",number:11,title:"Sara",titleIt:"Sara",locationIds:["scatole-comune","via-della-scuola"],characterIds:["irene-colombo","sara-neri"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-11",summary:"A class photo shows Sara Neri by a window. A clerk says she wrote, stayed after the children, and was sent away for exaggerating. At night Irene might see the same woman on a bus, with a bag like paper.",characterIds:["irene-colombo"],locationIds:["scatole-comune","via-della-scuola"],rememberedFacts:["Sara Neri was a teacher here, in the last class photo","People say she wrote, stayed late, exaggerated, and was sent away","Irene is not sure she sees the same woman on a night bus","The woman\u2019s bag looks like paper, not shopping"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Nel pomeriggio Irene apre un'altra scatola, permessa.",speakerId:null,kind:"narration",lemmas:["nel","pomeriggio","irene","aprire","altro","scatola","permesso"]},{id:"s02",text:"Ci sono foto di classi, anni vecchi, nomi sotto.",speakerId:null,kind:"narration",lemmas:["ci","essere","foto","di","classe","anno","vecchio","nome","sotto"]},{id:"s03",text:"Una foto \xe8 dell'ultima classe, due anni fa, o poco pi\xf9.",speakerId:null,kind:"narration",lemmas:["una","foto","essere","ultimo","classe","due","anno","fa","o","poco","piu"]},{id:"s04",text:"Dietro gli studenti c'\xe8 un'insegnante.",speakerId:null,kind:"narration",lemmas:["dietro","gli","studente","ce","insegnante"]},{id:"s05",text:"Non \xe8 in centro. \xc8 di lato, vicino a una finestra.",speakerId:null,kind:"narration",lemmas:["non","essere","in","centro","essere","di","lato","vicino","a","una","finestra"]},{id:"s06",text:"Irene guarda il viso a lungo. Poi la finestra nella foto.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","viso","a","lungo","poi","la","finestra","nella","foto"]},{id:"s07",text:"Non sa quale stanza \xe8. Sa solo: una finestra, una scuola, un'insegnante.",speakerId:null,kind:"narration",lemmas:["non","sapere","quale","stanza","essere","sapere","solo","una","finestra","una","scuola","insegnante"]},{id:"s08",text:"Non \xe8 la sua mansarda, quella finestra. \xc8 di l\xe0, in una classe.",speakerId:null,kind:"narration",lemmas:["non","essere","la","suo","mansarda","quello","finestra","essere","di","la","in","una","classe"]},{id:"s09",text:"Sotto la foto c'\xe8 un nome piccolo: Sara Neri.",speakerId:null,kind:"narration",lemmas:["sotto","la","foto","ce","un","nome","piccolo","sara","neri"]},{id:"s10",text:"\xc8 la stessa persona della cartella. La stessa data, quasi.",speakerId:null,kind:"narration",lemmas:["essere","la","stesso","persona","della","cartella","la","stesso","data","quasi"]},{id:"s11",text:"Irene confronta, nella testa: data della relazione, data della foto.",speakerId:null,kind:"narration",lemmas:["irene","confrontare","nella","testa","data","della","relazione","data","della","foto"]},{id:"s12",text:"Vicino. Prima la carta. Poi la classe. Poi via.",speakerId:null,kind:"narration",lemmas:["vicino","prima","la","carta","poi","la","classe","poi","via"]},{id:"s13",text:"Irene non parla. Tiene la foto con due mani.",speakerId:null,kind:"narration",lemmas:["irene","non","parlare","tenere","la","foto","con","due","mano"]},{id:"s14",text:"Guarda le altre foto della scatola. Anni prima, altri visi, altre classi.",speakerId:null,kind:"narration",lemmas:["guardare","le","altro","foto","della","scatola","anno","prima","altro","viso","altro","classe"]},{id:"s15",text:"Sara Neri c'\xe8 solo alla fine. Ultima classe, ultima finestra.",speakerId:null,kind:"narration",lemmas:["sara","neri","ce","solo","alla","fine","ultimo","classe","ultimo","finestra"]},{id:"s16",text:"Non era sempre qui. Poi c'era. Poi l'hanno mandata via.",speakerId:null,kind:"narration",lemmas:["non","essere","sempre","qui","poi","ce","poi","avere","mandare","via"]}]},{id:"p2",order:2,sentences:[{id:"s17",text:"Un uomo dell'ufficio passa e vede la foto. Non \xe8 Alme.",speakerId:null,kind:"narration",lemmas:["un","uomo","ufficio","passare","e","vedere","la","foto","non","essere","alme"]},{id:"s18",text:"Ah, la Neri.",speakerId:null,kind:"narration",lemmas:["ah","la","neri"]},{id:"s19",text:"Dicevano che esagerava.",speakerId:null,kind:"narration",lemmas:["dire","che","esagerare"]},{id:"s20",text:"Scriveva. Restava dopo i bambini. Poi l'hanno mandata via.",speakerId:null,kind:"narration",lemmas:["scrivere","restare","dopo","i","bambino","poi","avere","mandare","via"]},{id:"s21",text:"Dicevano anche che portava carte a casa, dice l'uomo, gi\xe0 lontano.",speakerId:null,kind:"narration",lemmas:["dire","anche","che","portare","carta","a","casa","dire","uomo","gia","lontano"]},{id:"s22",text:"Irene non sa se \xe8 vero. Tiene la frase, come l'altra.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","se","essere","vero","tenere","la","frase","come","altro"]},{id:"s23",text:"Irene alza gli occhi.",speakerId:null,kind:"narration",lemmas:["irene","alzare","gli","occhio"]},{id:"s24",text:"Via, perch\xe9?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["via","perche"]},{id:"s25",text:"Irene sente la sua voce: troppo. Poi \xe8 tardi.",speakerId:null,kind:"narration",lemmas:["irene","sentire","la","suo","voce","troppo","poi","essere","tardi"]},{id:"s26",text:"Perch\xe9 esagerava, dice l'uomo. La scuola era la scuola. Basta.",speakerId:null,kind:"narration",lemmas:["perche","esagerare","dire","uomo","la","scuola","essere","la","scuola","basta"]},{id:"s27",text:"Poi prende un caff\xe8 e va.",speakerId:null,kind:"narration",lemmas:["poi","prendere","un","caffe","e","andare"]},{id:"s28",text:"Irene non chiede dove abita adesso. Non chiede della luce.",speakerId:null,kind:"narration",lemmas:["irene","non","chiedere","dove","abitare","adesso","non","chiedere","della","luce"]},{id:"s29",text:"Tiene tre cose: scriveva, restava, esagerava.",speakerId:null,kind:"narration",lemmas:["tenere","tre","cosa","scrivere","restare","esagerare"]},{id:"s30",text:"Scrivere era il suo lavoro, pensa Irene. Restare dopo i bambini, anche.",speakerId:null,kind:"narration",lemmas:["scrivere","essere","il","suo","lavoro","pensare","irene","restare","dopo","i","bambino","anche"]},{id:"s31",text:"Esagerava \xe8 la parola del paese. Non \xe8 una data. Non \xe8 una crepa.",speakerId:null,kind:"narration",lemmas:["esagerare","essere","la","parola","del","paese","non","essere","una","data","non","essere","una","crepa"]},{id:"s32",text:"La relazione c'\xe8. La foto c'\xe8. La frase del paese c'\xe8.",speakerId:null,kind:"narration",lemmas:["la","relazione","ce","la","foto","ce","la","frase","del","paese","ce"]},{id:"s33",text:"Mette la foto nella scatola, con calma. Non la scansiona.",speakerId:null,kind:"narration",lemmas:["mettere","la","foto","nella","scatola","con","calma","non","la","scansionare"]},{id:"s34",text:"Scrive nel quaderno: insegnante, ultima classe, finestra nella foto.",speakerId:null,kind:"narration",lemmas:["scrivere","nel","quaderno","insegnante","ultimo","classe","finestra","nella","foto"]},{id:"s35",text:"Non scrive: \xe8 la luce. Non lo sa.",speakerId:null,kind:"narration",lemmas:["non","scrivere","essere","la","luce","non","lo","sapere"]}]},{id:"p3",order:3,sentences:[{id:"s36",text:"Di sera Irene torna a casa a piedi.",speakerId:null,kind:"narration",lemmas:["di","sera","irene","tornare","a","casa","a","piedi"]},{id:"s37",text:"Non cerca Sara. Torna a casa. La fermata c'\xe8, sulla strada.",speakerId:null,kind:"narration",lemmas:["non","cercare","sara","tornare","a","casa","la","fermata","ce","sulla","strada"]},{id:"s38",text:"C'\xe8 una fermata dell'autobus, vicino alla piazza, prima della scuola.",speakerId:null,kind:"narration",lemmas:["ce","una","fermata","autobus","vicino","alla","piazza","prima","della","scuola"]},{id:"s39",text:"Irene si ferma perch\xe9 il semaforo \xe8 rosso, non perch\xe9 cerca.",speakerId:null,kind:"narration",lemmas:["irene","si","fermare","perche","il","semaforo","essere","rosso","non","perche","cercare"]},{id:"s40",text:"Poi vede la donna. Era gi\xe0 l\xec, o arriva ora: Irene non sa.",speakerId:null,kind:"narration",lemmas:["poi","vedere","la","donna","essere","gia","li","o","arrivare","ora","irene","non","sapere"]},{id:"s41",text:"Una donna aspetta. Ha una borsa grande, rigida.",speakerId:null,kind:"narration",lemmas:["una","donna","aspettare","avere","una","borsa","grande","rigido"]},{id:"s42",text:"Irene guarda il viso, di lato, come nella foto.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","viso","di","lato","come","nella","foto"]},{id:"s43",text:"Sembra la donna della foto. Forse. L'et\xe0, i capelli, il lato.",speakerId:null,kind:"narration",lemmas:["sembrare","la","donna","della","foto","forse","eta","i","capello","il","lato"]},{id:"s44",text:"Forse no. \xc8 sera, e la luce \xe8 poca.",speakerId:null,kind:"narration",lemmas:["forse","no","essere","sera","e","la","luce","essere","poco"]},{id:"s45",text:"La donna non guarda Irene. Guarda la scuola chiusa, un momento, poi la strada.",speakerId:null,kind:"narration",lemmas:["la","donna","non","guardare","irene","guardare","la","scuola","chiudere","un","momento","poi","la","strada"]},{id:"s46",text:"Non \xe8 un segnale. \xc8 uno sguardo. Irene non risponde, perch\xe9 non c'\xe8 niente da rispondere.",speakerId:null,kind:"narration",lemmas:["non","essere","un","segnale","essere","uno","sguardo","irene","non","rispondere","perche","non","ce","niente","da","rispondere"]},{id:"s47",text:"L'autobus arriva. La donna sale. Non corre. Non parla.",speakerId:null,kind:"narration",lemmas:["autobus","arrivare","la","donna","salire","non","correre","non","parlare"]},{id:"s48",text:"La borsa sembra pesante. Come carta, non come spesa.",speakerId:null,kind:"narration",lemmas:["la","borsa","sembrare","pesante","come","carta","non","come","spesa"]},{id:"s49",text:"Se portava carte a casa allora, forse porta carte adesso. Forse no.",speakerId:null,kind:"narration",lemmas:["se","portare","carta","a","casa","allora","forse","portare","carta","adesso","forse","no"]},{id:"s50",text:"Irene non \xe8 sicura. Non dice: \xe8 lei. Non dice: non \xe8 lei.",speakerId:null,kind:"narration",lemmas:["irene","non","essere","sicuro","non","dire","essere","lei","non","dire","non","essere","lei"]},{id:"s51",text:"Non prende l'autobus. Non chiama. Guarda partire l'autobus.",speakerId:null,kind:"narration",lemmas:["non","prendere","autobus","non","chiamare","guardare","partire","autobus"]},{id:"s52",text:"A casa scrive: forse Sara. Poi aggiunge: non so.",speakerId:null,kind:"narration",lemmas:["a","casa","scrivere","forse","sara","poi","aggiungere","non","sapere"]},{id:"s53",text:"Aggiunge anche: borsa come carta. Guarda la scuola, non me.",speakerId:null,kind:"narration",lemmas:["aggiungere","anche","borsa","come","carta","guardare","la","scuola","non","me"]},{id:"s54",text:"Non \xe8 una prova. \xc8 una sera. Irene lo sa.",speakerId:null,kind:"narration",lemmas:["non","essere","una","prova","essere","una","sera","irene","lo","sapere"]},{id:"s55",text:"Chiude il quaderno. Non chiede a Loredana.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno","non","chiedere","a","loredana"]},{id:"s56",text:"Domani c'\xe8 di nuovo il comune. Domani c'\xe8 di nuovo la foto, nella scatola.",speakerId:null,kind:"narration",lemmas:["domani","ce","di","nuovo","il","comune","domani","ce","di","nuovo","la","foto","nella","scatola"]},{id:"s57",text:"Che scriveva era vero: la relazione c'\xe8. Restava, esagerava: questo non lo sa.",speakerId:null,kind:"narration",lemmas:["che","scrivere","essere","vero","la","relazione","ce","restare","esagerare","questo","non","lo","sapere"]}]}],questions:[{id:"ch11_q01",chapterId:"la-casa-delle-finestre-11",type:"direct",question:"Where is Sara Neri in the class photo?",choices:["To the side, near a window, with the last class","In Irene\u2019s attic","Behind Alme\u2019s desk"],correctChoice:0,explanation:"She is not in the middle. She is near a window. The name is Sara Neri.",difficulty:2},{id:"ch11_q02",chapterId:"la-casa-delle-finestre-11",type:"character",question:"What does the clerk add to \u201cshe exaggerated\u201d?",choices:["That she wrote, stayed after the children, and was sent away","That she is still the head teacher","That she is Quinto\u2019s sister"],correctChoice:0,explanation:"She wrote. She stayed after the children. Then they sent her away.",difficulty:2},{id:"ch11_q03",chapterId:"la-casa-delle-finestre-11",type:"inference",question:"What might Irene see at the bus stop?",choices:["The same woman, maybe, looking at the school, with a bag like paper","Sara opening the school","Mimmo with a camera"],correctChoice:0,explanation:"The face might match. She looks at the school, not at Irene. The bag looks like paper. Irene writes: maybe Sara. I don\u2019t know.",difficulty:2}]}},1014,[]);
__d(function(e,a,n,r,s,i,o){s.exports={id:"la-casa-delle-finestre-12",storyId:"la-casa-delle-finestre",number:12,title:"The second floor",titleIt:"Il secondo piano",locationIds:["via-della-scuola","scuola-media","mansarda-irene"],characterIds:["irene-colombo","loredana"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-12",summary:"From the street Irene sees the lamp on the second floor, not at the facing window. A second light on her stairs is Loredana. Two buildings, two lights. She does not go in.",characterIds:["irene-colombo","loredana"],locationIds:["via-della-scuola","mansarda-irene"],rememberedFacts:["From the street she sees more than from the attic","The lamp is on the second floor, perhaps the teachers\u2019 room, not window three","A light on Irene\u2019s stairs is Loredana, who cannot sleep","Not every light is the lamp in the school"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Di sera Irene non sale subito in mansarda.",speakerId:null,kind:"narration",lemmas:["di","sera","irene","non","salire","subito","in","mansarda"]},{id:"s02",text:"Dalla mansarda vede solo la griglia di fronte: finestra tre, stanza due.",speakerId:null,kind:"narration",lemmas:["dalla","mansarda","vedere","solo","la","griglia","di","fronte","finestra","tre","stanza","due"]},{id:"s03",text:"Stasera vuole vedere altro. Resta in strada, di qua, davanti alla scuola.",speakerId:null,kind:"narration",lemmas:["stasera","volere","vedere","altro","restare","in","strada","di","qua","davanti","alla","scuola"]},{id:"s04",text:"Ha il quaderno. Ha il disegno della griglia. Lo tiene basso, sotto la luce della strada.",speakerId:null,kind:"narration",lemmas:["avere","il","quaderno","avere","il","disegno","della","griglia","lo","tenere","basso","sotto","la","luce","della","strada"]},{id:"s05",text:"Mette il disegno accanto al palazzo. I numeri e le finestre devono coincidere anche di qua.",speakerId:null,kind:"narration",lemmas:["mettere","il","disegno","accanto","al","palazzo","i","numero","e","le","finestra","dovere","coincidere","anche","di","qua"]},{id:"s06",text:"Da qua la griglia \xe8 pi\xf9 larga. Dalla mansarda si vede solo un pezzo.",speakerId:null,kind:"narration",lemmas:["da","qua","la","griglia","essere","piu","largo","dalla","mansarda","si","vedere","solo","un","pezzo"]},{id:"s07",text:"Irene sposta il foglio. Cerca la tre. La trova, di fronte a casa sua.",speakerId:null,kind:"narration",lemmas:["irene","spostare","il","foglio","cercare","la","tre","la","trovare","di","fronte","a","casa","suo"]},{id:"s08",text:"Non prova il cancello. Non entra. Sta di qua. La scuola \xe8 di l\xe0.",speakerId:null,kind:"narration",lemmas:["non","provare","il","cancello","non","entrare","stare","di","qua","la","scuola","essere","di","la"]},{id:"s09",text:"Conta i piani: piano terra, primo, secondo.",speakerId:null,kind:"narration",lemmas:["contare","i","piano","piano","terra","primo","secondo"]},{id:"s10",text:"Conta anche le finestre del secondo piano, da sinistra.",speakerId:null,kind:"narration",lemmas:["contare","anche","le","finestra","del","secondo","piano","da","sinistra"]},{id:"s11",text:"Tre \xe8 di fronte a lei, a casa. Quattro e cinque sono pi\xf9 in l\xe0.",speakerId:null,kind:"narration",lemmas:["tre","essere","di","fronte","a","lei","a","casa","quattro","e","cinque","essere","piu","in","la"]},{id:"s12",text:"La luce di stasera non \xe8 sulla tre. \xc8 oltre, verso destra.",speakerId:null,kind:"narration",lemmas:["la","luce","di","stasera","non","essere","sulla","tre","essere","oltre","verso","destra"]},{id:"s13",text:"Sul disegno, al secondo piano a destra, c'\xe8 la stanza delle prof, o cos\xec sembra.",speakerId:null,kind:"narration",lemmas:["sul","disegno","al","secondo","piano","a","destra","ce","la","stanza","delle","prof","o","cosi","sembrare"]},{id:"s14",text:"Finestra tre \xe8 pi\xf9 a sinistra. Di fronte alla mansarda.",speakerId:null,kind:"narration",lemmas:["finestra","tre","essere","piu","a","sinistra","di","fronte","alla","mansarda"]},{id:"s15",text:"Alle nove c'\xe8 una luce, al secondo piano, a destra.",speakerId:null,kind:"narration",lemmas:["alle","nove","ce","una","luce","al","secondo","piano","a","destra"]},{id:"s16",text:"Non \xe8 finestra tre. Non \xe8 la pausa di ieri. \xc8 un'altra stanza, di l\xe0.",speakerId:null,kind:"narration",lemmas:["non","essere","finestra","tre","non","essere","la","pausa","di","ieri","essere","altro","stanza","di","la"]},{id:"s17",text:"Quindi la luce non resta solo dove Irene pu\xf2 vederla da casa.",speakerId:null,kind:"narration",lemmas:["quindi","la","luce","non","restare","solo","dove","irene","potere","vedere","da","casa"]},{id:"s18",text:"Irene scrive: secondo piano, stanza delle prof, forse. Non finestra tre.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","secondo","piano","stanza","delle","prof","forse","non","finestra","tre"]},{id:"s19",text:"Non sale. Non chiama. Guarda solo, di qua.",speakerId:null,kind:"narration",lemmas:["non","salire","non","chiamare","guardare","solo","di","qua"]},{id:"s20",text:"Dalla mansarda, ieri, la luce era alla tre, di fronte.",speakerId:null,kind:"narration",lemmas:["dalla","mansarda","ieri","la","luce","essere","alla","tre","di","fronte"]},{id:"s21",text:"Dalla strada, stasera, la luce \xe8 al secondo piano, altrove.",speakerId:null,kind:"narration",lemmas:["dalla","strada","stasera","la","luce","essere","al","secondo","piano","altrove"]},{id:"s22",text:"Due punti di vista. Due stanze. La persona, se c'\xe8, si muove.",speakerId:null,kind:"narration",lemmas:["due","punto","di","vista","due","stanza","la","persona","se","ce","si","muovere"]}]},{id:"p2",order:2,sentences:[{id:"s23",text:"Poi una seconda luce si muove, dietro di lei.",speakerId:null,kind:"narration",lemmas:["poi","una","secondo","luce","si","muovere","dietro","di","lei"]},{id:"s24",text:"Per un momento pensa: risponde. Qualcuno viene.",speakerId:null,kind:"narration",lemmas:["per","un","momento","pensare","rispondere","qualcuno","venire"]},{id:"s25",text:"Poi capisce. Non \xe8 la scuola. \xc8 la sua casa, sulle scale, di qua.",speakerId:null,kind:"narration",lemmas:["poi","capire","non","essere","la","scuola","essere","la","suo","casa","sulle","scala","di","qua"]},{id:"s26",text:"Irene si gira. Il cuore va in fretta.",speakerId:null,kind:"narration",lemmas:["irene","si","girare","il","cuore","andare","in","fretta"]},{id:"s27",text:"Qualcuno scende, di qua, con una luce piccola.",speakerId:null,kind:"narration",lemmas:["qualcuno","scendere","di","qua","con","una","luce","piccolo"]},{id:"s28",text:"Non \xe8 una torcia da campeggio. \xc8 un telefono acceso.",speakerId:null,kind:"narration",lemmas:["non","essere","una","torcia","da","campeggio","essere","un","telefono","accendere"]},{id:"s29",text:"Loredana \xe8 in vestaglia. Ha i capelli in disordine.",speakerId:null,kind:"narration",lemmas:["loredana","essere","in","vestaglia","avere","i","capello","in","disordine"]},{id:"s30",text:"Irene.",speakerId:"loredana",kind:"dialogue",lemmas:["irene"]},{id:"s31",text:"Torna tardi.",speakerId:"loredana",kind:"dialogue",lemmas:["tornare","tardi"]},{id:"s32",text:"Lavoro, dice Irene. Non dice: la scuola.",speakerId:null,kind:"narration",lemmas:["lavoro","dire","irene","non","dire","la","scuola"]},{id:"s33",text:"Scusi. Non ho sentito. Guardavo di l\xe0.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["scusare","non","avere","sentire","guardare","di","la"]},{id:"s34",text:"Loredana abbassa il telefono. Non guarda la scuola.",speakerId:null,kind:"narration",lemmas:["loredana","abbassare","il","telefono","non","guardare","la","scuola"]},{id:"s35",text:"Controllo la strada. Non dormo.",speakerId:"loredana",kind:"dialogue",lemmas:["controllare","la","strada","non","dormire"]},{id:"s36",text:"La scuola\u2026",speakerId:"loredana",kind:"dialogue",lemmas:["la","scuola"]},{id:"s37",text:"Irene aspetta. Dovrei dire della luce, pensa. Non dice.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","dovere","dire","della","luce","pensare","non","dire"]},{id:"s38",text:"Non finisce la frase. Non dice vuota. Non dice piena.",speakerId:null,kind:"narration",lemmas:["non","finire","la","frase","non","dire","vuoto","non","dire","pieno"]},{id:"s39",text:"Irene guarda di l\xe0. La luce della scuola, al secondo piano, c'\xe8 ancora.",speakerId:null,kind:"narration",lemmas:["irene","guardare","di","la","la","luce","della","scuola","al","secondo","piano","ce","ancora"]},{id:"s40",text:"Loredana \xe8 di qua, sulle scale. La luce di l\xe0 resta accesa.",speakerId:null,kind:"narration",lemmas:["loredana","essere","di","qua","sulle","scala","la","luce","di","la","restare","accendere"]},{id:"s41",text:"Quindi Loredana non \xe8 quella luce. Sono due.",speakerId:null,kind:"narration",lemmas:["quindi","loredana","non","essere","quello","luce","essere","due"]},{id:"s42",text:"Loredana non la vede, o non vuole. Guarda Irene, poi le scale.",speakerId:null,kind:"narration",lemmas:["loredana","non","la","vedere","o","non","volere","guardare","irene","poi","le","scala"]},{id:"s43",text:"Buonanotte, dice piano, e sale.",speakerId:null,kind:"narration",lemmas:["buonanotte","dire","piano","e","salire"]},{id:"s44",text:"Irene resta di qua. Due luci. Due case. Non \xe8 la stessa cosa.",speakerId:null,kind:"narration",lemmas:["irene","restare","di","qua","due","luce","due","casa","non","essere","la","stesso","cosa"]},{id:"s45",text:"Scrive: luce scuola di l\xe0. Loredana di qua, sulle scale.",speakerId:null,kind:"narration",lemmas:["scrivere","luce","scuola","di","la","loredana","di","qua","sulle","scala"]},{id:"s46",text:"Poi sale anche lei. Non entra a scuola.",speakerId:null,kind:"narration",lemmas:["poi","salire","anche","lei","non","entrare","a","scuola"]},{id:"s47",text:"In mansarda apre il quaderno. Non scrive: Loredana aiuta.",speakerId:null,kind:"narration",lemmas:["in","mansarda","aprire","il","quaderno","non","scrivere","loredana","aiutare"]},{id:"s48",text:"Scrive solo dove sono le luci. Di qua. Di l\xe0.",speakerId:null,kind:"narration",lemmas:["scrivere","solo","dove","essere","le","luce","di","qua","di","la"]},{id:"s49",text:"Dalla mansarda, dopo, guarda di nuovo. Finestra tre \xe8 scura.",speakerId:null,kind:"narration",lemmas:["dalla","mansarda","dopo","guardare","di","nuovo","finestra","tre","essere","scuro"]},{id:"s50",text:"La luce del secondo piano, a destra, da qui si vede poco, o niente.",speakerId:null,kind:"narration",lemmas:["la","luce","del","secondo","piano","a","destra","da","qui","si","vedere","poco","o","niente"]},{id:"s51",text:"Quindi la strada serviva. La mansarda non basta.",speakerId:null,kind:"narration",lemmas:["quindi","la","strada","servire","la","mansarda","non","bastare"]},{id:"s52",text:"Domani, se c'\xe8 di nuovo una luce, sa dove stare: di qua, in strada, o di fronte, su.",speakerId:null,kind:"narration",lemmas:["domani","se","ce","di","nuovo","una","luce","sapere","dove","stare","di","qua","in","strada","o","di","fronte","su"]},{id:"s53",text:"Non entra. Non stasera. Ha visto abbastanza da qua.",speakerId:null,kind:"narration",lemmas:["non","entrare","non","stasera","avere","vedere","abbastanza","da","qua"]},{id:"s54",text:"Smette di guardare, per ora. La scuola resta di l\xe0, con la sua luce.",speakerId:null,kind:"narration",lemmas:["smettere","di","guardare","per","ora","la","scuola","restare","di","la","con","la","suo","luce"]}]}],questions:[{id:"ch12_q01",chapterId:"la-casa-delle-finestre-12",type:"direct",question:"Why does Irene watch from the street?",choices:["From the attic she only sees the facing windows","She has Quinto\u2019s key","Loredana told her to go in"],correctChoice:0,explanation:"From the attic she only sees the facing grid. Tonight she wants to see more.",difficulty:2},{id:"ch12_q02",chapterId:"la-casa-delle-finestre-12",type:"event",question:"Where is the lamp in the school tonight?",choices:["On the second floor to the right, not at window three","In Irene\u2019s attic","In the courtyard"],correctChoice:0,explanation:"At nine there is a light on the second floor, to the right. Not yesterday\u2019s pause.",difficulty:2},{id:"ch12_q03",chapterId:"la-casa-delle-finestre-12",type:"character",question:"Who is the light on Irene\u2019s stairs?",choices:["Loredana, who cannot sleep","Sara Neri with a camping lamp","Mimmo with a video"],correctChoice:0,explanation:"It is a phone, not a camping torch. Loredana is in a dressing gown.",difficulty:2},{id:"ch12_q04",chapterId:"la-casa-delle-finestre-12",type:"inference",question:"What does Irene understand about the two lights?",choices:["They belong to two buildings; not every light is the school lamp","Loredana works with the person in the school","She should enter tonight"],correctChoice:0,explanation:"Two lights. Two houses. School over there, Loredana on this side.",difficulty:2}]}},1015,[]);
__d(function(e,a,n,r,i,o,l){i.exports={id:"la-casa-delle-finestre-13",storyId:"la-casa-delle-finestre",number:13,title:"Loredana",titleIt:"Loredana",locationIds:["cucina-loredana","mansarda-irene"],characterIds:["irene-colombo","loredana"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-13",summary:"Loredana\u2019s daughter was in the last class. She wants the school forgotten. Irene\u2019s numbered windows hurt her. Loredana is not the night lamp.",characterIds:["irene-colombo","loredana"],locationIds:["cucina-loredana"],rememberedFacts:["Loredana\u2019s daughter was in the last class","Loredana wants no more talk of the school","Irene\u2019s numbered sketch hurts her","Loredana is not the night lamp"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"La mattina Irene scende piano, con il quaderno sotto il braccio.",speakerId:null,kind:"narration",lemmas:["la","mattina","irene","scendere","piano","con","il","quaderno","sotto","il","braccio"]},{id:"s02",text:"Non vuole parlare della luce. Non vuole parlare di Loredana sulle scale.",speakerId:null,kind:"narration",lemmas:["non","volere","parlare","della","luce","non","volere","parlare","di","loredana","sulle","scala"]},{id:"s03",text:"Loredana \xe8 in cucina. C'\xe8 il caff\xe8, e una tazza per Irene.",speakerId:null,kind:"narration",lemmas:["loredana","essere","in","cucina","ce","il","caffe","e","una","tazza","per","irene"]},{id:"s04",text:"Si sieda. Due minuti.",speakerId:"loredana",kind:"dialogue",lemmas:["si","sedere","due","minuto"]},{id:"s05",text:"Irene si siede. Il quaderno resta sul tavolo, chiuso, ma visibile.",speakerId:null,kind:"narration",lemmas:["irene","si","sedere","il","quaderno","restare","sul","tavolo","chiudere","ma","visibile"]},{id:"s06",text:"Loredana non guarda il quaderno. Guarda la finestra della cucina, di qua.",speakerId:null,kind:"narration",lemmas:["loredana","non","guardare","il","quaderno","guardare","la","finestra","della","cucina","di","qua"]},{id:"s07",text:"Ieri sera non dormivo. Lei lo sa.",speakerId:"loredana",kind:"dialogue",lemmas:["ieri","sera","non","dormire","lei","lo","sapere"]},{id:"s08",text:"Irene non corregge. Beve.",speakerId:null,kind:"narration",lemmas:["irene","non","correggere","bere"]},{id:"s09",text:"Mi dispiace.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["mi","dispiacere"]},{id:"s10",text:"Loredana versa il caff\xe8. Le mani tremano poco.",speakerId:null,kind:"narration",lemmas:["loredana","versare","il","caffe","le","mano","tremare","poco"]},{id:"s11",text:"Non \xe8 la vestaglia di ieri sera. \xc8 giorno. Per\xf2 gli occhi sono gli stessi.",speakerId:null,kind:"narration",lemmas:["non","essere","la","vestaglia","di","ieri","sera","essere","giorno","pero","gli","occhio","essere","gli","stesso"]},{id:"s12",text:"Irene tiene le mani intorno alla tazza. Il quaderno pesa sul tavolo.",speakerId:null,kind:"narration",lemmas:["irene","tenere","le","mano","intorno","alla","tazza","il","quaderno","pesare","sul","tavolo"]}]},{id:"p2",order:2,sentences:[{id:"s13",text:"Mia figlia era nell'ultima classe.",speakerId:"loredana",kind:"dialogue",lemmas:["mio","figlia","essere","ultimo","classe"]},{id:"s14",text:"Lo dice piano, come una data, non come un segreto.",speakerId:null,kind:"narration",lemmas:["lo","dire","piano","come","una","data","non","come","un","segreto"]},{id:"s15",text:"Andava a scuola di fronte. Tornava e parlava, parlava.",speakerId:"loredana",kind:"dialogue",lemmas:["andare","a","scuola","di","fronte","tornare","e","parlare","parlare"]},{id:"s16",text:"Parlava delle stanze, delle prof, delle finestre. Adesso no.",speakerId:"loredana",kind:"dialogue",lemmas:["parlare","delle","stanza","delle","prof","delle","finestra","adesso","no"]},{id:"s17",text:"Non \xe8 morta. Vive altrove. Per\xf2 quella scuola \xe8 finita.",speakerId:"loredana",kind:"dialogue",lemmas:["non","essere","morto","vivere","altrove","pero","quello","scuola","essere","finire"]},{id:"s18",text:"Adesso la scuola \xe8 chiusa. Lei non parla pi\xf9 di quelle stanze.",speakerId:"loredana",kind:"dialogue",lemmas:["adesso","la","scuola","essere","chiudere","lei","non","parlare","piu","di","quello","stanza"]},{id:"s19",text:"Irene ascolta. Non chiede il nome. Non chiede dove abita adesso.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","non","chiedere","il","nome","non","chiedere","dove","abitare","adesso"]},{id:"s20",text:"Voglio dimenticare quella scuola. Voglio che il paese dimentichi.",speakerId:"loredana",kind:"dialogue",lemmas:["volere","dimenticare","quello","scuola","volere","che","il","paese","dimenticare"]},{id:"s21",text:"Tutti dicono: \xe8 vuota. Io lo dico perch\xe9 ho paura, e perch\xe9 non voglio.",speakerId:"loredana",kind:"dialogue",lemmas:["tutto","dire","essere","vuoto","io","lo","dire","perche","avere","paura","e","perche","non","volere"]},{id:"s22",text:"Irene capisce una cosa nuova: vuota \xe8 anche una parola per non sentire.",speakerId:null,kind:"narration",lemmas:["irene","capire","una","cosa","nuovo","vuoto","essere","anche","una","parola","per","non","sentire"]},{id:"s23",text:"Non \xe8 la luce di l\xe0. Loredana era di qua, con il telefono. Due luci.",speakerId:null,kind:"narration",lemmas:["non","essere","la","luce","di","la","loredana","essere","di","qua","con","il","telefono","due","luce"]},{id:"s24",text:"Irene lo sa ancora. Non lo dice. Non serve.",speakerId:null,kind:"narration",lemmas:["irene","lo","sapere","ancora","non","lo","dire","non","servire"]}]},{id:"p3",order:3,sentences:[{id:"s25",text:"Loredana prende il quaderno senza chiedere. Lo apre.",speakerId:null,kind:"narration",lemmas:["loredana","prendere","il","quaderno","senza","chiedere","lo","aprire"]},{id:"s26",text:"Irene non ha fatto in tempo. Non voleva mostrare i numeri.",speakerId:null,kind:"narration",lemmas:["irene","non","avere","fare","in","tempo","non","volere","mostrare","i","numero"]},{id:"s27",text:"Sulla pagina c'\xe8 la griglia. Finestre con i numeri. Tre, quattro, cinque.",speakerId:null,kind:"narration",lemmas:["sulla","pagina","ce","la","griglia","finestra","con","i","numero","tre","quattro","cinque"]},{id:"s28",text:"C'\xe8 anche: stanza due, di fronte. C'\xe8 ieri. C'\xe8 stasera niente.",speakerId:null,kind:"narration",lemmas:["ce","anche","stanza","due","di","fronte","ce","ieri","ce","stasera","niente"]},{id:"s29",text:"Loredana legge i numeri ad alta voce, poi si ferma.",speakerId:null,kind:"narration",lemmas:["loredana","leggere","i","numero","ad","alto","voce","poi","si","fermare"]},{id:"s30",text:"Ha messo i numeri sulle sue finestre.",speakerId:"loredana",kind:"dialogue",lemmas:["avere","mettere","i","numero","sulle","suo","finestra"]},{id:"s31",text:"Non \xe8 cattiveria. \xc8 un disegno. Per\xf2 Loredana piange, senza rumore.",speakerId:null,kind:"narration",lemmas:["non","essere","cattiveria","essere","un","disegno","pero","loredana","piangere","senza","rumore"]},{id:"s32",text:"Irene chiude il quaderno. Lo mette via, sotto il braccio, di nuovo.",speakerId:null,kind:"narration",lemmas:["irene","chiudere","il","quaderno","lo","mettere","via","sotto","il","braccio","di","nuovo"]},{id:"s33",text:"Mi dispiace. Non volevo.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["mi","dispiacere","non","volere"]},{id:"s34",text:"Loredana si asciuga gli occhi. Non alza la voce.",speakerId:null,kind:"narration",lemmas:["loredana","si","asciugare","gli","occhio","non","alzare","la","voce"]},{id:"s35",text:"Se ama questo paese, lasci stare le finestre.",speakerId:"loredana",kind:"dialogue",lemmas:["se","amare","questo","paese","lasciare","stare","le","finestra"]},{id:"s36",text:"Irene non risponde. Non promette. Beve il caff\xe8 freddo, e sale.",speakerId:null,kind:"narration",lemmas:["irene","non","rispondere","non","promettere","bere","il","caffe","freddo","e","salire"]},{id:"s37",text:"In mansarda apre il quaderno. Non scrive: Loredana aiuta. Non scrive: Loredana \xe8 la luce.",speakerId:null,kind:"narration",lemmas:["in","mansarda","aprire","il","quaderno","non","scrivere","loredana","aiutare","non","scrivere","loredana","essere","la","luce"]},{id:"s38",text:"Scrive: figlia, ultima classe. Vuole dimenticare. I numeri fanno male.",speakerId:null,kind:"narration",lemmas:["scrivere","figlia","ultimo","classe","volere","dimenticare","i","numero","fare","male"]},{id:"s39",text:"Scrive anche: Loredana di qua. La luce di l\xe0. Ancora due.",speakerId:null,kind:"narration",lemmas:["scrivere","anche","loredana","di","qua","la","luce","di","la","ancora","due"]},{id:"s40",text:"Poi chiude. Dovrei lasciare le finestre. Per\xf2 non promette a nessuno.",speakerId:null,kind:"narration",lemmas:["poi","chiudere","dovere","lasciare","le","finestra","pero","non","promettere","a","nessuno"]},{id:"s41",text:"Loredana resta gi\xf9. Non sale. Non guarda di l\xe0.",speakerId:null,kind:"narration",lemmas:["loredana","restare","giu","non","salire","non","guardare","di","la"]},{id:"s42",text:"Irene ha paura di farle male di nuovo. Ha anche paura di fermarsi.",speakerId:null,kind:"narration",lemmas:["irene","avere","paura","di","fare","male","di","nuovo","avere","anche","paura","di","fermare"]},{id:"s43",text:"Mi dispiace, ha detto. Non voglio, ha detto Loredana.",speakerId:null,kind:"narration",lemmas:["mi","dispiacere","avere","dire","non","volere","avere","dire","loredana"]},{id:"s44",text:"Due paure. Una casa. Una scuola chiusa. Irene va al lavoro con il quaderno chiuso.",speakerId:null,kind:"narration",lemmas:["due","paura","una","casa","una","scuola","chiudere","irene","andare","al","lavoro","con","il","quaderno","chiudere"]}]},{id:"p4",order:4,sentences:[{id:"s45",text:"Al comune non parla di Loredana. Non parla della figlia. Non parla delle finestre.",speakerId:null,kind:"narration",lemmas:["al","comune","non","parlare","di","loredana","non","parlare","della","figlia","non","parlare","delle","finestra"]},{id:"s46",text:"Scansiona liste. Le mani fanno il lavoro. La testa no, del tutto.",speakerId:null,kind:"narration",lemmas:["scansionare","lista","le","mano","fare","il","lavoro","la","testa","no","del","tutto"]},{id:"s47",text:"Se ama questo paese, lasci stare le finestre: la frase resta.",speakerId:null,kind:"narration",lemmas:["se","amare","questo","paese","lasciare","stare","le","finestra","la","frase","restare"]},{id:"s48",text:"Irene non sa se ama questo paese. Sa che i numeri sono veri, e che Loredana ha pianto.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","se","amare","questo","paese","sapere","che","i","numero","essere","vero","e","che","loredana","avere","piangere"]},{id:"s49",text:"Sa anche che Loredana non \xe8 la lampada. Questo non cambia il pianto.",speakerId:null,kind:"narration",lemmas:["sapere","anche","che","loredana","non","essere","la","lampada","questo","non","cambiare","il","pianto"]},{id:"s50",text:"La sera sale senza mostrare il quaderno. La cucina \xe8 buia. Loredana non chiama.",speakerId:null,kind:"narration",lemmas:["la","sera","salire","senza","mostrare","il","quaderno","la","cucina","essere","buio","loredana","non","chiamare"]},{id:"s51",text:"Irene non accende la lampada verso la scuola, non ancora. Ascolta le scale. Niente.",speakerId:null,kind:"narration",lemmas:["irene","non","accendere","la","lampada","verso","la","scuola","non","ancora","ascoltare","le","scala","niente"]},{id:"s52",text:"Ho paura, ha detto Loredana. Non voglio. Irene tiene quelle frasi accanto ai numeri, non sopra.",speakerId:null,kind:"narration",lemmas:["avere","paura","avere","dire","loredana","non","volere","irene","tenere","quello","frase","accanto","ai","numero","non","sopra"]}]}],questions:[{id:"ch13_q01",chapterId:"la-casa-delle-finestre-13",type:"character",question:"Who was in the last class?",choices:["Loredana\u2019s daughter","Alme","Quinto"],correctChoice:0,explanation:"Loredana says her daughter was in the last class.",difficulty:2},{id:"ch13_q02",chapterId:"la-casa-delle-finestre-13",type:"direct",question:"What does Loredana want?",choices:["No more talk of the school; she wants to forget","Irene to open the school","A meeting with Sara"],correctChoice:0,explanation:"She wants to forget that school. She wants the town to forget.",difficulty:2},{id:"ch13_q03",chapterId:"la-casa-delle-finestre-13",type:"event",question:"What hurts Loredana?",choices:["Irene\u2019s numbered sketch of the windows","Mimmo\u2019s video","Alme\u2019s coffee"],correctChoice:0,explanation:"She opens the notebook. You put numbers on her windows.",difficulty:2},{id:"ch13_q04",chapterId:"la-casa-delle-finestre-13",type:"inference",question:"Is Loredana the night lamp in the school?",choices:["No. She was on this side, with a phone","Yes. She admitted it","The chapter does not say"],correctChoice:0,explanation:"Two lights. Loredana was on this side. Empty is also a word for not feeling.",difficulty:2}]}},1016,[]);
__d(function(e,a,n,o,r,s,i){r.exports={id:"la-casa-delle-finestre-14",storyId:"la-casa-delle-finestre",number:14,title:"The real code",titleIt:"Il codice vero",locationIds:["mansarda-irene","scuola-media"],characterIds:["irene-colombo"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-14",summary:"The facing window flashes three slow times. Irene answers with her lamp. Two slow flashes answer. Then dark. She writes: it is not only a timetable.",characterIds:["irene-colombo"],locationIds:["mansarda-irene","scuola-media"],rememberedFacts:["The facing window flashes three slow times","Irene answers with her lamp","Two slow flashes answer, then dark","She writes that it is not only a timetable"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Di sera Irene pensa alle parole di Loredana.",speakerId:null,kind:"narration",lemmas:["di","sera","irene","pensare","alle","parola","di","loredana"]},{id:"s02",text:"Se ama questo paese, lasci stare le finestre.",speakerId:null,kind:"narration",lemmas:["se","amare","questo","paese","lasciare","stare","le","finestra"]},{id:"s03",text:"Dovrei lasciare. Non dovrei guardare. Per\xf2 ieri c'era una pausa, e una sera senza luce.",speakerId:null,kind:"narration",lemmas:["dovere","lasciare","non","dovere","guardare","pero","ieri","ce","una","pausa","e","una","sera","senza","luce"]},{id:"s04",text:"Il quaderno \xe8 chiuso. Lei lo apre lo stesso.",speakerId:null,kind:"narration",lemmas:["il","quaderno","essere","chiudere","lei","lo","aprire","lo","stesso"]},{id:"s05",text:"Si mette alla finestra, di proposito, di fronte.",speakerId:null,kind:"narration",lemmas:["si","mettere","alla","finestra","di","proposito","di","fronte"]},{id:"s06",text:"Ha spento la luce della stanza. Resta una lampada piccola sul tavolo, spenta.",speakerId:null,kind:"narration",lemmas:["avere","spegnere","la","luce","della","stanza","restare","una","lampada","piccolo","sul","tavolo","spegnere"]},{id:"s07",text:"Aspetta le nove. Fuori \xe8 buio. La scuola sembra vuota.",speakerId:null,kind:"narration",lemmas:["aspettare","le","nove","fuori","essere","buio","la","scuola","sembrare","vuoto"]},{id:"s08",text:"Non esce. Non scende. Guarda solo.",speakerId:null,kind:"narration",lemmas:["non","uscire","non","scendere","guardare","solo"]},{id:"s09",text:"Conta i minuti. Pensa alla figlia di Loredana, all'ultima classe, ai numeri.",speakerId:null,kind:"narration",lemmas:["contare","i","minuto","pensare","alla","figlia","di","loredana","ultimo","classe","ai","numero"]},{id:"s10",text:"Se qualcuno \xe8 di l\xe0, non \xe8 Loredana. Questo lo ha gi\xe0. Non \xe8 abbastanza.",speakerId:null,kind:"narration",lemmas:["se","qualcuno","essere","di","la","non","essere","loredana","questo","lo","avere","gia","non","essere","abbastanza"]}]},{id:"p2",order:2,sentences:[{id:"s11",text:"Poi c'\xe8 una luce, alla finestra tre. Di fronte.",speakerId:null,kind:"narration",lemmas:["poi","ce","una","luce","alla","finestra","tre","di","fronte"]},{id:"s12",text:"Non va a destra. Non va al secondo piano. Resta l\xec.",speakerId:null,kind:"narration",lemmas:["non","andare","a","destra","non","andare","al","secondo","piano","restare","li"]},{id:"s13",text:"Si spegne. Poi si accende. Poi si spegne. Poi di nuovo.",speakerId:null,kind:"narration",lemmas:["si","spegnere","poi","si","accendere","poi","si","spegnere","poi","di","nuovo"]},{id:"s14",text:"Tre volte. Lente. Lunghe. Non \xe8 l'orario. Non \xe8 quattro, cinque, tre.",speakerId:null,kind:"narration",lemmas:["tre","volta","lento","lungo","non","essere","orario","non","essere","quattro","cinque","tre"]},{id:"s15",text:"Non \xe8 Morse. Non \xe8 un alfabeto. \xc8 solo lento, e poi buio.",speakerId:null,kind:"narration",lemmas:["non","essere","morse","non","essere","un","alfabeto","essere","solo","lento","e","poi","buio"]},{id:"s16",text:"Irene conta: una, due, tre. Poi buio.",speakerId:null,kind:"narration",lemmas:["irene","contare","una","due","tre","poi","buio"]},{id:"s17",text:"Qualcuno \xe8 l\xec. O \xe8 solo una luce che si muove male.",speakerId:null,kind:"narration",lemmas:["qualcuno","essere","li","o","essere","solo","una","luce","che","si","muovere","male"]},{id:"s18",text:"Dovrei non rispondere. Loredana ha pianto. Per\xf2 la pausa non era sul foglio.",speakerId:null,kind:"narration",lemmas:["dovere","non","rispondere","loredana","avere","piangere","pero","la","pausa","non","essere","sul","foglio"]},{id:"s19",text:"Irene prende la lampada del tavolo. Le mani tremano.",speakerId:null,kind:"narration",lemmas:["irene","prendere","la","lampada","del","tavolo","le","mano","tremare"]},{id:"s20",text:"Non dovrei. Per\xf2 accende. Una volta, lenta. Spegnere. Di nuovo, lenta.",speakerId:null,kind:"narration",lemmas:["non","dovere","pero","accendere","una","volta","lento","spegnere","di","nuovo","lento"]},{id:"s21",text:"Due volte. Poi la lascia spenta. Non tre. Non un gioco lungo.",speakerId:null,kind:"narration",lemmas:["due","volta","poi","la","lasciare","spegnere","non","tre","non","un","gioco","lungo"]}]},{id:"p3",order:3,sentences:[{id:"s22",text:"Aspetta. Il cuore va in fretta.",speakerId:null,kind:"narration",lemmas:["aspettare","il","cuore","andare","in","fretta"]},{id:"s23",text:"Di fronte, la luce risponde. Una volta, lenta. Poi un'altra.",speakerId:null,kind:"narration",lemmas:["di","fronte","la","luce","rispondere","una","volta","lento","poi","altro"]},{id:"s24",text:"Due. Poi buio.",speakerId:null,kind:"narration",lemmas:["due","poi","buio"]},{id:"s25",text:"Non tre. Non quattro. Due, come lei.",speakerId:null,kind:"narration",lemmas:["non","tre","non","quattro","due","come","lei"]},{id:"s26",text:"Irene resta ferma. Non accende di nuovo. Non bussa sul vetro.",speakerId:null,kind:"narration",lemmas:["irene","restare","fermo","non","accendere","di","nuovo","non","bussare","sul","vetro"]},{id:"s27",text:"Nessuno chiama. Nessuno parla. La finestra tre \xe8 scura.",speakerId:null,kind:"narration",lemmas:["nessuno","chiamare","nessuno","parlare","la","finestra","tre","essere","scuro"]},{id:"s28",text:"Irene aspetta cinque minuti. La luce non torna.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","cinque","minuto","la","luce","non","tornare"]},{id:"s29",text:"Non esce. Non va al cancello. Non chiama i carabinieri.",speakerId:null,kind:"narration",lemmas:["non","uscire","non","andare","al","cancello","non","chiamare","i","carabinieri"]},{id:"s30",text:"Apre il quaderno. Scrive: tre lente, di fronte. Io due. Poi due. Poi buio.",speakerId:null,kind:"narration",lemmas:["aprire","il","quaderno","scrivere","tre","lento","di","fronte","io","due","poi","due","poi","buio"]},{id:"s31",text:"Poi scrive: non \xe8 solo un orario.",speakerId:null,kind:"narration",lemmas:["poi","scrivere","non","essere","solo","un","orario"]},{id:"s32",text:"Non scrive un nome. Non scrive Sara. Non scrive qualcuno mi parla.",speakerId:null,kind:"narration",lemmas:["non","scrivere","un","nome","non","scrivere","sara","non","scrivere","qualcuno","mi","parlare"]},{id:"s33",text:"Sa solo questo: ha risposto, e qualcuno ha risposto a lei. O sembra.",speakerId:null,kind:"narration",lemmas:["sapere","solo","questo","avere","rispondere","e","qualcuno","avere","rispondere","a","lei","o","sembrare"]},{id:"s34",text:"Non sa chi. Non sale in strada. Non bussa alla porta di Loredana.",speakerId:null,kind:"narration",lemmas:["non","sapere","chi","non","salire","in","strada","non","bussare","alla","porta","di","loredana"]},{id:"s35",text:"Dovrei dirle della luce. Non dovrei, dopo i numeri.",speakerId:null,kind:"narration",lemmas:["dovere","dire","della","luce","non","dovere","dopo","i","numero"]},{id:"s36",text:"Sceglie il silenzio, per stasera. Il quaderno tiene i fatti. Lei no, a voce.",speakerId:null,kind:"narration",lemmas:["scegliere","il","silenzio","per","stasera","il","quaderno","tenere","i","fatto","lei","no","a","voce"]},{id:"s37",text:"Tre lente da l\xe0. Due da qua. Due da l\xe0. Poi niente.",speakerId:null,kind:"narration",lemmas:["tre","lento","da","la","due","da","qua","due","da","la","poi","niente"]},{id:"s38",text:"\xc8 semplice. \xc8 umano. Non \xe8 un orario, e non \xe8 ancora un nome.",speakerId:null,kind:"narration",lemmas:["essere","semplice","essere","umano","non","essere","un","orario","e","non","essere","ancora","un","nome"]},{id:"s39",text:"Irene spegne la lampada del tavolo. Si sdraia. Non dorme subito.",speakerId:null,kind:"narration",lemmas:["irene","spegnere","la","lampada","del","tavolo","si","sdraiare","non","dormire","subito"]}]},{id:"p4",order:4,sentences:[{id:"s40",text:"Prima di accendere ha contato fino a dieci. Poi fino a venti.",speakerId:null,kind:"narration",lemmas:["prima","di","accendere","avere","contare","fino","a","dieci","poi","fino","a","venti"]},{id:"s41",text:"Dovrei spegnere e andare a letto. Non dovrei fare la luce verso la scuola.",speakerId:null,kind:"narration",lemmas:["dovere","spegnere","e","andare","a","letto","non","dovere","fare","la","luce","verso","la","scuola"]},{id:"s42",text:"Per\xf2 ha fatto due volte, lente, e ha ricevuto due volte, lente.",speakerId:null,kind:"narration",lemmas:["pero","avere","fare","due","volta","lento","e","avere","ricevere","due","volta","lento"]},{id:"s43",text:"Non \xe8 un alfabeto. \xc8 un s\xec piccolo, e poi basta.",speakerId:null,kind:"narration",lemmas:["non","essere","un","alfabeto","essere","un","si_yes","piccolo","e","poi","basta"]},{id:"s44",text:"Qualcuno di l\xe0 ha visto la sua lampada. Questo \xe8 un fatto nuovo. Non \xe8 un nome.",speakerId:null,kind:"narration",lemmas:["qualcuno","di","la","avere","vedere","la","suo","lampada","questo","essere","un","fatto","nuovo","non","essere","un","nome"]},{id:"s45",text:"Domani c'\xe8 il comune. Domani c'\xe8 Loredana gi\xf9. Stasera c'\xe8 solo questo, e le mani che tremano ancora.",speakerId:null,kind:"narration",lemmas:["domani","ce","il","comune","domani","ce","loredana","giu","stasera","ce","solo","questo","e","le","mano","che","tremare","ancora"]},{id:"s46",text:"Non \xe8 Sara sul foglio. Non \xe8 un piano. \xc8 una luce che ha risposto a una luce.",speakerId:null,kind:"narration",lemmas:["non","essere","sara","sul","foglio","non","essere","un","piano","essere","una","luce","che","avere","rispondere","a","una","luce"]},{id:"s47",text:"Irene scrive di nuovo, pi\xf9 piano: non \xe8 solo un orario. Poi chiude. Non esce.",speakerId:null,kind:"narration",lemmas:["irene","scrivere","di","nuovo","piu","piano","non","essere","solo","un","orario","poi","chiudere","non","uscire"]},{id:"s48",text:"La finestra tre resta scura. La lampada del tavolo resta spenta. Due buie, di qua e di l\xe0.",speakerId:null,kind:"narration",lemmas:["la","finestra","tre","restare","scuro","la","lampada","del","tavolo","restare","spegnere","due","buio","di","qua","e","di","la"]},{id:"s49",text:"Ha risposto contro il senso, e contro Loredana. Lo sa. Non cancella la riga.",speakerId:null,kind:"narration",lemmas:["avere","rispondere","contro","il","senso","e","contro","loredana","lo","sapere","non","cancellare","la","riga"]},{id:"s50",text:"Non va al cancello. Non \xe8 un codice vero con lettere. \xc8 tre, poi due, poi buio.",speakerId:null,kind:"narration",lemmas:["non","andare","al","cancello","non","essere","un","codice","vero","con","lettera","essere","tre","poi","due","poi","buio"]},{id:"s51",text:"Dovrei. Non dovrei. Per\xf2 l'ha fatto. Questo resta, senza nome.",speakerId:null,kind:"narration",lemmas:["dovere","non","dovere","pero","avere","fare","questo","restare","senza","nome"]},{id:"s52",text:"Non chiama nessuno.",speakerId:null,kind:"narration",lemmas:["non","chiamare","nessuno"]},{id:"s53",text:"Se Loredana sente, fa male. Se nessuno sente, resta questo fatto, goffo, umano, chiuso nella stanza.",speakerId:null,kind:"narration",lemmas:["se","loredana","sentire","fare","male","se","nessuno","sentire","restare","questo","fatto","semplice","umano","chiudere","nella","stanza"]}]}],questions:[{id:"ch14_q01",chapterId:"la-casa-delle-finestre-14",type:"event",question:"What does the facing window do?",choices:["It flashes three slow times","It follows Monday\u2019s timetable","It stays dark all night"],correctChoice:0,explanation:"Three times. Slow. Long. At window three, opposite.",difficulty:2},{id:"ch14_q02",chapterId:"la-casa-delle-finestre-14",type:"direct",question:"What does Irene do?",choices:["She answers with her lamp, two slow times","She runs to the gate","She calls the Carabinieri"],correctChoice:0,explanation:"She should not. But she turns the table lamp on twice, slow.",difficulty:2},{id:"ch14_q03",chapterId:"la-casa-delle-finestre-14",type:"event",question:"What answers her?",choices:["Two slow flashes, then dark","A knock on the door","A note on the glass"],correctChoice:0,explanation:"Opposite, the light answers twice, like her. Then dark.",difficulty:2},{id:"ch14_q04",chapterId:"la-casa-delle-finestre-14",type:"inference",question:"What does Irene write?",choices:["That it is not only a timetable","Sara\u2019s name","A Morse alphabet"],correctChoice:0,explanation:"She writes: it is not only a timetable. She does not write a name.",difficulty:2}]}},1017,[]);
__d(function(e,a,r,n,o,i,t){o.exports={id:"la-casa-delle-finestre-15",storyId:"la-casa-delle-finestre",number:15,title:"Do not call",titleIt:"Non chiamare",locationIds:["scuola-media","comune","ufficio-alme"],characterIds:["irene-colombo","alme"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-15",summary:"Irene finds a note in the grate: no Carabinieri, registers. At work Alme books destroying papers for Friday, in three days.",characterIds:["irene-colombo","alme"],locationIds:["scuola-media","ufficio-alme"],rememberedFacts:["A note in the grate says not to call the Carabinieri, and mentions registers","Alme schedules destroying papers for Friday","Friday is in three days","Irene has little time"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"La mattina Irene passa davanti alla scuola, presto, come ieri.",speakerId:null,kind:"narration",lemmas:["la","mattina","irene","passare","davanti","alla","scuola","presto","come","ieri"]},{id:"s02",text:"Non entra. Guarda il cancello, poi la grata bassa, vicino al muro di fronte.",speakerId:null,kind:"narration",lemmas:["non","entrare","guardare","il","cancello","poi","la","grata","basso","vicino","al","muro","di","fronte"]},{id:"s03",text:"C'\xe8 un foglio, piegato, fermo tra le sbarre.",speakerId:null,kind:"narration",lemmas:["ce","un","foglio","piegare","fermo","tra","le","sbarra"]},{id:"s04",text:"Non c'era ieri. O lei non l'ha visto. Oggi c'\xe8.",speakerId:null,kind:"narration",lemmas:["non","ce","ieri","o","lei","non","avere","vedere","oggi","ce"]},{id:"s05",text:"Irene lo prende con due dita. Non \xe8 vecchio. Non c'\xe8 pioggia.",speakerId:null,kind:"narration",lemmas:["irene","lo","prendere","con","due","dito","non","essere","vecchio","non","ce","pioggia"]},{id:"s06",text:"Apre il foglio in strada, di qua, non di l\xe0.",speakerId:null,kind:"narration",lemmas:["aprire","il","foglio","in","strada","di","qua","non","di","la"]},{id:"s07",text:"Due righe, grandi, chiare: NON CARABINIERI. REGISTRI.",speakerId:null,kind:"narration",lemmas:["due","riga","grande","chiaro","non","carabinieri","registro"]},{id:"s08",text:"La prima riga \xe8 un ordine. La seconda \xe8 una cosa, non una spiegazione.",speakerId:null,kind:"narration",lemmas:["la","primo","riga","essere","un","ordine","la","secondo","essere","una","cosa","non","una","spiegazione"]},{id:"s09",text:"Irene non sa quali registri. Sa che Alme ha scatole, e carte della scuola.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","quale","registro","sapere","che","alme","avere","scatola","e","carta","della","scuola"]},{id:"s10",text:"Niente altro. Nessun nome. Nessuna data.",speakerId:null,kind:"narration",lemmas:["niente","altro","nessuno","nome","nessuno","data"]},{id:"s11",text:"Irene legge due volte. Lo mette in tasca, accanto alla confezione delle pile.",speakerId:null,kind:"narration",lemmas:["irene","leggere","due","volta","lo","mettere","in","tasca","accanto","alla","confezione","delle","pila"]},{id:"s12",text:"Dovrei chiamare comunque, pensa. Per\xf2 il foglio dice di no.",speakerId:null,kind:"narration",lemmas:["dovere","chiamare","comunque","pensare","pero","il","foglio","dire","di","no"]},{id:"s13",text:"Non sa chi l'ha scritto. Sa solo: dopo le due luci, c'\xe8 carta.",speakerId:null,kind:"narration",lemmas:["non","sapere","chi","avere","scrivere","sapere","solo","dopo","le","due","luce","ce","carta"]}]},{id:"p2",order:2,sentences:[{id:"s14",text:"Al comune il lavoro \xe8 come sempre, e non lo \xe8.",speakerId:null,kind:"narration",lemmas:["al","comune","il","lavoro","essere","come","sempre","e","non","lo","essere"]},{id:"s15",text:"Irene scansiona. Conta. Per\xf2 lo stomaco \xe8 stretto.",speakerId:null,kind:"narration",lemmas:["irene","scansionare","contare","pero","lo","stomaco","essere","stretto"]},{id:"s16",text:"Alme la chiama su, in ufficio, per le date.",speakerId:null,kind:"narration",lemmas:["alme","la","chiamare","su","in","ufficio","per","le","data"]},{id:"s17",text:"C'\xe8 un calendario sul muro.",speakerId:null,kind:"narration",lemmas:["ce","un","calendario","sul","muro"]},{id:"s18",text:"Alme indica venerd\xec con una penna. Irene conta i giorni sulle dita, sotto il tavolo.",speakerId:null,kind:"narration",lemmas:["alme","indicare","venerdi","con","una","penna","irene","contare","i","giorno","sulle","dito","sotto","il","tavolo"]},{id:"s19",text:"Venerd\xec distruggiamo le carte vecchie della scuola.",speakerId:"alme",kind:"dialogue",lemmas:["venerdi","distruggere","le","carta","vecchio","della","scuola"]},{id:"s20",text:"Non tutto. Quello che non serve. Registri, copie, liste.",speakerId:"alme",kind:"dialogue",lemmas:["non","tutto","quello","che","non","servire","registro","copia","lista"]},{id:"s21",text:"Non c'\xe8 tempo dopo. Il contratto \xe8 corto. Lei lo sa.",speakerId:"alme",kind:"dialogue",lemmas:["non","ce","tempo","dopo","il","contratto","essere","corto","lei","lo","sapere"]},{id:"s22",text:"Irene guarda venerd\xec. Oggi \xe8 marted\xec. Venerd\xec \xe8 tra tre giorni.",speakerId:null,kind:"narration",lemmas:["irene","guardare","venerdi","oggi","essere","martedi","venerdi","essere","tra","tre","giorno"]},{id:"s23",text:"Dobbiamo farlo, dice Alme, con il sorriso di sempre.",speakerId:null,kind:"narration",lemmas:["dovere","fare","dire","alme","con","il","sorriso","di","sempre"]},{id:"s24",text:"Irene dice: va bene. Non dice: registri. Non dice: un foglio nella grata.",speakerId:null,kind:"narration",lemmas:["irene","dire","andare","bene","non","dire","registro","non","dire","un","foglio","nella","grata"]},{id:"s25",text:"Lo stomaco fa male. Poco. Basta.",speakerId:null,kind:"narration",lemmas:["lo","stomaco","fare","male","poco","basta"]}]},{id:"p3",order:3,sentences:[{id:"s26",text:"Gi\xf9, Irene apre il quaderno. Copia: NON CARABINIERI. REGISTRI.",speakerId:null,kind:"narration",lemmas:["giu","irene","aprire","il","quaderno","copiare","non","carabinieri","registro"]},{id:"s27",text:"Copia anche: venerd\xec, tra tre giorni, distruggere.",speakerId:null,kind:"narration",lemmas:["copiare","anche","venerdi","tra","tre","giorno","distruggere"]},{id:"s28",text:"Non c'\xe8 tempo, pensa. Per\xf2 non sa che cosa deve fare.",speakerId:null,kind:"narration",lemmas:["non","ce","tempo","pensare","pero","non","sapere","che","cosa","dovere","fare"]},{id:"s29",text:"Dovrei chiamare i carabinieri. Il foglio dice di no.",speakerId:null,kind:"narration",lemmas:["dovere","chiamare","i","carabinieri","il","foglio","dire","di","no"]},{id:"s30",text:"Dovrei dirlo ad Alme. Alme distrugge venerd\xec.",speakerId:null,kind:"narration",lemmas:["dovere","dire","ad","alme","alme","distruggere","venerdi"]},{id:"s31",text:"Non incontra nessuno dietro la scuola. Non corre. Non \xe8 un film.",speakerId:null,kind:"narration",lemmas:["non","incontrare","nessuno","dietro","la","scuola","non","correre","non","essere","un","film"]},{id:"s32",text:"Mette il foglio nel quaderno. Chiude. Lavora ancora un'ora.",speakerId:null,kind:"narration",lemmas:["mettere","il","foglio","nel","quaderno","chiudere","lavorare","ancora","ora"]},{id:"s33",text:"Tre giorni. Registri. Non chiamare. Questo \xe8 tutto, per ora.",speakerId:null,kind:"narration",lemmas:["tre","giorno","registro","non","chiamare","questo","essere","tutto","per","ora"]},{id:"s34",text:"Non ha visto Sara. Non ha aperto la scuola. Ha un foglio, e un venerd\xec.",speakerId:null,kind:"narration",lemmas:["non","avere","vedere","sara","non","avere","aprire","la","scuola","avere","un","foglio","e","un","venerdi"]},{id:"s35",text:"Passa vicino alle scatole dei registri. Le conta con gli occhi. Non le sposta.",speakerId:null,kind:"narration",lemmas:["passare","vicino","alle","scatola","dei","registro","le","contare","con","gli","occhio","non","le","spostare"]},{id:"s36",text:"Venerd\xec qualcuno le prende. Distrugge. Tre giorni non sono tanti.",speakerId:null,kind:"narration",lemmas:["venerdi","qualcuno","le","prendere","distruggere","tre","giorno","non","essere","tanto"]},{id:"s37",text:"Dovrei chiamare comunque. Non chiama. Mette una mano sulla tasca, dove c'\xe8 il foglio, e lavora.",speakerId:null,kind:"narration",lemmas:["dovere","chiamare","comunque","non","chiamare","mettere","una","mano","sulla","tasca","dove","ce","il","foglio","e","lavorare"]}]},{id:"p4",order:4,sentences:[{id:"s38",text:"Alme \xe8 su. Non chiede del foglio. Non sa del foglio.",speakerId:null,kind:"narration",lemmas:["alme","essere","su","non","chiedere","del","foglio","non","sapere","del","foglio"]},{id:"s39",text:"Irene guarda il calendario di nuovo, da sola, quando Alme parla al telefono.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","calendario","di","nuovo","da","sola","quando","alme","parlare","al","telefono"]},{id:"s40",text:"Marted\xec, mercoled\xec, gioved\xec, venerd\xec. Quattro nomi. Tre notti in mezzo.",speakerId:null,kind:"narration",lemmas:["martedi","mercoledi","giovedi","venerdi","quattro","nome","tre","notte","in","mezzo"]},{id:"s41",text:"Dobbiamo, ha detto Alme. Non c'\xe8 tempo dopo.",speakerId:null,kind:"narration",lemmas:["dovere","avere","dire","alme","non","ce","tempo","dopo"]},{id:"s42",text:"Irene non sa ancora se cerca Sara, o se chiama, o se tace.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","ancora","se","cercare","sara","o","se","chiamare","o","se","tacere"]},{id:"s43",text:"Sa solo che venerd\xec \xe8 una data vera, sul muro, con una penna.",speakerId:null,kind:"narration",lemmas:["sapere","solo","che","venerdi","essere","una","data","vero","sul","muro","con","una","penna"]},{id:"s44",text:"I registri sono scatole. Il foglio \xe8 due parole. Le due cose si toccano, e lei non sa come.",speakerId:null,kind:"narration",lemmas:["i","registro","essere","scatola","il","foglio","essere","due","parola","le","due","cosa","si","toccare","e","lei","non","sapere","come"]},{id:"s45",text:"Non deve incontrare nessuno oggi. Deve solo non perdere tre giorni. Non sono tanti.",speakerId:null,kind:"narration",lemmas:["non","dovere","incontrare","nessuno","oggi","dovere","solo","non","perdere","tre","giorno","non","essere","tanto"]},{id:"s46",text:"Quando esce, la grata \xe8 vuota. Il foglio \xe8 nel quaderno. Venerd\xec \xe8 tra tre giorni.",speakerId:null,kind:"narration",lemmas:["quando","uscire","la","grata","essere","vuoto","il","foglio","essere","nel","quaderno","venerdi","essere","tra","tre","giorno"]},{id:"s47",text:"In strada non corre. Guarda la scuola chiusa. Nessuno alla grata. Nessuna luce, di giorno.",speakerId:null,kind:"narration",lemmas:["in","strada","non","correre","guardare","la","scuola","chiudere","nessuno","alla","grata","nessuno","luce","di","giorno"]},{id:"s48",text:"Dovrei chiamare comunque: la frase torna. Il foglio torna. Lei cammina in mezzo.",speakerId:null,kind:"narration",lemmas:["dovere","chiamare","comunque","la","frase","tornare","il","foglio","tornare","lei","camminare","in","mezzo"]},{id:"s49",text:"A casa mette il foglio sotto la pagina di ieri sera. Luci prima. Carta dopo. Venerd\xec dopo ancora.",speakerId:null,kind:"narration",lemmas:["a","casa","mettere","il","foglio","sotto","la","pagina","di","ieri","sera","luce","prima","carta","dopo","venerdi","dopo","ancora"]},{id:"s50",text:"Non c'\xe8 tempo per capire tutto. C'\xe8 tempo per non buttare tre giorni.",speakerId:null,kind:"narration",lemmas:["non","ce","tempo","per","capire","tutto","ce","tempo","per","non","buttare","tre","giorno"]},{id:"s51",text:"Marted\xec sera. Mercoled\xec, gioved\xec, venerd\xec. Irene conta ancora, senza voce.",speakerId:null,kind:"narration",lemmas:["martedi","sera","mercoledi","giovedi","venerdi","irene","contare","ancora","senza","voce"]},{id:"s52",text:"Non chiama. Non distrugge. Non incontra. Tiene il foglio. Tre giorni, per ora.",speakerId:null,kind:"narration",lemmas:["non","chiamare","non","distruggere","non","incontrare","tenere","il","foglio","tre","giorno","per","ora"]},{id:"s53",text:"Tre giorni. Registri. Non chiamare. Non \xe8 un piano. \xc8 una data, e lei \xe8 gi\xe0 in ritardo.",speakerId:null,kind:"narration",lemmas:["tre","giorno","registro","non","chiamare","non","essere","un","piano","essere","una","data","e","lei","essere","gia","in","ritardo"]}]}],questions:[{id:"ch15_q01",chapterId:"la-casa-delle-finestre-15",type:"direct",question:"What is on the paper in the grate?",choices:["Do not call Carabinieri. Registers","Come tonight with a key","Sara\u2019s address"],correctChoice:0,explanation:"Two lines: NON CARABINIERI. REGISTRI.",difficulty:2},{id:"ch15_q02",chapterId:"la-casa-delle-finestre-15",type:"event",question:"What does Alme schedule?",choices:["Destroying old school papers on Friday","A meeting with Piva","Opening the school"],correctChoice:0,explanation:"On Friday we destroy the old school papers. Registers, copies, lists.",difficulty:2},{id:"ch15_q03",chapterId:"la-casa-delle-finestre-15",type:"direct",question:"How soon is Friday?",choices:["In three days","Tonight","Next month"],correctChoice:0,explanation:"Today is Tuesday. Friday is in three days.",difficulty:2},{id:"ch15_q04",chapterId:"la-casa-delle-finestre-15",type:"inference",question:"Does Irene call the Carabinieri in this chapter?",choices:["No. She thinks she should, but she does not","Yes, from Alme\u2019s office","Yes, from the grate"],correctChoice:0,explanation:"I should call anyway. The sheet says no. She does not call.",difficulty:2}]}},1018,[]);
__d(function(e,a,n,o,r,i,l){r.exports={id:"la-casa-delle-finestre-16",storyId:"la-casa-delle-finestre",number:16,title:"Irene\u2019s choice",titleIt:"La scelta di Irene",locationIds:["via-della-scuola","scuola-media","cortile-scuola"],characterIds:["irene-colombo","quinto-belli"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-16",summary:"Irene lists three options and waits one day. Quinto offers a key if she leaves the forbidden folder alone. She refuses the key and does not call Piva. She will look for Sara in daylight.",characterIds:["irene-colombo","quinto-belli"],locationIds:["via-della-scuola"],rememberedFacts:["Irene could tell Piva, tell Alme, or look for Sara","She waits one day","Quinto offers a key if she leaves the non scansionare folder alone","She refuses the key and does not call Piva"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Irene cammina. Non va al comune subito. Gira il paese, piano.",speakerId:null,kind:"narration",lemmas:["irene","camminare","non","andare","al","comune","subito","girare","il","paese","piano"]},{id:"s02",text:"Nel quaderno scrive tre righe, come tre porte.",speakerId:null,kind:"narration",lemmas:["nel","quaderno","scrivere","tre","riga","come","tre","porta"]},{id:"s03",text:"Se dico al maresciallo Piva, qualcuno viene. Il foglio dice di no.",speakerId:null,kind:"narration",lemmas:["se","dire","al","maresciallo","piva","qualcuno","venire","il","foglio","dire","di","no"]},{id:"s04",text:"Se dico ad Alme, Alme sorride. Venerd\xec distrugge lo stesso.",speakerId:null,kind:"narration",lemmas:["se","dire","ad","alme","alme","sorridere","venerdi","distruggere","lo","stesso"]},{id:"s05",text:"Se cerco Sara, cerco una donna dell'autobus, di una foto, di una relazione.",speakerId:null,kind:"narration",lemmas:["se","cercare","sara","cercare","una","donna","autobus","di","una","foto","di","una","relazione"]},{id:"s06",text:"Non so se \xe8 lei. Non so se la luce \xe8 lei.",speakerId:null,kind:"narration",lemmas:["non","sapere","se","essere","lei","non","sapere","se","la","luce","essere","lei"]},{id:"s07",text:"Tre scelte. Tutte cattive, o tutte incomplete.",speakerId:null,kind:"narration",lemmas:["tre","scelta","tutto","cattivo","o","tutto","incompleto"]},{id:"s08",text:"Irene potrebbe chiamare oggi. Potrebbe dire tutto gi\xf9, alle scatole.",speakerId:null,kind:"narration",lemmas:["irene","potere","chiamare","oggi","potere","dire","tutto","giu","alle","scatola"]},{id:"s09",text:"Dovrei scegliere adesso. Per\xf2 sceglie di aspettare un giorno.",speakerId:null,kind:"narration",lemmas:["dovere","scegliere","adesso","pero","scegliere","di","aspettare","un","giorno"]},{id:"s10",text:"Scrive: un giorno. Non \xe8 una soluzione. \xc8 tempo.",speakerId:null,kind:"narration",lemmas:["scrivere","un","giorno","non","essere","una","soluzione","essere","tempo"]},{id:"s11",text:"Un giorno non ferma venerd\xec. Un giorno ferma solo la voce, oggi.",speakerId:null,kind:"narration",lemmas:["un","giorno","non","fermare","venerdi","un","giorno","fermare","solo","la","voce","oggi"]},{id:"s12",text:"Cammina ancora. Passa la piazza, la fermata, la scuola chiusa.",speakerId:null,kind:"narration",lemmas:["camminare","ancora","passare","la","piazza","la","fermata","la","scuola","chiudere"]}]},{id:"p2",order:2,sentences:[{id:"s13",text:"Vicino alla scuola c'\xe8 Quinto, con la tanica. Oggi non annaffia.",speakerId:null,kind:"narration",lemmas:["vicino","alla","scuola","ce","quinto","con","la","tanica","oggi","non","annaffiare"]},{id:"s14",text:"Tiene le chiavi in mano, visibili, come sempre.",speakerId:null,kind:"narration",lemmas:["tenere","le","chiave","in","mano","visibile","come","sempre"]},{id:"s15",text:"Signorina. Lei guarda troppo.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["signorina","lei","guardare","troppo"]},{id:"s16",text:"Irene si ferma di qua. Il cancello \xe8 di l\xe0.",speakerId:null,kind:"narration",lemmas:["irene","si","fermare","di","qua","il","cancello","essere","di","la"]},{id:"s17",text:"Lavoro al comune. Carte della scuola.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["lavorare","al","comune","carta","della","scuola"]},{id:"s18",text:"Quinto annuisce. Non sorride.",speakerId:null,kind:"narration",lemmas:["quinto","annuire","non","sorridere"]},{id:"s19",text:"C'\xe8 una cartella. Non scansionare. Lei la lascia stare, e io le do una chiave.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["ce","una","cartella","non","scansionare","lei","la","lasciare","stare","e","io","le","dare","una","chiave"]},{id:"s20",text:"Una chiave sicura, dice. Per entrare senza rumore. Poi basta.",speakerId:null,kind:"narration",lemmas:["una","chiave","sicuro","dire","per","entrare","senza","rumore","poi","basta"]},{id:"s21",text:"Irene guarda le chiavi. Non le prende.",speakerId:null,kind:"narration",lemmas:["irene","guardare","le","chiave","non","le","prendere"]},{id:"s22",text:"Se prendo la chiave, entro. La scuola non \xe8 sicura. Loredana ha paura.",speakerId:null,kind:"narration",lemmas:["se","prendere","la","chiave","entrare","la","scuola","non","essere","sicuro","loredana","avere","paura"]},{id:"s23",text:"Se lascio la cartella, lascio anche Sara Neri, e le crepe.",speakerId:null,kind:"narration",lemmas:["se","lasciare","la","cartella","lasciare","anche","sara","neri","e","le","crepa"]},{id:"s24",text:"No. Grazie. Non voglio la chiave.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["no","grazie","non","volere","la","chiave"]},{id:"s25",text:"Quinto chiude la mano. Non insiste. Non spiega perch\xe9 offre.",speakerId:null,kind:"narration",lemmas:["quinto","chiudere","la","mano","non","insistere","non","spiegare","perche","offrire"]},{id:"s26",text:"La scuola \xe8 vuota, dice, senza guardare le finestre.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["la","scuola","essere","vuoto","dire","senza","guardare","le","finestra"]},{id:"s27",text:"Poi cammina via con la tanica, e con tutte le chiavi.",speakerId:null,kind:"narration",lemmas:["poi","camminare","via","con","la","tanica","e","con","tutto","le","chiave"]}]},{id:"p3",order:3,sentences:[{id:"s28",text:"Irene non chiama il maresciallo Piva. Non oggi. Non con la sua chiave.",speakerId:null,kind:"narration",lemmas:["irene","non","chiamare","il","maresciallo","piva","non","oggi","non","con","la","suo","chiave"]},{id:"s29",text:"Non dice di s\xec ad Alme. Non entra di notte.",speakerId:null,kind:"narration",lemmas:["non","dire","di","si_yes","ad","alme","non","entrare","di","notte"]},{id:"s30",text:"Aspetta un giorno. Per\xf2 non resta ferma nella testa.",speakerId:null,kind:"narration",lemmas:["aspettare","un","giorno","pero","non","restare","fermo","nella","testa"]},{id:"s31",text:"Scrive: di giorno, non con la chiave. Cerco Sara.",speakerId:null,kind:"narration",lemmas:["scrivere","di","giorno","non","con","la","chiave","cercare","sara"]},{id:"s32",text:"Non \xe8 una prova. \xc8 una scelta piccola: vedere la donna, se c'\xe8, alla luce.",speakerId:null,kind:"narration",lemmas:["non","essere","una","prova","essere","una","scelta","piccolo","vedere","la","donna","se","ce","alla","luce"]},{id:"s33",text:"Chiude il quaderno. Va al lavoro. Venerd\xec \xe8 tra tre giorni, meno uno, presto.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno","andare","al","lavoro","venerdi","essere","tra","tre","giorno","meno","uno","presto"]},{id:"s34",text:"Prima passa la fermata, di giorno. Non c'\xe8 la donna. Non c'\xe8 la borsa.",speakerId:null,kind:"narration",lemmas:["prima","passare","la","fermata","di","giorno","non","ce","la","donna","non","ce","la","borsa"]},{id:"s35",text:"Irene non aspetta l'autobus. Guarda, poi va. Cerco Sara, ha scritto. Oggi non c'\xe8.",speakerId:null,kind:"narration",lemmas:["irene","non","aspettare","autobus","guardare","poi","andare","cercare","sara","avere","scrivere","oggi","non","ce"]},{id:"s36",text:"Non \xe8 la fine. \xc8 un giorno. La chiave resta con Quinto.",speakerId:null,kind:"narration",lemmas:["non","essere","la","fine","essere","un","giorno","la","chiave","restare","con","quinto"]}]},{id:"p4",order:4,sentences:[{id:"s37",text:"Se prendeva la chiave, entrava. Se entrava, la scuola non era pi\xf9 solo finestre.",speakerId:null,kind:"narration",lemmas:["se","prendere","la","chiave","entrare","se","entrare","la","scuola","non","essere","piu","solo","finestra"]},{id:"s38",text:"Ha detto no. Questo \xe8 un fatto. Non \xe8 ancora Sara, e non \xe8 Piva.",speakerId:null,kind:"narration",lemmas:["avere","dire","no","questo","essere","un","fatto","non","essere","ancora","sara","e","non","essere","piva"]},{id:"s39",text:"Quinto sa della cartella. Non spiega come. Irene non chiede, perch\xe9 chiedere \xe8 gi\xe0 un s\xec.",speakerId:null,kind:"narration",lemmas:["quinto","sapere","della","cartella","non","spiegare","come","irene","non","chiedere","perche","chiedere","essere","gia","un","si_yes"]},{id:"s40",text:"Di giorno, se c'\xe8 la donna, la vede. Se non c'\xe8, aspetta il giorno dopo, non la notte con le chiavi.",speakerId:null,kind:"narration",lemmas:["di","giorno","se","ce","la","donna","la","vedere","se","non","ce","aspettare","il","giorno","dopo","non","la","notte","con","le","chiave"]},{id:"s41",text:"Venerd\xec resta sul calendario. Un giorno di attesa non lo cancella.",speakerId:null,kind:"narration",lemmas:["venerdi","restare","sul","calendario","un","giorno","di","attesa","non","lo","cancellare"]},{id:"s42",text:"Irene va al comune con tre no: no a Piva, no alla chiave, no alla fretta di stasera.",speakerId:null,kind:"narration",lemmas:["irene","andare","al","comune","con","tre","no","no","a","piva","no","alla","chiave","no","alla","fretta","di","stasera"]},{id:"s43",text:"Un s\xec c'\xe8: di giorno, se la donna c'\xe8. Oggi non c'era. Domani pu\xf2 esserci.",speakerId:null,kind:"narration",lemmas:["un","si_yes","ce","di","giorno","se","la","donna","ce","oggi","non","ce","domani","potere","esserci"]},{id:"s44",text:"Non ha capito tutto. Ha scelto di non entrare, e di non chiamare, per un giorno.",speakerId:null,kind:"narration",lemmas:["non","avere","capire","tutto","avere","scegliere","di","non","entrare","e","di","non","chiamare","per","un","giorno"]},{id:"s45",text:"Se dico a Piva, non ascolto il foglio. Se dico ad Alme, venerd\xec resta.",speakerId:null,kind:"narration",lemmas:["se","dire","a","piva","non","ascoltare","il","foglio","se","dire","ad","alme","venerdi","restare"]},{id:"s46",text:"Se cerco Sara di giorno, forse capisco una persona, non un palazzo.",speakerId:null,kind:"narration",lemmas:["se","cercare","sara","di","giorno","forse","capire","una","persona","non","un","palazzo"]},{id:"s47",text:"Per questo aspetta. Non perch\xe9 ha capito. Perch\xe9 non ha ancora visto il viso, alla luce.",speakerId:null,kind:"narration",lemmas:["per","questo","aspettare","non","perche","avere","capire","perche","non","avere","ancora","vedere","il","viso","alla","luce"]},{id:"s48",text:"Quinto \xe8 gi\xe0 lontano, con le chiavi. Irene tiene il quaderno, e tre no, e un giorno.",speakerId:null,kind:"narration",lemmas:["quinto","essere","gia","lontano","con","le","chiave","irene","tenere","il","quaderno","e","tre","no","e","un","giorno"]},{id:"s49",text:"Domani \xe8 mercoled\xec. Poi gioved\xec. Poi venerd\xec. Lei ha scelto solo il primo passo: aspettare, e cercare di giorno.",speakerId:null,kind:"narration",lemmas:["domani","essere","mercoledi","poi","giovedi","poi","venerdi","lei","avere","scegliere","solo","il","primo","passo","aspettare","e","cercare","di","giorno"]},{id:"s50",text:"Non ha la chiave. Non ha Piva. Ha un giorno, e una foto, e un forse.",speakerId:null,kind:"narration",lemmas:["non","avere","la","chiave","non","avere","piva","avere","un","giorno","e","una","foto","e","un","forse"]},{id:"s51",text:"Questo \xe8 abbastanza per stasera. Non \xe8 tutto. Non deve essere tutto.",speakerId:null,kind:"narration",lemmas:["questo","essere","abbastanza","per","stasera","non","essere","tutto","non","dovere","essere","tutto"]}]}],questions:[{id:"ch16_q01",chapterId:"la-casa-delle-finestre-16",type:"direct",question:"What three options does Irene write?",choices:["Tell Piva, tell Alme, or look for Sara","Take the key, call Mimmo, or leave town","Scan everything, or nothing"],correctChoice:0,explanation:"Three lines, like three doors: Piva, Alme, Sara.",difficulty:2},{id:"ch16_q02",chapterId:"la-casa-delle-finestre-16",type:"event",question:"What does she choose to do first?",choices:["Wait one day","Call Piva at once","Enter the school at night"],correctChoice:0,explanation:"She chooses to wait one day. It is not a solution. It is time.",difficulty:2},{id:"ch16_q03",chapterId:"la-casa-delle-finestre-16",type:"character",question:"What does Quinto offer?",choices:["A key if she leaves the forbidden folder alone","To testify about the cracks","A meeting with Sara"],correctChoice:0,explanation:"Leave non scansionare alone, and he gives her a key. She says no.",difficulty:2},{id:"ch16_q04",chapterId:"la-casa-delle-finestre-16",type:"inference",question:"How will Irene look for Sara?",choices:["In daylight, without Quinto\u2019s key","With the key, at night","By calling Piva"],correctChoice:0,explanation:"She writes: in daylight, not with the key. I look for Sara.",difficulty:2}]}},1019,[]);
__d(function(e,a,r,n,i,o,s){i.exports={id:"la-casa-delle-finestre-17",storyId:"la-casa-delle-finestre",number:17,title:"Meeting",titleIt:"Incontro",locationIds:["via-della-scuola","scuola-media"],characterIds:["irene-colombo","sara-neri"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-17",summary:"On Wednesday, behind the gym, Irene meets Sara Neri. Sara was the lamp. She asks Irene to delay a box at work before Friday, not to enter the school. Irene says she does not know.",characterIds:["irene-colombo","sara-neri"],locationIds:["scuola-media"],rememberedFacts:["Today is Wednesday","Sara Neri was the person with the lamp","She used rooms because there is no corridor light, and she followed old hours","She paused and answered because she saw Irene","She wants the registers saved from Friday","She asks Irene to delay or lose a box at work, not to break in","Irene says she does not know"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Oggi \xe8 mercoled\xec. Ieri era marted\xec. Venerd\xec \xe8 tra due giorni.",speakerId:null,kind:"narration",lemmas:["oggi","essere","mercoledi","ieri","essere","martedi","venerdi","essere","tra","due","giorno"]},{id:"s02",text:"Irene non prende la chiave di Quinto. Cerca Sara di giorno, come ha scritto.",speakerId:null,kind:"narration",lemmas:["irene","non","prendere","la","chiave","di","quinto","cercare","sara","di","giorno","come","avere","scrivere"]},{id:"s03",text:"Non va alla fermata. Gira dietro la scuola, di l\xe0, verso la palestra chiusa.",speakerId:null,kind:"narration",lemmas:["non","andare","alla","fermata","girare","dietro","la","scuola","di","la","verso","la","palestra","chiudere"]},{id:"s04",text:"Non entra. Resta fuori, sul cemento, con il quaderno in tasca.",speakerId:null,kind:"narration",lemmas:["non","entrare","restare","fuori","sul","cemento","con","il","quaderno","in","tasca"]},{id:"s05",text:"C'\xe8 una donna. Ha una borsa grande, rigida, come carta.",speakerId:null,kind:"narration",lemmas:["ce","una","donna","avere","una","borsa","grande","rigido","come","carta"]},{id:"s06",text:"Irene guarda il viso. \xc8 la foto. \xc8 la fermata. Forse non \xe8 pi\xf9 forse.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","viso","essere","la","foto","essere","la","fermata","forse","non","essere","piu","forse"]},{id:"s07",text:"La donna parla per prima. Voce bassa, di giorno.",speakerId:null,kind:"narration",lemmas:["la","donna","parlare","per","prima","voce","basso","di","giorno"]},{id:"s08",text:"Lei \xe8 Irene. Io sono Sara Neri.",speakerId:"sara-neri",kind:"dialogue",lemmas:["lei","essere","irene","io","essere","sara","neri"]},{id:"s09",text:"Irene non sorride. Il cuore va in fretta. Ha rabbia, e paura, insieme.",speakerId:null,kind:"narration",lemmas:["irene","non","sorridere","il","cuore","andare","in","fretta","avere","rabbia","e","paura","insieme"]},{id:"s10",text:"Lei era la luce.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["lei","essere","la","luce"]},{id:"s11",text:"S\xec.",speakerId:"sara-neri",kind:"dialogue",lemmas:["si_yes"]},{id:"s12",text:"Irene respira. Voleva un nome. Adesso ce l'ha, e non \xe8 pi\xf9 facile.",speakerId:null,kind:"narration",lemmas:["irene","respirare","volere","un","nome","adesso","ce","avere","e","non","essere","piu","facile"]},{id:"s13",text:"Lei mi ha spaventata. Le luci, la pausa, il foglio nella grata.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["lei","mi","avere","spaventare","le","luce","la","pausa","il","foglio","nella","grata"]},{id:"s14",text:"Il foglio era mio. Non chiamare. Registri. Era vero.",speakerId:"sara-neri",kind:"dialogue",lemmas:["il","foglio","essere","mio","non","chiamare","registro","essere","vero"]},{id:"s15",text:"Irene non dice grazie. Non dice ti denuncio. Sta l\xec, sul cemento.",speakerId:null,kind:"narration",lemmas:["irene","non","dire","grazie","non","dire","ti","denunciare","stare","li","sul","cemento"]}]},{id:"p2",order:2,sentences:[{id:"s16",text:"Irene tiene le mani chiuse. Non \xe8 un film. \xc8 una persona, di giorno, dietro la palestra.",speakerId:null,kind:"narration",lemmas:["irene","tenere","le","mano","chiudere","non","essere","un","film","essere","una","persona","di","giorno","dietro","la","palestra"]},{id:"s17",text:"Perch\xe9 le stanze? Perch\xe9 la pausa? Perch\xe9 tre luci lente?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["perche","le","stanza","perche","la","pausa","perche","tre","luce","lento"]},{id:"s18",text:"Sara non fa un discorso. Risponde a pezzi, concreti.",speakerId:null,kind:"narration",lemmas:["sara","non","fare","un","discorso","rispondere","a","pezzo","concreto"]},{id:"s19",text:"Nel corridoio non c'\xe8 luce. Uso le stanze. Avevo l'orario vecchio, in testa.",speakerId:"sara-neri",kind:"dialogue",lemmas:["nel","corridoio","non","ce","luce","usare","le","stanza","avere","orario","vecchio","in","testa"]},{id:"s20",text:"Poi ho visto lei, alla finestra. Mi sono fermata. Poi ho risposto.",speakerId:"sara-neri",kind:"dialogue",lemmas:["poi","avere","vedere","lei","alla","finestra","mi","essere","fermare","poi","avere","rispondere"]},{id:"s21",text:"Avevo bisogno di qualcuno al comune. Non dei carabinieri. Dei registri.",speakerId:"sara-neri",kind:"dialogue",lemmas:["avere","bisogno","di","qualcuno","al","comune","non","dei","carabinieri","dei","registro"]},{id:"s22",text:"Irene ascolta. Non perdona, non ancora. Capisce i fatti, uno sotto l'altro.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","non","perdonare","non","ancora","capire","i","fatto","uno","sotto","altro"]},{id:"s23",text:"Venerd\xec Alme distrugge. I registri delle classi, le copie, le liste.",speakerId:"sara-neri",kind:"dialogue",lemmas:["venerdi","alme","distruggere","i","registro","delle","classe","le","copia","le","lista"]},{id:"s24",text:"Se mi aiuti, non entri. Non prendi la chiave. Perdi tempo, al lavoro.",speakerId:"sara-neri",kind:"dialogue",lemmas:["se","mi","aiutare","non","entrare","non","prendere","la","chiave","perdere","tempo","al","lavoro"]},{id:"s25",text:"Una scatola. La metti dove non \xe8. Un giorno, due. Basta.",speakerId:"sara-neri",kind:"dialogue",lemmas:["una","scatola","la","mettere","dove","non","essere","un","giorno","due","basta"]},{id:"s26",text:"Non \xe8 un furto da film. \xc8 tempo. Venerd\xec \xe8 tra due giorni.",speakerId:null,kind:"narration",lemmas:["non","essere","un","furto","da","film","essere","tempo","venerdi","essere","tra","due","giorno"]}]},{id:"p3",order:3,sentences:[{id:"s27",text:"Irene guarda la borsa. Guarda Sara. Guarda la palestra chiusa.",speakerId:null,kind:"narration",lemmas:["irene","guardare","la","borsa","guardare","sara","guardare","la","palestra","chiudere"]},{id:"s28",text:"Loredana ha pianto. Quinto ha offerto una chiave. Alme sorride.",speakerId:null,kind:"narration",lemmas:["loredana","avere","piangere","quinto","avere","offrire","una","chiave","alme","sorridere"]},{id:"s29",text:"Adesso una donna dice: perdi una scatola. Irene non \xe8 pi\xf9 solo una che conta finestre.",speakerId:null,kind:"narration",lemmas:["adesso","una","donna","dire","perdere","una","scatola","irene","non","essere","piu","solo","una","che","contare","finestra"]},{id:"s30",text:"Dovrei dire di no. Dovrei chiamare Piva. Dovrei andare al lavoro e scansionare.",speakerId:null,kind:"narration",lemmas:["dovere","dire","di","no","dovere","chiamare","piva","dovere","andare","al","lavoro","e","scansionare"]},{id:"s31",text:"Non so.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["non","sapere"]},{id:"s32",text:"Sara non insiste. Non tocca Irene. Annuisce, o quasi.",speakerId:null,kind:"narration",lemmas:["sara","non","insistere","non","toccare","irene","annuire","o","quasi"]},{id:"s33",text:"Oggi \xe8 mercoled\xec. Domani \xe8 gioved\xec. Poi venerd\xec.",speakerId:"sara-neri",kind:"dialogue",lemmas:["oggi","essere","mercoledi","domani","essere","giovedi","poi","venerdi"]},{id:"s34",text:"Irene se ne va di qua, verso la strada. Non entra. Non dice di s\xec.",speakerId:null,kind:"narration",lemmas:["irene","se","ne","andare","di","qua","verso","la","strada","non","entrare","non","dire","di","si_yes"]},{id:"s35",text:"Scrive dopo, in mansarda: Sara \xe8 la luce. Chiede tempo, non la scuola. Io: non so.",speakerId:null,kind:"narration",lemmas:["scrivere","dopo","in","mansarda","sara","essere","la","luce","chiedere","tempo","non","la","scuola","io","non","sapere"]},{id:"s36",text:"Non scrive: ho capito tutto. Non ha capito tutto. Ha un viso, e una richiesta.",speakerId:null,kind:"narration",lemmas:["non","scrivere","avere","capire","tutto","non","avere","capire","tutto","avere","un","viso","e","una","richiesta"]},{id:"s37",text:"Dietro la palestra c'era cemento, e una borsa, e due giorni.",speakerId:null,kind:"narration",lemmas:["dietro","la","palestra","ce","cemento","e","una","borsa","e","due","giorno"]},{id:"s38",text:"Irene va al comune lo stesso mercoled\xec, dopo. Scansiona. Non perde una scatola. Non oggi.",speakerId:null,kind:"narration",lemmas:["irene","andare","al","comune","lo","stesso","mercoledi","dopo","scansionare","non","perdere","una","scatola","non","oggi"]},{id:"s39",text:"Alme dice poco. Venerd\xec, ripete. Irene dice: va bene. Non dice di Sara.",speakerId:null,kind:"narration",lemmas:["alme","dire","poco","venerdi","ripetere","irene","dire","andare","bene","non","dire","di","sara"]},{id:"s40",text:"La sera non accende la lampada verso la scuola. Sa chi \xe8. Non ha bisogno della griglia, stasera.",speakerId:null,kind:"narration",lemmas:["la","sera","non","accendere","la","lampada","verso","la","scuola","sapere","chi","essere","non","avere","bisogno","della","griglia","stasera"]},{id:"s41",text:"Ha bisogno di una scelta, gioved\xec. Oggi ha detto non so. Questo resta.",speakerId:null,kind:"narration",lemmas:["avere","bisogno","di","una","scelta","giovedi","oggi","avere","dire","non","sapere","questo","restare"]},{id:"s42",text:"Sara \xe8 restata dietro la palestra. Non l'ha seguita. Non \xe8 un inseguimento.",speakerId:null,kind:"narration",lemmas:["sara","essere","restare","dietro","la","palestra","non","avere","seguire","non","essere","un","inseguimento"]},{id:"s43",text:"Irene, al comune, tocca una scatola di registri e la lascia. Non oggi. Mercoled\xec non \xe8 il giorno del seminterrato.",speakerId:null,kind:"narration",lemmas:["irene","al","comune","toccare","una","scatola","di","registro","e","la","lasciare","non","oggi","mercoledi","non","essere","il","giorno","del","seminterrato"]},{id:"s44",text:"Se mi aiuti, ha detto Sara. Se. Irene tiene il se fino a gioved\xec.",speakerId:null,kind:"narration",lemmas:["se","mi","aiutare","avere","dire","sara","se","irene","tenere","il","se","fino","a","giovedi"]},{id:"s45",text:"Non \xe8 tutto risolto. \xc8 un incontro. Un viso. Una richiesta di tempo. Un non so.",speakerId:null,kind:"narration",lemmas:["non","essere","tutto","risolvere","essere","un","incontro","un","viso","una","richiesta","di","tempo","un","non","sapere"]},{id:"s46",text:"Dietro la palestra il vento \xe8 poco. Sara tiene la borsa come tiene i registri: vicina.",speakerId:null,kind:"narration",lemmas:["dietro","la","palestra","il","vento","essere","poco","sara","tenere","la","borsa","come","tenere","i","registro","vicino"]},{id:"s47",text:"Irene chiede ancora: le ore vecchie. Sara dice: stanza due, poi tre, poi otto, come prima.",speakerId:null,kind:"narration",lemmas:["irene","chiedere","ancora","le","ora","vecchio","sara","dire","stanza","due","poi","tre","poi","otto","come","prima"]},{id:"s48",text:"Poi lei. Poi la pausa. Poi le tre lente. Poi le due. Poi il foglio.",speakerId:null,kind:"narration",lemmas:["poi","lei","poi","la","pausa","poi","le","tre","lento","poi","le","due","poi","il","foglio"]},{id:"s49",text:"Non \xe8 magia. \xc8 una donna senza corridoio, con una lampada da campeggio, e una data: venerd\xec.",speakerId:null,kind:"narration",lemmas:["non","essere","magia","essere","una","donna","senza","corridoio","con","una","lampada","da","campeggio","e","una","data","venerdi"]},{id:"s50",text:"Irene torna in mansarda mercoled\xec sera. Non bussa da Loredana. Non chiama Piva. Non dice s\xec a Sara.",speakerId:null,kind:"narration",lemmas:["irene","tornare","in","mansarda","mercoledi","sera","non","bussare","da","loredana","non","chiamare","piva","non","dire","si_yes","a","sara"]},{id:"s51",text:"Domani \xe8 gioved\xec. Domani pu\xf2 perdere una scatola, o no. Stasera tiene solo: non so.",speakerId:null,kind:"narration",lemmas:["domani","essere","giovedi","domani","potere","perdere","una","scatola","o","no","stasera","tenere","solo","non","sapere"]},{id:"s52",text:"Mercoled\xec \xe8 finito. Non ha detto s\xec. Non ha detto no. Ha un nome, e due giorni. Basta cos\xec.",speakerId:null,kind:"narration",lemmas:["mercoledi","essere","finire","non","avere","dire","si_yes","non","avere","dire","no","avere","un","nome","e","due","giorno","basta","cosi"]}]}],questions:[{id:"ch17_q01",chapterId:"la-casa-delle-finestre-17",type:"direct",question:"What day is it?",choices:["Wednesday","Friday","Tuesday"],correctChoice:0,explanation:"Today is Wednesday. Yesterday was Tuesday. Friday is in two days.",difficulty:2},{id:"ch17_q02",chapterId:"la-casa-delle-finestre-17",type:"character",question:"Who was the lamp?",choices:["Sara Neri","Loredana","Quinto"],correctChoice:0,explanation:"Irene says: you were the light. Sara says yes.",difficulty:2},{id:"ch17_q03",chapterId:"la-casa-delle-finestre-17",type:"event",question:"What does Sara ask Irene to do?",choices:["Lose or delay a box at work, not enter the school","Take Quinto\u2019s key tonight","Call the Carabinieri at once"],correctChoice:0,explanation:"Lose time at work. A box. Not the key. Not a break-in.",difficulty:2},{id:"ch17_q04",chapterId:"la-casa-delle-finestre-17",type:"inference",question:"What does Irene answer?",choices:["I don\u2019t know","Yes, I will steal the files","No, never"],correctChoice:0,explanation:"She does not say yes. She says: I don\u2019t know.",difficulty:2}]}},1020,[]);
__d(function(e,a,o,r,n,i,s){n.exports={id:"la-casa-delle-finestre-18",storyId:"la-casa-delle-finestre",number:18,title:"The basement",titleIt:"Il seminterrato",locationIds:["scatole-comune","seminterrato-comune","ufficio-alme"],characterIds:["irene-colombo","alme"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-18",summary:"On Thursday Irene scans for hours, then hides a box of registers in the basement. She knows it is wrong. Alme counts the boxes, notices a gap, and looks at Irene too long.",characterIds:["irene-colombo","alme"],locationIds:["scatole-comune","seminterrato-comune"],rememberedFacts:["Today is Thursday","Irene hides a box of registers on purpose","She knows it is wrong","Alme notices something missing and says nothing yet"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Oggi \xe8 gioved\xec. Ieri ha visto Sara. Domani \xe8 venerd\xec.",speakerId:null,kind:"narration",lemmas:["oggi","essere","giovedi","ieri","avere","vedere","sara","domani","essere","venerdi"]},{id:"s02",text:"Irene \xe8 gi\xf9, con le scatole. Lo scanner \xe8 acceso. Alme \xe8 su.",speakerId:null,kind:"narration",lemmas:["irene","essere","giu","con","le","scatola","lo","scanner","essere","accendere","alme","essere","su"]},{id:"s03",text:"Prima fa il lavoro vero. Pagine, timbri, numeri sul foglio del comune.",speakerId:null,kind:"narration",lemmas:["prima","fare","il","lavoro","vero","pagina","timbro","numero","sul","foglio","del","comune"]},{id:"s04",text:"Scansiona una cartella. Poi un'altra. Poi un'altra ancora.",speakerId:null,kind:"narration",lemmas:["scansionare","una","cartella","poi","altro","poi","altro","ancora"]},{id:"s05",text:"Le ore passano. Ha fame, poco. Ha sudore, s\xec.",speakerId:null,kind:"narration",lemmas:["le","ora","passare","avere","fame","poco","avere","sudore","si_yes"]},{id:"s06",text:"Mattina: liste. Poi copie. Poi un caff\xe8, in piedi, senza Alme.",speakerId:null,kind:"narration",lemmas:["mattina","lista","poi","copia","poi","un","caffe","in","piedi","senza","alme"]},{id:"s07",text:"A mezzogiorno ha scansionato abbastanza per sembrare normale. Il seminterrato aspetta.",speakerId:null,kind:"narration",lemmas:["a","mezzogiorno","avere","scansionare","abbastanza","per","sembrare","normale","il","seminterrato","aspettare"]},{id:"s08",text:"Non dovevo, pensa. Per\xf2 ieri ha detto: non so. Oggi le mani scelgono.",speakerId:null,kind:"narration",lemmas:["non","dovere","pensare","pero","ieri","avere","dire","non","sapere","oggi","le","mano","scegliere"]},{id:"s09",text:"C'\xe8 una scatola di registri, copie, liste. Non \xe8 la cartella chiusa. \xc8 una scatola normale.",speakerId:null,kind:"narration",lemmas:["ce","una","scatola","di","registro","copia","lista","non","essere","la","cartella","chiudere","essere","una","scatola","normale"]},{id:"s10",text:"Irene la prende. Non la mette sullo scanner. La porta pi\xf9 gi\xf9, nel seminterrato.",speakerId:null,kind:"narration",lemmas:["irene","la","prendere","non","la","mettere","sullo","scanner","la","portare","piu","giu","nel","seminterrato"]},{id:"s11",text:"L\xec ci sono altre scatole, vecchie, con polvere. Mette questa dietro, dove non si vede subito.",speakerId:null,kind:"narration",lemmas:["li","ci","essere","altro","scatola","vecchio","con","polvere","mettere","questo","dietro","dove","non","si","vedere","subito"]},{id:"s12",text:"Ho fatto un errore, dir\xe0, se qualcuno chiede. Per\xf2 sa: non \xe8 un errore. \xc8 una scelta.",speakerId:null,kind:"narration",lemmas:["avere","fare","un","errore","dire","se","qualcuno","chiedere","pero","sapere","non","essere","un","errore","essere","una","scelta"]},{id:"s13",text:"Le mani tremano. Chiude la porta del seminterrato. Sale. Lo scanner aspetta.",speakerId:null,kind:"narration",lemmas:["le","mano","tremare","chiudere","la","porta","del","seminterrato","salire","lo","scanner","aspettare"]}]},{id:"p2",order:2,sentences:[{id:"s14",text:"Lavora ancora. Scansiona quello che resta, le cartelle piccole, le liste corte.",speakerId:null,kind:"narration",lemmas:["lavorare","ancora","scansionare","quello","che","restare","le","cartella","piccolo","le","lista","corto"]},{id:"s15",text:"Ho fatto, pensa. Non dovevo. Per\xf2 venerd\xec \xe8 domani, e Sara ha chiesto tempo.",speakerId:null,kind:"narration",lemmas:["avere","fare","pensare","non","dovere","pero","venerdi","essere","domani","e","sara","avere","chiedere","tempo"]},{id:"s16",text:"Non \xe8 un eroe. Ha nascosto una scatola. Questo \xe8 tutto, e pesa.",speakerId:null,kind:"narration",lemmas:["non","essere","un","eroe","avere","nascondere","una","scatola","questo","essere","tutto","e","pesare"]},{id:"s17",text:"Alme scende nel pomeriggio, con una penna e un foglio di numeri.",speakerId:null,kind:"narration",lemmas:["alme","scendere","nel","pomeriggio","con","una","penna","e","un","foglio","di","numero"]},{id:"s18",text:"Conta le scatole. Una, due, tre. Poi di nuovo. Poi guarda lo spazio vuoto.",speakerId:null,kind:"narration",lemmas:["contare","le","scatola","una","due","tre","poi","di","nuovo","poi","guardare","lo","spazio","vuoto"]},{id:"s19",text:"Manca una.",speakerId:"alme",kind:"dialogue",lemmas:["mancare","una"]},{id:"s20",text:"Irene tiene lo scanner. Non guarda il seminterrato.",speakerId:null,kind:"narration",lemmas:["irene","tenere","lo","scanner","non","guardare","il","seminterrato"]},{id:"s21",text:"Forse un errore. Le ho contate stamattina.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["forse","un","errore","le","avere","contare","stamattina"]},{id:"s22",text:"Alme non alza la voce. Conta ancora. Lo spazio resta.",speakerId:null,kind:"narration",lemmas:["alme","non","alzare","la","voce","contare","ancora","lo","spazio","restare"]},{id:"s23",text:"Guarda Irene troppo a lungo. Non dice dove. Non dice: vieni da me.",speakerId:null,kind:"narration",lemmas:["guardare","irene","troppo","a","lungo","non","dire","dove","non","dire","venire","da","me"]},{id:"s24",text:"Poi sale, con il foglio. Non sorride, questa volta.",speakerId:null,kind:"narration",lemmas:["poi","salire","con","il","foglio","non","sorridere","questo","volta"]},{id:"s25",text:"Irene resta gi\xf9. Ha fatto. Non doveva. Per\xf2 la scatola \xe8 altrove, per un giorno.",speakerId:null,kind:"narration",lemmas:["irene","restare","giu","avere","fare","non","dovere","pero","la","scatola","essere","altrove","per","un","giorno"]},{id:"s26",text:"Il seminterrato \xe8 buio, un poco. Lei ha chiuso la porta. Le scatole vecchie coprono la nuova.",speakerId:null,kind:"narration",lemmas:["il","seminterrato","essere","buio","un","poco","lei","avere","chiudere","la","porta","le","scatola","vecchio","coprire","la","nuovo"]},{id:"s27",text:"Non \xe8 un piano grande. \xc8 un giorno. Domani la macchina vuole tutto.",speakerId:null,kind:"narration",lemmas:["non","essere","un","piano","grande","essere","un","giorno","domani","la","macchina","volere","tutto"]},{id:"s28",text:"Irene si lava le mani, gi\xf9, troppo a lungo. Il sudore resta.",speakerId:null,kind:"narration",lemmas:["irene","si","lavare","le","mano","giu","troppo","a","lungo","il","sudore","restare"]},{id:"s29",text:"Alme non torna. Il pomeriggio finisce. Irene sale, firma il foglio delle ore, esce.",speakerId:null,kind:"narration",lemmas:["alme","non","tornare","il","pomeriggio","finire","irene","salire","firmare","il","foglio","delle","ora","uscire"]},{id:"s30",text:"In strada sa che ha cambiato il lavoro, non solo il quaderno. Ha fatto. Non doveva.",speakerId:null,kind:"narration",lemmas:["in","strada","sapere","che","avere","cambiare","il","lavoro","non","solo","il","quaderno","avere","fare","non","dovere"]},{id:"s31",text:"Passa le ore dopo il lavoro senza dire a Sara: l'ho fatto. Non la cerca gioved\xec sera.",speakerId:null,kind:"narration",lemmas:["passare","le","ora","dopo","il","lavoro","senza","dire","a","sara","avere","fare","non","la","cercare","giovedi","sera"]},{id:"s32",text:"La scatola sta nel seminterrato. Alme ha contato. Lo sguardo \xe8 stato troppo lungo. Questo \xe8 il costo, oggi.",speakerId:null,kind:"narration",lemmas:["la","scatola","stare","nel","seminterrato","alme","avere","contare","lo","sguardo","essere","stato","troppo","lungo","questo","essere","il","costo","oggi"]},{id:"s33",text:"Domani \xe8 venerd\xec. Irene sa dove \xe8 la scatola. Sa anche che Alme sa che manca qualcosa.",speakerId:null,kind:"narration",lemmas:["domani","essere","venerdi","irene","sapere","dove","essere","la","scatola","sapere","anche","che","alme","sapere","che","mancare","qualcosa"]},{id:"s34",text:"Nel seminterrato ha contato i passi. Dieci, forse. Ha messo la scatola dietro due pi\xf9 vecchie.",speakerId:null,kind:"narration",lemmas:["nel","seminterrato","avere","contare","i","passo","dieci","forse","avere","mettere","la","scatola","dietro","due","piu","vecchio"]},{id:"s35",text:"Ha chiuso. \xc8 salita. Ha scansionato ancora, per sembrare uguale a ieri, a mercoled\xec.",speakerId:null,kind:"narration",lemmas:["avere","chiudere","essere","salire","avere","scansionare","ancora","per","sembrare","uguale","a","ieri","a","mercoledi"]},{id:"s36",text:"Alme ha detto: manca una. Irene ha detto: forse un errore. Era una bugia, la seconda.",speakerId:null,kind:"narration",lemmas:["alme","avere","dire","mancare","una","irene","avere","dire","forse","un","errore","essere","una","bugia","la","secondo"]},{id:"s37",text:"La prima era no, qualcosa di strano. Questa \xe8 pi\xf9 pesante. Non doveva. Per\xf2 l'ha fatto.",speakerId:null,kind:"narration",lemmas:["la","primo","essere","no","qualcosa","di","strano","questo","essere","piu","pesante","non","dovere","pero","avere","fare"]},{id:"s38",text:"Gioved\xec finisce cos\xec: una scatola altrove, uno sguardo troppo lungo, e Irene che esce senza caff\xe8.",speakerId:null,kind:"narration",lemmas:["giovedi","finire","cosi","una","scatola","altrove","uno","sguardo","troppo","lungo","e","irene","che","uscire","senza","caffe"]},{id:"s39",text:"Ha lavorato dalle nove alle quattro, quasi. Poi dieci minuti gi\xf9, nel seminterrato. Poi di nuovo lo scanner.",speakerId:null,kind:"narration",lemmas:["avere","lavorare","dalle","nove","alle","quattro","quasi","poi","dieci","minuto","giu","nel","seminterrato","poi","di","nuovo","lo","scanner"]},{id:"s40",text:"Nessuno l'ha vista portare la scatola. O Alme l'ha vista, e non ha detto. Irene non sa.",speakerId:null,kind:"narration",lemmas:["nessuno","avere","vedere","portare","la","scatola","o","alme","avere","vedere","e","non","avere","dire","irene","non","sapere"]},{id:"s41",text:"Non \xe8 un colpo. \xc8 un errore voluto, in un comune piccolo, un gioved\xec prima della macchina.",speakerId:null,kind:"narration",lemmas:["non","essere","un","colpo","essere","un","errore","volere","in","un","comune","piccolo","un","giovedi","prima","della","macchina"]},{id:"s42",text:"Irene cammina a casa con le mani in tasca. Non c'\xe8 la chiavetta, non ancora. C'\xe8 solo il sudore.",speakerId:null,kind:"narration",lemmas:["irene","camminare","a","casa","con","le","mano","in","tasca","non","ce","la","chiavetta","non","ancora","ce","solo","il","sudore"]},{id:"s43",text:"Gioved\xec non \xe8 venerd\xec. La macchina non ha preso quella scatola. Un giorno di tempo, sporco, vero.",speakerId:null,kind:"narration",lemmas:["giovedi","non","essere","venerdi","la","macchina","non","avere","prendere","quello","scatola","un","giorno","di","tempo","sporco","vero"]},{id:"s44",text:"Ho fatto, non dovevo, per\xf2: tre pezzi. Irene li tiene tutti, senza perdere il per\xf2.",speakerId:null,kind:"narration",lemmas:["avere","fare","non","dovere","pero","tre","pezzo","irene","li","tenere","tutto","senza","perdere","il","pero"]},{id:"s45",text:"Il seminterrato resta chiuso. Le scale restano. Lo scanner resta. Lei esce, e il comune resta con un buco.",speakerId:null,kind:"narration",lemmas:["il","seminterrato","restare","chiudere","le","scala","restare","lo","scanner","restare","lei","uscire","e","il","comune","restare","con","un","buco"]},{id:"s46",text:"Alme non ha chiamato. Non ancora. Gioved\xec sera \xe8 questo silenzio, pi\xf9 pesante del caff\xe8.",speakerId:null,kind:"narration",lemmas:["alme","non","avere","chiamare","non","ancora","giovedi","sera","essere","questo","silenzio","piu","pesante","del","caffe"]},{id:"s47",text:"Irene va verso la scuola, non verso casa. Ha bisogno di aria. Trover\xe0 Quinto, o no. \xc8 ancora gioved\xec.",speakerId:null,kind:"narration",lemmas:["irene","andare","verso","la","scuola","non","verso","casa","avere","bisogno","di","aria","trovare","quinto","o","no","essere","ancora","giovedi"]}]}],questions:[{id:"ch18_q01",chapterId:"la-casa-delle-finestre-18",type:"direct",question:"What day is it?",choices:["Thursday","Friday","Tuesday"],correctChoice:0,explanation:"Today is Thursday. Yesterday she saw Sara. Tomorrow is Friday.",difficulty:2},{id:"ch18_q02",chapterId:"la-casa-delle-finestre-18",type:"event",question:"What does Irene do with a box of registers?",choices:["She hides it in the basement on purpose","She scans it at once","She gives it to Quinto"],correctChoice:0,explanation:"She carries it into the basement and puts it behind other boxes.",difficulty:2},{id:"ch18_q03",chapterId:"la-casa-delle-finestre-18",type:"inference",question:"How does Irene feel about it?",choices:["She knows it is wrong","She thinks it is a joke","She tells Alme immediately"],correctChoice:0,explanation:"I did it. I should not have. It is not a mistake. It is a choice.",difficulty:2},{id:"ch18_q04",chapterId:"la-casa-delle-finestre-18",type:"character",question:"What does Alme do?",choices:["She counts, sees a gap, looks at Irene too long, and says nothing yet","She calls Piva","She laughs and goes for coffee"],correctChoice:0,explanation:"One is missing. She looks too long. She does not smile this time.",difficulty:2}]}},1021,[]);
__d(function(e,a,n,o,r,i,s){r.exports={id:"la-casa-delle-finestre-19",storyId:"la-casa-delle-finestre",number:19,title:"Quinto changes",titleIt:"Quinto cambia",locationIds:["via-della-scuola","cortile-scuola","scuola-media"],characterIds:["irene-colombo","quinto-belli"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-19",summary:"Thursday after work, Quinto finds Irene. He knew about the cracks. He will not talk to the Carabinieri. He will not stop Sara. Later Irene sees the gate unchained once.",characterIds:["irene-colombo","quinto-belli"],locationIds:["via-della-scuola","cortile-scuola"],rememberedFacts:["It is still Thursday, after work","Quinto knew the building had cracks","He will not speak to Piva","He will not block Sara","He leaves the gate unchained once, for her, not for Irene"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"\xc8 ancora gioved\xec, dopo il lavoro. Irene non va subito a casa.",speakerId:null,kind:"narration",lemmas:["essere","ancora","giovedi","dopo","il","lavoro","irene","non","andare","subito","a","casa"]},{id:"s02",text:"Cammina verso la scuola. Ha bisogno di aria, non di una chiave.",speakerId:null,kind:"narration",lemmas:["camminare","verso","la","scuola","avere","bisogno","di","aria","non","di","una","chiave"]},{id:"s03",text:"Quinto \xe8 l\xec, vicino al cancello, senza tanica. Le chiavi ci sono, in tasca.",speakerId:null,kind:"narration",lemmas:["quinto","essere","li","vicino","al","cancello","senza","tanica","le","chiave","ci","essere","in","tasca"]},{id:"s04",text:"Signorina. Oggi ha fatto qualcosa, al comune.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["signorina","oggi","avere","fare","qualcosa","al","comune"]},{id:"s05",text:"Irene si ferma di qua. Non mente bene. Non spiega la scatola.",speakerId:null,kind:"narration",lemmas:["irene","si","fermare","di","qua","non","mentire","bene","non","spiegare","la","scatola"]},{id:"s06",text:"Ho lavorato.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["avere","lavorare"]},{id:"s07",text:"Quinto annuisce. Non offre la chiave, questa volta.",speakerId:null,kind:"narration",lemmas:["quinto","annuire","non","offrire","la","chiave","questo","volta"]},{id:"s08",text:"Sapevo delle crepe. Prima della chiusura. Le ho viste, su.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["sapere","delle","crepa","prima","della","chiusura","le","avere","vedere","su"]},{id:"s09",text:"Irene ascolta. Non \xe8 un discorso lungo. \xc8 un fatto, tardi.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","non","essere","un","discorso","lungo","essere","un","fatto","tardi"]},{id:"s10",text:"Non posso parlare con i carabinieri. Non dico niente al maresciallo.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["non","potere","parlare","con","i","carabinieri","non","dire","niente","al","maresciallo"]},{id:"s11",text:"Non fermo Sara. Lei entra, a modo suo. Io non la fermo.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["non","fermare","sara","lei","entrare","a","modo","suo","io","non","la","fermare"]},{id:"s12",text:"Irene guarda il cancello. La catena c'\xe8 ancora, per ora.",speakerId:null,kind:"narration",lemmas:["irene","guardare","il","cancello","la","catena","ce","ancora","per","ora"]},{id:"s13",text:"Perch\xe9 me lo dice?",speakerId:"irene-colombo",kind:"dialogue",lemmas:["perche","me","lo","dire"]},{id:"s14",text:"Perch\xe9 lei guarda. Perch\xe9 io annaffio piante morte, e lei conta finestre.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["perche","lei","guardare","perche","io","annaffiare","pianta","morto","e","lei","contare","finestra"]},{id:"s15",text:"Irene non ride. Le piante morte le ha viste il secondo giorno. Adesso capisce la frase.",speakerId:null,kind:"narration",lemmas:["irene","non","ridere","le","pianta","morto","le","avere","vedere","il","secondo","giorno","adesso","capire","la","frase"]},{id:"s16",text:"Non va su, dice. Non parla. Non ferma Sara. Tre no, come i suoi, e diversi.",speakerId:null,kind:"narration",lemmas:["non","andare","su","dire","non","parlare","non","fermare","sara","tre","no","come","i","suo","e","diverso"]}]},{id:"p2",order:2,sentences:[{id:"s17",text:"Quinto non chiede perdono. Non dice: ero buono. Dice poco.",speakerId:null,kind:"narration",lemmas:["quinto","non","chiedere","perdono","non","dire","essere","buono","dire","poco"]},{id:"s18",text:"Annaffio piante morte cos\xec non vado su.",speakerId:"quinto-belli",kind:"dialogue",lemmas:["annaffiare","pianta","morto","cosi","non","andare","su"]},{id:"s19",text:"Poi cammina via, verso il cortile, con le chiavi.",speakerId:null,kind:"narration",lemmas:["poi","camminare","via","verso","il","cortile","con","le","chiave"]},{id:"s20",text:"Irene resta di qua. Non entra. Non \xe8 la sua porta.",speakerId:null,kind:"narration",lemmas:["irene","restare","di","qua","non","entrare","non","essere","la","suo","porta"]},{id:"s21",text:"Pi\xf9 tardi, tornando a casa, passa di nuovo. Guarda il cancello.",speakerId:null,kind:"narration",lemmas:["piu","tardi","tornare","a","casa","passare","di","nuovo","guardare","il","cancello"]},{id:"s22",text:"La catena non c'\xe8. Il cancello \xe8 chiuso, ma senza catena. Una volta.",speakerId:null,kind:"narration",lemmas:["la","catena","non","ce","il","cancello","essere","chiudere","ma","senza","catena","una","volta"]},{id:"s23",text:"Non \xe8 per lei. Lo sa. \xc8 per Sara, se Sara entra, a modo suo.",speakerId:null,kind:"narration",lemmas:["non","essere","per","lei","lo","sapere","essere","per","sara","se","sara","entrare","a","modo","suo"]},{id:"s24",text:"Irene non prova il cancello. Non prende l'apertura come un invito.",speakerId:null,kind:"narration",lemmas:["irene","non","provare","il","cancello","non","prendere","apertura","come","un","invito"]},{id:"s25",text:"Scrive: Quinto sapeva. Non parla. Non ferma Sara. Cancello senza catena, una volta, non per me.",speakerId:null,kind:"narration",lemmas:["scrivere","quinto","sapere","non","parlare","non","fermare","sara","cancello","senza","catena","una","volta","non","per","me"]},{id:"s26",text:"Domani \xe8 venerd\xec. Oggi resta gioved\xec, ancora, fino alla notte.",speakerId:null,kind:"narration",lemmas:["domani","essere","venerdi","oggi","restare","giovedi","ancora","fino","alla","notte"]},{id:"s27",text:"Quinto non \xe8 la luce. Irene lo sapeva. Adesso sa anche: lui ha visto le crepe, e ha taciuto.",speakerId:null,kind:"narration",lemmas:["quinto","non","essere","la","luce","irene","lo","sapere","adesso","sapere","anche","lui","avere","vedere","le","crepa","e","avere","tacere"]},{id:"s28",text:"Non \xe8 coraggio. Non \xe8 un nemico. \xc8 un uomo con una tanica, e una catena tolta una volta.",speakerId:null,kind:"narration",lemmas:["non","essere","coraggio","non","essere","un","nemico","essere","un","uomo","con","una","tanica","e","una","catena","togliere","una","volta"]},{id:"s29",text:"Irene non usa il cancello. Torna in mansarda. Non guarda la griglia per contare. Sa chi si muove di l\xe0.",speakerId:null,kind:"narration",lemmas:["irene","non","usare","il","cancello","tornare","in","mansarda","non","guardare","la","griglia","per","contare","sapere","chi","si","muovere","di","la"]},{id:"s30",text:"Domani la macchina. Domani Alme. Stasera solo questo: Quinto cambia, poco, e non parla con Piva.",speakerId:null,kind:"narration",lemmas:["domani","la","macchina","domani","alme","stasera","solo","questo","quinto","cambiare","poco","e","non","parlare","con","piva"]},{id:"s31",text:"Non \xe8 una redenzione. Non muore. Non diventa buono in tre frasi.",speakerId:null,kind:"narration",lemmas:["non","essere","una","redenzione","non","morire","non","diventare","buono","in","tre","frase"]},{id:"s32",text:"Toglie una catena una volta, per Sara. Irene vede, e non entra. Questo \xe8 il capitolo, non di pi\xf9.",speakerId:null,kind:"narration",lemmas:["togliere","una","catena","una","volta","per","sara","irene","vedere","e","non","entrare","questo","essere","il","capitolo","non","di","piu"]},{id:"s33",text:"Quinto parla poco, come sempre. Non fa un discorso di salvezza. Dice: sapevo. Non posso. Non fermo.",speakerId:null,kind:"narration",lemmas:["quinto","parlare","poco","come","sempre","non","fare","un","discorso","di","salvezza","dire","sapere","non","potere","non","fermare"]},{id:"s34",text:"Irene chiede delle crepe, una volta. Lui dice: su, il muro. I bambini no. Poi tace.",speakerId:null,kind:"narration",lemmas:["irene","chiedere","delle","crepa","una","volta","lui","dire","su","il","muro","i","bambino","no","poi","tacere"]},{id:"s35",text:"Non testimonia. Non usa quella parola. Dice: non parlo con i carabinieri.",speakerId:null,kind:"narration",lemmas:["non","testimoniare","non","usare","quello","parola","dire","non","parlare","con","i","carabinieri"]},{id:"s36",text:"La catena a terra, o via: Irene non la cerca. Vede solo il cancello senza ferro intorno.",speakerId:null,kind:"narration",lemmas:["la","catena","a","terra","o","via","irene","non","la","cercare","vedere","solo","il","cancello","senza","ferro","intorno"]},{id:"s37",text:"Gioved\xec notte. Domani venerd\xec. Quinto resta il custode. Non \xe8 la lampada. Non \xe8 un eroe.",speakerId:null,kind:"narration",lemmas:["giovedi","notte","domani","venerdi","quinto","restare","il","custode","non","essere","la","lampada","non","essere","un","eroe"]},{id:"s38",text:"Irene ripete le sue parole, in testa: sapevo, non posso, non dico, non fermo Sara.",speakerId:null,kind:"narration",lemmas:["irene","ripetere","le","suo","parola","in","testa","sapere","non","potere","non","dire","non","fermare","sara"]},{id:"s39",text:"Annaffio piante morte cos\xec non vado su: questa resta. \xc8 la frase pi\xf9 vera della sera.",speakerId:null,kind:"narration",lemmas:["annaffiare","pianta","morto","cosi","non","andare","su","questo","restare","essere","la","frase","piu","vero","della","sera"]},{id:"s40",text:"Il cancello senza catena non \xe8 per l'archivista. \xc8 una volta, per l'insegnante, se entra.",speakerId:null,kind:"narration",lemmas:["il","cancello","senza","catena","non","essere","per","archivista","essere","una","volta","per","insegnante","se","entrare"]},{id:"s41",text:"Irene sale in mansarda. Non prova le chiavi che non ha. Domani \xe8 venerd\xec, non un'esplorazione.",speakerId:null,kind:"narration",lemmas:["irene","salire","in","mansarda","non","provare","le","chiave","che","non","avere","domani","essere","venerdi","non","esplorazione"]},{id:"s42",text:"Non entra. Non \xe8 il suo cancello. Quinto l'ha detto senza dirlo: per Sara, non per me.",speakerId:null,kind:"narration",lemmas:["non","entrare","non","essere","il","suo","cancello","quinto","avere","dire","senza","dire","per","sara","non","per","me"]},{id:"s43",text:"Irene accetta il no all'ingresso. Ha gi\xe0 un s\xec sporco, al comune, nella scatola nascosta.",speakerId:null,kind:"narration",lemmas:["irene","accettare","il","no","ingresso","avere","gia","un","si_yes","sporco","al","comune","nella","scatola","nascondere"]},{id:"s44",text:"Due s\xec diversi: uno \xe8 una scatola persa. Uno sarebbe entrare. Lei ha fatto il primo, non il secondo.",speakerId:null,kind:"narration",lemmas:["due","si_yes","diverso","uno","essere","una","scatola","perdere","uno","essere","entrare","lei","avere","fare","il","primo","non","il","secondo"]},{id:"s45",text:"Quinto va via. Irene va via. La scuola resta, con il cancello un po' pi\xf9 aperto, non per lei.",speakerId:null,kind:"narration",lemmas:["quinto","andare","via","irene","andare","via","la","scuola","restare","con","il","cancello","un","po","piu","aprire","non","per","lei"]},{id:"s46",text:"Lei non \xe8 Quinto. Non annaffia. Non ha chiavi. Ha una scatola persa, e un venerd\xec davanti.",speakerId:null,kind:"narration",lemmas:["lei","non","essere","quinto","non","annaffiare","non","avere","chiave","avere","una","scatola","perdere","e","un","venerdi","davanti"]},{id:"s47",text:"Scrive la catena. Scrive: non per me. Chiude. Domani \xe8 venerd\xec, non gioved\xec. La notte \xe8 ancora gioved\xec.",speakerId:null,kind:"narration",lemmas:["scrivere","la","catena","scrivere","non","per","me","chiudere","domani","essere","venerdi","non","giovedi","la","notte","essere","ancora","giovedi"]},{id:"s48",text:"Non \xe8 un altro giorno. \xc8 lo stesso gioved\xec, tardi. Poi, solo dopo, venerd\xec. Questo \xe8 tutto, stasera.",speakerId:null,kind:"narration",lemmas:["non","essere","un","altro","giorno","essere","lo","stesso","giovedi","tardi","poi","solo","dopo","venerdi","questo","essere","tutto","stasera"]}]}],questions:[{id:"ch19_q01",chapterId:"la-casa-delle-finestre-19",type:"direct",question:"When does this happen?",choices:["Thursday after work","Friday morning","Tuesday at the comune"],correctChoice:0,explanation:"It is still Thursday, after work. Tomorrow is Friday.",difficulty:2},{id:"ch19_q02",chapterId:"la-casa-delle-finestre-19",type:"character",question:"What did Quinto know?",choices:["The cracks, before the closure","That Irene is the lamp","Alme\u2019s USB"],correctChoice:0,explanation:"I knew about the cracks. I saw them upstairs.",difficulty:2},{id:"ch19_q03",chapterId:"la-casa-delle-finestre-19",type:"event",question:"What will Quinto not do?",choices:["Talk to the Carabinieri, or stop Sara","Water the plants","Keep the keys"],correctChoice:0,explanation:"He will not speak to the marshal. He will not stop Sara.",difficulty:2},{id:"ch19_q04",chapterId:"la-casa-delle-finestre-19",type:"inference",question:"Why is the gate unchained once?",choices:["For Sara, not as an invitation for Irene","So Irene can explore the school","Because Quinto lost the chain"],correctChoice:0,explanation:"It is not for her. It is for Sara, in her way. Irene does not try the gate.",difficulty:2}]}},1022,[]);
__d(function(e,a,r,n,o,i,t){o.exports={id:"la-casa-delle-finestre-20",storyId:"la-casa-delle-finestre",number:20,title:"Friday",titleIt:"Venerd\xec",locationIds:["comune","ufficio-alme","scatole-comune"],characterIds:["irene-colombo","alme"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-20",summary:"Friday: papers are destroyed. Irene copies files onto a USB stick. Alme finds her in the corridor and says come with me.",characterIds:["irene-colombo","alme"],locationIds:["comune"],rememberedFacts:["Today is Friday; papers are to be destroyed","Irene copies files onto a USB stick","Alme intercepts Irene in the corridor and tells her to come with her"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Oggi \xe8 venerd\xec. Non \xe8 marted\xec. Non \xe8 mercoled\xec. Non \xe8 gioved\xec.",speakerId:null,kind:"narration",lemmas:["oggi","essere","venerdi","non","essere","martedi","non","essere","mercoledi","non","essere","giovedi"]},{id:"s02",text:"Al comune la macchina per distruggere \xe8 accesa. Fa rumore. Puzza di carta calda.",speakerId:null,kind:"narration",lemmas:["al","comune","la","macchina","per","distruggere","essere","accendere","fare","rumore","puzzare","di","carta","caldo"]},{id:"s03",text:"Alme \xe8 in ufficio presto. Dice: oggi. Non c'\xe8 tempo. Manca poco.",speakerId:null,kind:"narration",lemmas:["alme","essere","in","ufficio","presto","dire","oggi","non","ce","tempo","mancare","poco"]},{id:"s04",text:"Manca un'ora, dice dopo, o due. Irene non guarda l'orologio. Guarda le scatole.",speakerId:null,kind:"narration",lemmas:["mancare","ora","dire","dopo","o","due","irene","non","guardare","orologio","guardare","le","scatola"]},{id:"s05",text:"Adesso, troppa carta. Adesso, la macchina. Adesso, o mai.",speakerId:null,kind:"narration",lemmas:["adesso","troppa","carta","adesso","la","macchina","adesso","o","mai"]},{id:"s06",text:"Irene porta su le scatole che restano. Una dopo l'altra. Non quella del seminterrato, non ancora.",speakerId:null,kind:"narration",lemmas:["irene","portare","su","le","scatola","che","restare","una","dopo","altro","non","quello","del","seminterrato","non","ancora"]},{id:"s07",text:"Adesso \xe8 tardi per chiamare Piva, pensa. Adesso \xe8 tardi per dire non so.",speakerId:null,kind:"narration",lemmas:["adesso","essere","tardi","per","chiamare","piva","pensare","adesso","essere","tardi","per","dire","non","sapere"]},{id:"s08",text:"Ha una chiavetta, piccola, in tasca. L'ha comprata ieri sera, dopo Quinto.",speakerId:null,kind:"narration",lemmas:["avere","una","chiavetta","piccolo","in","tasca","avere","comprare","ieri","sera","dopo","quinto"]},{id:"s09",text:"Non \xe8 internet. Non \xe8 un film. \xc8 una copia, se riesce.",speakerId:null,kind:"narration",lemmas:["non","essere","internet","non","essere","un","film","essere","una","copia","se","riuscire"]}]},{id:"p2",order:2,sentences:[{id:"s10",text:"Quando Alme parla al telefono, Irene \xe8 sola un minuto, gi\xf9.",speakerId:null,kind:"narration",lemmas:["quando","alme","parlare","al","telefono","irene","essere","solo","un","minuto","giu"]},{id:"s11",text:"Apre il computer del comune, quello dello scanner. Mette la chiavetta.",speakerId:null,kind:"narration",lemmas:["aprire","il","computer","del","comune","quello","dello","scanner","mettere","la","chiavetta"]},{id:"s12",text:"Copia le cartelle gi\xe0 scansionate. Copia in fretta, non tutto, abbastanza.",speakerId:null,kind:"narration",lemmas:["copiare","le","cartella","gia","scansionare","copiare","in","fretta","non","tutto","abbastanza"]},{id:"s13",text:"Il cuore va. Manca un'ora, o meno, prima che la macchina prenda il resto.",speakerId:null,kind:"narration",lemmas:["il","cuore","andare","mancare","ora","o","meno","prima","che","la","macchina","prendere","il","resto"]},{id:"s14",text:"Toglie la chiavetta. La mette in tasca. Chiude lo schermo.",speakerId:null,kind:"narration",lemmas:["togliere","la","chiavetta","la","mettere","in","tasca","chiudere","lo","schermo"]},{id:"s15",text:"Poi sale con una scatola normale, per la macchina. Fa il lavoro visibile.",speakerId:null,kind:"narration",lemmas:["poi","salire","con","una","scatola","normale","per","la","macchina","fare","il","lavoro","visibile"]},{id:"s16",text:"Alme indica. Irene mette le carte nella macchina. Troppo tardi per fermarsi. Il rumore continua.",speakerId:null,kind:"narration",lemmas:["alme","indicare","irene","mettere","le","carta","nella","macchina","troppo","tardi","per","fermare","il","rumore","continuare"]},{id:"s17",text:"La scatola del seminterrato resta gi\xf9. Per ora. Irene non la porta su.",speakerId:null,kind:"narration",lemmas:["la","scatola","del","seminterrato","restare","giu","per","ora","irene","non","la","portare","su"]}]},{id:"p3",order:3,sentences:[{id:"s18",text:"Nel corridoio, dopo, Irene va verso le scale, con la mano in tasca.",speakerId:null,kind:"narration",lemmas:["nel","corridoio","dopo","irene","andare","verso","le","scala","con","la","mano","in","tasca"]},{id:"s19",text:"Alme \xe8 l\xec. Non urla. Non corre. \xc8 solo nel corridoio, di fronte.",speakerId:null,kind:"narration",lemmas:["alme","essere","li","non","urlare","non","correre","essere","solo","nel","corridoio","di","fronte"]},{id:"s20",text:"Guarda la tasca di Irene, o sembra. Poi guarda gli occhi.",speakerId:null,kind:"narration",lemmas:["guardare","la","tasca","di","irene","o","sembrare","poi","guardare","gli","occhio"]},{id:"s21",text:"Venga con me.",speakerId:"alme",kind:"dialogue",lemmas:["venire","con","me"]},{id:"s22",text:"Non \xe8 un grido. \xc8 una frase, piano, come il caff\xe8 di altri giorni, e non lo \xe8.",speakerId:null,kind:"narration",lemmas:["non","essere","un","grido","essere","una","frase","piano","come","il","caffe","di","altro","giorno","e","non","lo","essere"]},{id:"s23",text:"Irene non scappa. Non butta la chiavetta. Cammina dietro Alme, verso l'ufficio.",speakerId:null,kind:"narration",lemmas:["irene","non","scappare","non","buttare","la","chiavetta","camminare","dietro","alme","verso","ufficio"]},{id:"s24",text:"Oggi \xe8 venerd\xec. La macchina lavora. La copia \xe8 in tasca. Alme ha detto: venga con me.",speakerId:null,kind:"narration",lemmas:["oggi","essere","venerdi","la","macchina","lavorare","la","copia","essere","in","tasca","alme","avere","dire","venire","con","me"]},{id:"s25",text:"Irene non sa ancora che cosa far\xe0 Alme. Sa solo che il corridoio \xe8 finito, e la porta \xe8 aperta.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","ancora","che","cosa","fare","alme","sapere","solo","che","il","corridoio","essere","finire","e","la","porta","essere","aprire"]},{id:"s26",text:"La chiavetta pesa poco. Le carte nella macchina non tornano. Manca poco, e troppo, insieme.",speakerId:null,kind:"narration",lemmas:["la","chiavetta","pesare","poco","le","carta","nella","macchina","non","tornare","mancare","poco","e","troppo","insieme"]},{id:"s27",text:"Non carica niente su internet. Non corre. Segue Alme. Venerd\xec \xe8 adesso.",speakerId:null,kind:"narration",lemmas:["non","caricare","niente","su","internet","non","correre","seguire","alme","venerdi","essere","adesso"]},{id:"s28",text:"Nel corridoio il rumore della macchina arriva ancora. Troppo tardi per le carte gi\xe0 dentro.",speakerId:null,kind:"narration",lemmas:["nel","corridoio","il","rumore","della","macchina","arrivare","ancora","troppo","tardi","per","le","carta","gia","dentro"]},{id:"s29",text:"Irene tiene la chiavetta. Alme tiene la porta. Due donne. Nessuna corsa. Una frase: venga con me.",speakerId:null,kind:"narration",lemmas:["irene","tenere","la","chiavetta","alme","tenere","la","porta","due","donna","nessuno","corsa","una","frase","venire","con","me"]},{id:"s30",text:"La mattina ha portato scatole su. A mezzogiorno la macchina mangiava gi\xe0. Nel pomeriggio manca poco.",speakerId:null,kind:"narration",lemmas:["la","mattina","avere","portare","scatola","su","a","mezzogiorno","la","macchina","mangiare","gia","nel","pomeriggio","mancare","poco"]},{id:"s31",text:"Ha copiato quando Alme era al telefono. Un minuto. Cartelle gi\xe0 nello scanner, non il seminterrato.",speakerId:null,kind:"narration",lemmas:["avere","copiare","quando","alme","essere","al","telefono","un","minuto","cartella","gia","nello","scanner","non","il","seminterrato"]},{id:"s32",text:"La chiavetta \xe8 una copia. Le carte vive vanno nella macchina. Due destini, venerd\xec.",speakerId:null,kind:"narration",lemmas:["la","chiavetta","essere","una","copia","le","carta","vivo","andare","nella","macchina","due","destino","venerdi"]},{id:"s33",text:"Nel corridoio Alme non grida. Dice venga con me, e Irene va, perch\xe9 scappare \xe8 un altro film.",speakerId:null,kind:"narration",lemmas:["nel","corridoio","alme","non","gridare","dire","venire","con","me","e","irene","andare","perche","scappare","essere","un","altro","film"]},{id:"s34",text:"La scelta di Alme non c'\xe8 ancora. C'\xe8 venerd\xec, la macchina, la tasca, e una porta.",speakerId:null,kind:"narration",lemmas:["la","scelta","di","alme","non","ce","ancora","ce","venerdi","la","macchina","la","tasca","e","una","porta"]},{id:"s35",text:"Alle nove: scatole. Alle undici: rumore. All'una: chiavetta. Alle tre: corridoio. Adesso: l'ufficio.",speakerId:null,kind:"narration",lemmas:["alle","nove","scatola","alle","undici","rumore","una","chiavetta","alle","tre","corridoio","adesso","ufficio"]},{id:"s36",text:"Troppo tardi per marted\xec. Troppo tardi per non so. Venerd\xec chiede una copia, e una porta chiusa dopo.",speakerId:null,kind:"narration",lemmas:["troppo","tardi","per","martedi","troppo","tardi","per","non","sapere","venerdi","chiedere","una","copia","e","una","porta","chiudere","dopo"]},{id:"s37",text:"Irene non sa se Alme ha visto la chiavetta. Sa che Alme ha visto lei, nel corridoio.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","se","alme","avere","vedere","la","chiavetta","sapere","che","alme","avere","vedere","lei","nel","corridoio"]},{id:"s38",text:"Venga con me. Irene va. La macchina continua. La storia non \xe8 finita in strada.",speakerId:null,kind:"narration",lemmas:["venire","con","me","irene","andare","la","macchina","continuare","la","storia","non","essere","finire","in","strada"]},{id:"s39",text:"Nove, undici, una, tre: venerd\xec ha ore, non settimane. Manca poco. Adesso \xe8 l'ufficio.",speakerId:null,kind:"narration",lemmas:["nove","undici","una","tre","venerdi","avere","ora","non","settimana","mancare","poco","adesso","essere","ufficio"]},{id:"s40",text:"Irene non butta la chiavetta nel corridoio. La tiene. Entra. Alme chiude la porta, piano.",speakerId:null,kind:"narration",lemmas:["irene","non","buttare","la","chiavetta","nel","corridoio","la","tenere","entrare","alme","chiudere","la","porta","piano"]},{id:"s41",text:"Fuori, la macchina lavora ancora. Dentro, due sedie, un ufficio, venerd\xec pomeriggio.",speakerId:null,kind:"narration",lemmas:["fuori","la","macchina","lavorare","ancora","dentro","due","sedia","un","ufficio","venerdi","pomeriggio"]},{id:"s42",text:"Irene aspetta che Alme parli. Non parla ancora. Questo \xe8 l'ultimo fatto del capitolo: la porta \xe8 chiusa, la scelta no.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","che","alme","parlare","non","parlare","ancora","questo","essere","ultimo","fatto","del","capitolo","la","porta","essere","chiudere","la","scelta","no"]},{id:"s43",text:"Venerd\xec mattina, venerd\xec mezzogiorno, venerd\xec pomeriggio: tre pezzi dello stesso giorno, non tre giorni nuovi.",speakerId:null,kind:"narration",lemmas:["venerdi","mattina","venerdi","mezzogiorno","venerdi","pomeriggio","tre","pezzo","dello","stesso","giorno","non","tre","giorno","nuovo"]},{id:"s44",text:"La copia \xe8 in tasca. Le carte sono nella macchina. Alme \xe8 di fronte. Manca un'ora, o \xe8 gi\xe0 tardi.",speakerId:null,kind:"narration",lemmas:["la","copia","essere","in","tasca","le","carta","essere","nella","macchina","alme","essere","di","fronte","mancare","ora","o","essere","gia","tardi"]},{id:"s45",text:"Irene siede. Non spiega ancora. Aspetta. Questo \xe8 venerd\xec, fino in fondo. Non \xe8 sabato. Non \xe8 un altro marted\xec.",speakerId:null,kind:"narration",lemmas:["irene","sedere","non","spiegare","ancora","aspettare","questo","essere","venerdi","fino","in","fondo","non","essere","sabato","non","essere","un","altro","martedi"]},{id:"s46",text:"Alme resta in piedi. Irene resta seduta. Tra loro il tavolo. Nella tasca la chiavetta. Fuori il rumore.",speakerId:null,kind:"narration",lemmas:["alme","restare","in","piedi","irene","restare","sedere","tra","loro","il","tavolo","nella","tasca","la","chiavetta","fuori","il","rumore"]},{id:"s47",text:"Nessuno corre. Nessuno urla. Venerd\xec chiede solo questo, per ora: due donne, una porta, e niente ancora detto.",speakerId:null,kind:"narration",lemmas:["nessuno","correre","nessuno","urlare","venerdi","chiedere","solo","questo","per","ora","due","donna","una","porta","e","niente","ancora","dire"]},{id:"s48",text:"Adesso. Troppo tardi. Manca poco. Tre modi di dire lo stesso venerd\xec.",speakerId:null,kind:"narration",lemmas:["adesso","troppo","tardi","mancare","poco","tre","modo","di","dire","lo","stesso","venerdi"]},{id:"s49",text:"Dietro la porta c'\xe8 l'ufficio. Non c'\xe8 ancora una scelta di Alme. C'\xe8 solo: venga con me.",speakerId:null,kind:"narration",lemmas:["dietro","la","porta","ce","ufficio","non","ce","ancora","una","scelta","di","alme","ce","solo","venire","con","me"]}]}],questions:[{id:"ch20_q01",chapterId:"la-casa-delle-finestre-20",type:"direct",question:"What day is it?",choices:["Friday","Wednesday","Thursday"],correctChoice:0,explanation:"Today is Friday. Papers are to be destroyed.",difficulty:2},{id:"ch20_q02",chapterId:"la-casa-delle-finestre-20",type:"event",question:"What does Irene put in her pocket?",choices:["A USB stick with copies","Quinto\u2019s key","The whole basement box"],correctChoice:0,explanation:"She copies scanned folders onto a chiavetta. Not the internet.",difficulty:2},{id:"ch20_q03",chapterId:"la-casa-delle-finestre-20",type:"character",question:"What does Alme say in the corridor?",choices:["Come with me","Run","I will help you twice"],correctChoice:0,explanation:"She does not shout. She says: Come with me.",difficulty:2},{id:"ch20_q04",chapterId:"la-casa-delle-finestre-20",type:"inference",question:"Do we know Alme\u2019s final choice yet?",choices:["No. Irene only knows the door is open","Yes. Alme lets the box go","Yes. Alme calls Piva"],correctChoice:0,explanation:"Irene does not yet know what Alme will do. That is the next chapter.",difficulty:2}]}},1023,[]);
__d(function(e,a,n,o,i,r,s){i.exports={id:"la-casa-delle-finestre-21",storyId:"la-casa-delle-finestre",number:21,title:"The director",titleIt:"La dirigente",locationIds:["ufficio-alme"],characterIds:["irene-colombo","alme"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-21",summary:"Still Friday, in Alme\u2019s office. Alme says the closure protected children and also her job. She lets one box exist as already destroyed. She tells Irene to go to Piva or not; she will not help twice.",characterIds:["irene-colombo","alme"],locationIds:["ufficio-alme"],rememberedFacts:["It is still Friday, in Alme\u2019s office","Alme says the closure protected children","Alme also protected her job and the town\u2019s story","She allows one box to survive as already shredded","This is not a full confession","She says Irene may go to Piva or not; she will not help twice"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"La porta \xe8 chiusa. Oggi \xe8 ancora venerd\xec. Fuori la macchina fa rumore.",speakerId:null,kind:"narration",lemmas:["la","porta","essere","chiudere","oggi","essere","ancora","venerdi","fuori","la","macchina","fare","rumore"]},{id:"s02",text:"Alme resta in piedi. Irene resta seduta. Tra loro il tavolo.",speakerId:null,kind:"narration",lemmas:["alme","restare","in","piedi","irene","restare","sedere","tra","loro","il","tavolo"]},{id:"s03",text:"Alme non urla. Non fa un discorso lungo. Parla a pezzi.",speakerId:null,kind:"narration",lemmas:["alme","non","urlare","non","fare","un","discorso","lungo","parlare","a","pezzo"]},{id:"s04",text:"Abbiamo chiuso la scuola perch\xe9 i bambini non potevano restare.",speakerId:"alme",kind:"dialogue",lemmas:["avere","chiudere","la","scuola","perche","i","bambino","non","potere","restare"]},{id:"s05",text:"Il muro non era sicuro. Questo \xe8 vero.",speakerId:"alme",kind:"dialogue",lemmas:["il","muro","non","essere","sicuro","questo","essere","vero"]},{id:"s06",text:"Irene ascolta. Non dice: e le crepe di Sara. Non fa l'avvocato.",speakerId:null,kind:"narration",lemmas:["irene","ascoltare","non","dire","e","le","crepa","di","sara","non","fare","avvocato"]},{id:"s07",text:"Quindi abbiamo chiuso. Quindi il paese dice: \xe8 vuota.",speakerId:"alme",kind:"dialogue",lemmas:["quindi","avere","chiudere","quindi","il","paese","dire","essere","vuoto"]},{id:"s08",text:"Per\xf2 ho protetto anche il mio posto di lavoro. E la storia del paese.",speakerId:"alme",kind:"dialogue",lemmas:["pero","avere","proteggere","anche","il","mio","posto","di","lavoro","e","la","storia","del","paese"]},{id:"s09",text:"Non \xe8 tutta la verit\xe0. \xc8 abbastanza per chiudere una porta, due anni fa.",speakerId:null,kind:"narration",lemmas:["non","essere","tutto","la","verita","essere","abbastanza","per","chiudere","una","porta","due","anno","fa"]}]},{id:"p2",order:2,sentences:[{id:"s10",text:"Irene tiene la mano in tasca, sulla chiavetta. Alme guarda la tasca, poi no.",speakerId:null,kind:"narration",lemmas:["irene","tenere","la","mano","in","tasca","sulla","chiavetta","alme","guardare","la","tasca","poi","no"]},{id:"s11",text:"Non chiede della copia. Non chiede di Sara. Chiede della scatola.",speakerId:null,kind:"narration",lemmas:["non","chiedere","della","copia","non","chiedere","di","sara","chiedere","della","scatola"]},{id:"s12",text:"Quella del seminterrato. Io so.",speakerId:"alme",kind:"dialogue",lemmas:["quello","del","seminterrato","io","sapere"]},{id:"s13",text:"Irene non mente di nuovo. Non parla. Annuisce, quasi.",speakerId:null,kind:"narration",lemmas:["irene","non","mentire","di","nuovo","non","parlare","annuire","quasi"]},{id:"s14",text:"Per i fogli, quella scatola \xe8 gi\xe0 distrutta. Oggi. Venerd\xec.",speakerId:"alme",kind:"dialogue",lemmas:["per","i","foglio","quello","scatola","essere","gia","distruggere","oggi","venerdi"]},{id:"s15",text:"Non \xe8 coraggio. Non \xe8 piet\xe0 pulita. \xc8 una cosa piccola, e vile, e utile.",speakerId:"alme",kind:"dialogue",lemmas:["non","essere","coraggio","non","essere","pieta","pulito","essere","una","cosa","piccolo","e","vile","e","utile"]},{id:"s16",text:"Irene capisce: una scatola resta. Non un processo. Non la televisione.",speakerId:null,kind:"narration",lemmas:["irene","capire","una","scatola","restare","non","un","processo","non","la","televisione"]},{id:"s17",text:"Alme si siede, alla fine. Le mani sul tavolo, ferme.",speakerId:null,kind:"narration",lemmas:["alme","si","sedere","alla","fine","le","mano","sul","tavolo","fermo"]},{id:"s18",text:"Non confesso in piazza. Non lo far\xf2.",speakerId:"alme",kind:"dialogue",lemmas:["non","confessare","in","piazza","non","lo","fare"]}]},{id:"p3",order:3,sentences:[{id:"s19",text:"Il rumore della macchina continua. Venerd\xec non si ferma per due donne.",speakerId:null,kind:"narration",lemmas:["il","rumore","della","macchina","continuare","venerdi","non","si","fermare","per","due","donna"]},{id:"s20",text:"Irene dovrebbe dire grazie, o no, o tutto. Dice poco.",speakerId:null,kind:"narration",lemmas:["irene","dovere","dire","grazie","o","no","o","tutto","dire","poco"]},{id:"s21",text:"La scatola resta gi\xf9. Io non aiuto due volte.",speakerId:"alme",kind:"dialogue",lemmas:["la","scatola","restare","giu","io","non","aiutare","due","volta"]},{id:"s22",text:"Adesso va dal maresciallo Piva, o non va. Questa \xe8 la sua scelta.",speakerId:"alme",kind:"dialogue",lemmas:["adesso","andare","dal","maresciallo","piva","o","non","andare","questo","essere","la","suo","scelta"]},{id:"s23",text:"Non \xe8 un ordine. \xc8 una porta, aperta, dopo una porta chiusa.",speakerId:null,kind:"narration",lemmas:["non","essere","un","ordine","essere","una","porta","aprire","dopo","una","porta","chiudere"]},{id:"s24",text:"Irene si alza. La chiavetta resta in tasca. Alme non la prende.",speakerId:null,kind:"narration",lemmas:["irene","si","alzare","la","chiavetta","restare","in","tasca","alme","non","la","prendere"]},{id:"s25",text:"Non \xe8 finito il mistero in una stanza. \xc8 una scatola, e una scelta, e venerd\xec che continua.",speakerId:null,kind:"narration",lemmas:["non","essere","finire","il","mistero","in","una","stanza","essere","una","scatola","e","una","scelta","e","venerdi","che","continuare"]},{id:"s26",text:"Irene esce. Alme non dice arrivederci. Dice solo, piano: o Piva, o no.",speakerId:null,kind:"narration",lemmas:["irene","uscire","alme","non","dire","arrivederci","dire","solo","piano","o","piva","o","no"]},{id:"s27",text:"Nel corridoio il rumore \xe8 lo stesso. Venerd\xec non \xe8 diventato un altro giorno dentro l'ufficio.",speakerId:null,kind:"narration",lemmas:["nel","corridoio","il","rumore","essere","lo","stesso","venerdi","non","essere","diventare","un","altro","giorno","dentro","ufficio"]},{id:"s28",text:"Irene non ha una confessione completa. Ha pezzi: bambini, posto di lavoro, una scatola gi\xe0 distrutta sulla carta.",speakerId:null,kind:"narration",lemmas:["irene","non","avere","una","confessione","completo","avere","pezzo","bambino","posto","di","lavoro","una","scatola","gia","distruggere","sulla","carta"]},{id:"s29",text:"Non \xe8 coraggio, ha detto Alme. Irene ci crede. Non la ama per questo. Non la odia come un film.",speakerId:null,kind:"narration",lemmas:["non","essere","coraggio","avere","dire","alme","irene","ci","credere","non","la","amare","per","questo","non","la","odiare","come","un","film"]},{id:"s30",text:"La chiavetta pesa. La scatola resta. Piva \xe8 una scelta, non un premio.",speakerId:null,kind:"narration",lemmas:["la","chiavetta","pesare","la","scatola","restare","piva","essere","una","scelta","non","un","premio"]},{id:"s31",text:"Scende le scale. Non torna nel seminterrato. Non deve, oggi. Alme ha detto: resta gi\xf9.",speakerId:null,kind:"narration",lemmas:["scendere","le","scala","non","tornare","nel","seminterrato","non","dovere","oggi","alme","avere","dire","restare","giu"]},{id:"s32",text:"Fuori \xe8 ancora pomeriggio. La macchina lavora. Irene cammina verso i carabinieri, o ci pensa. Poi cammina.",speakerId:null,kind:"narration",lemmas:["fuori","essere","ancora","pomeriggio","la","macchina","lavorare","irene","camminare","verso","i","carabinieri","o","ci","pensare","poi","camminare"]},{id:"s33",text:"Non \xe8 tutto spiegato. Manca Sara, manca il paese, manca che cosa far\xe0 Piva. Questo capitolo \xe8 Alme, e un no al coraggio.",speakerId:null,kind:"narration",lemmas:["non","essere","tutto","spiegare","mancare","sara","mancare","il","paese","mancare","che","cosa","fare","piva","questo","capitolo","essere","alme","e","un","no","al","coraggio"]},{id:"s34",text:"Alme ha detto dei bambini, e del posto, e della storia del paese. Tre motivi, non uno solo. Irene li tiene separati.",speakerId:null,kind:"narration",lemmas:["alme","avere","dire","dei","bambino","e","del","posto","e","della","storia","del","paese","tre","motivo","non","uno","solo","irene","li","tenere","separare"]},{id:"s35",text:"Se dice tutto a Piva, Alme non aiuta due volte. Se non dice, la scatola resta comunque, sulla carta, distrutta.",speakerId:null,kind:"narration",lemmas:["se","dire","tutto","a","piva","alme","non","aiutare","due","volta","se","non","dire","la","scatola","restare","comunque","sulla","carta","distruggere"]},{id:"s36",text:"Quindi la scelta \xe8 sua, e sporca, come la scatola. Non \xe8 un esame con una risposta sola.",speakerId:null,kind:"narration",lemmas:["quindi","la","scelta","essere","suo","e","sporco","come","la","scatola","non","essere","un","esame","con","una","risposta","solo"]},{id:"s37",text:"Irene non chiede perch\xe9 Alme ha aspettato venerd\xec. Non chiede dei registri di dieci anni fa. Non \xe8 questo il capitolo.",speakerId:null,kind:"narration",lemmas:["irene","non","chiedere","perche","alme","avere","aspettare","venerdi","non","chiedere","dei","registro","di","dieci","anno","fa","non","essere","questo","il","capitolo"]},{id:"s38",text:"Cammina. Il comune resta alle spalle, con la macchina accesa. Davanti c'\xe8 Piva, o la mansarda. Lei sceglie la strada dei carabinieri.",speakerId:null,kind:"narration",lemmas:["camminare","il","comune","restare","alle","spalle","con","la","macchina","accendere","davanti","ce","piva","o","la","mansarda","lei","scegliere","la","strada","dei","carabinieri"]},{id:"s39",text:"Non torna da Alme per un'altra frase. Una volta \xe8 abbastanza. Non \xe8 coraggio, e non lo chiede di nuovo.",speakerId:null,kind:"narration",lemmas:["non","tornare","da","alme","per","altro","frase","una","volta","essere","abbastanza","non","essere","coraggio","e","non","lo","chiedere","di","nuovo"]},{id:"s40",text:"La dirigente resta in ufficio. Irene \xe8 gi\xe0 nel pomeriggio, verso una stanza piccola, con lei formale.",speakerId:null,kind:"narration",lemmas:["la","dirigente","restare","in","ufficio","irene","essere","gia","nel","pomeriggio","verso","una","stanza","piccolo","con","lei","formale"]},{id:"s41",text:"Venerd\xec continua. La scatola, sulla carta, \xe8 distrutta. Sulla terra, gi\xf9, c'\xe8. Questo Irene lo porta a Piva, o no: lo porta.",speakerId:null,kind:"narration",lemmas:["venerdi","continuare","la","scatola","sulla","carta","essere","distruggere","sulla","terra","giu","ce","questo","irene","lo","portare","a","piva","o","no","lo","portare"]},{id:"s42",text:"Non ha capito Alme in cinque minuti. Ha capito abbastanza: bambini s\xec, posto s\xec, confessione in piazza no.",speakerId:null,kind:"narration",lemmas:["non","avere","capire","alme","in","cinque","minuto","avere","capire","abbastanza","bambino","si_yes","posto","si_yes","confessione","in","piazza","no"]},{id:"s43",text:"Due donne, un tavolo, una macchina fuori. Poi Irene sola, in strada, con una scelta che Alme non far\xe0 al posto suo.",speakerId:null,kind:"narration",lemmas:["due","donna","un","tavolo","una","macchina","fuori","poi","irene","solo","in","strada","con","una","scelta","che","alme","non","fare","al","posto","suo"]},{id:"s44",text:"Non \xe8 un monologo da cattiva. Alme ha detto poco, e ha lasciato una scatola, e ha detto di Piva. Fine della stanza.",speakerId:null,kind:"narration",lemmas:["non","essere","un","monologo","da","cattivo","alme","avere","dire","poco","e","avere","lasciare","una","scatola","e","avere","dire","di","piva","fine","della","stanza"]},{id:"s45",text:"Irene non sa se questo \xe8 piet\xe0. Sa che non \xe8 coraggio. Sa che venerd\xec non aspetta. Cammina.",speakerId:null,kind:"narration",lemmas:["irene","non","sapere","se","questo","essere","pieta","sapere","che","non","essere","coraggio","sapere","che","venerdi","non","aspettare","camminare"]},{id:"s46",text:"Non arrestano Alme in questa stanza. Non c'\xe8 uno scandalo nazionale. C'\xe8 una dirigente, e una scatola, e un no detto due volte.",speakerId:null,kind:"narration",lemmas:["non","arrestare","alme","in","questo","stanza","non","ce","uno","scandalo","nazionale","ce","una","dirigente","e","una","scatola","e","un","no","dire","due","volta"]},{id:"s47",text:"Irene esce dal comune. Venerd\xec pomeriggio. La scelta \xe8 Piva. Questo \xe8 il capitolo. Il resto non \xe8 qui.",speakerId:null,kind:"narration",lemmas:["irene","uscire","dal","comune","venerdi","pomeriggio","la","scelta","essere","piva","questo","essere","il","capitolo","il","resto","non","essere","qui"]}]}],questions:[{id:"ch21_q01",chapterId:"la-casa-delle-finestre-21",type:"direct",question:"When and where is this?",choices:["Still Friday, in Alme\u2019s office","Tuesday at the school","Saturday on the bus"],correctChoice:0,explanation:"The door is shut. Today is still Friday.",difficulty:2},{id:"ch21_q02",chapterId:"la-casa-delle-finestre-21",type:"character",question:"What does Alme say about the closure?",choices:["It protected children, and also her job and the town\u2019s story","Sara was right and Alme will confess on TV","Quinto is the lamp"],correctChoice:0,explanation:"The wall was not safe. She also protected her job.",difficulty:2},{id:"ch21_q03",chapterId:"la-casa-delle-finestre-21",type:"event",question:"What happens to the basement box?",choices:["On paper it is already destroyed; it survives unofficially","Alme burns it in front of Irene","Piva takes it at once"],correctChoice:0,explanation:"On paper, that box is already destroyed. One box remains.",difficulty:2},{id:"ch21_q04",chapterId:"la-casa-delle-finestre-21",type:"inference",question:"What choice does Alme leave Irene?",choices:["Go to Piva or not; Alme will not help twice","Arrest Alme","Sell the USB"],correctChoice:0,explanation:"Now you go to Marshal Piva, or you don\u2019t. I do not help twice.",difficulty:2}]}},1024,[]);
__d(function(e,a,i,r,n,s,o){n.exports={id:"la-casa-delle-finestre-22",storyId:"la-casa-delle-finestre",number:22,title:"Piva",titleIt:"Piva",locationIds:["caserma-piva","via-della-scuola"],characterIds:["irene-colombo","piva","sara-neri"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-22",summary:"Friday evening Irene tells Marshal Piva the facts, later than she should have. Sara is angry, then relieved. The school stays closed. The story stays local. Piva says the windows were never the crime; the paper was.",characterIds:["irene-colombo","piva","sara-neri"],locationIds:["caserma-piva","via-della-scuola"],rememberedFacts:["Irene talks to Marshal Piva","She goes later than she should have","Sara is angry, then relieved","The school stays closed; it will not be a national story","Piva says the windows were never the crime; the paper was"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Venerd\xec sera Irene va dai carabinieri. Non \xe8 marted\xec. \xc8 tardi, e lei lo sa.",speakerId:null,kind:"narration",lemmas:["venerdi","sera","irene","andare","dai","carabinieri","non","essere","martedi","essere","tardi","e","lei","lo","sapere"]},{id:"s02",text:"Il maresciallo Piva la riceve in una stanza piccola. Lei, formale.",speakerId:null,kind:"narration",lemmas:["il","maresciallo","piva","la","ricevere","in","una","stanza","piccolo","lei","formale"]},{id:"s03",text:"Si sieda. Mi dica che cosa ha visto.",speakerId:"piva",kind:"dialogue",lemmas:["si","sedere","mi","dire","che","cosa","avere","vedere"]},{id:"s04",text:"Irene non fa la detective. Dice i fatti, in ordine, come un archivio.",speakerId:null,kind:"narration",lemmas:["irene","non","fare","la","detective","dire","i","fatto","in","ordine","come","un","archivio"]},{id:"s05",text:"Ho visto una luce nella scuola chiusa. Poi un orario. Poi una pausa. Poi un foglio: non carabinieri, registri.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["avere","vedere","una","luce","nella","scuola","chiudere","poi","un","orario","poi","una","pausa","poi","un","foglio","non","carabinieri","registro"]},{id:"s06",text:"Venerd\xec il comune distrugge carte. Io ho nascosto una scatola. Poi ho fatto una copia.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["venerdi","il","comune","distruggere","carta","io","avere","nascondere","una","scatola","poi","avere","fare","una","copia"]},{id:"s07",text:"Sara Neri era la luce. Alme sa della scatola. Quinto sapeva delle crepe.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["sara","neri","essere","la","luce","alme","sapere","della","scatola","quinto","sapere","delle","crepa"]},{id:"s08",text:"Piva scrive. Non sorride. Non dice: brava. Non dice: ha risolto lei.",speakerId:null,kind:"narration",lemmas:["piva","scrivere","non","sorridere","non","dire","brava","non","dire","avere","risolvere","lei"]},{id:"s09",text:"Doveva venire prima. Il foglio diceva di non chiamare. Per\xf2 doveva venire prima.",speakerId:"piva",kind:"dialogue",lemmas:["dovere","venire","prima","il","foglio","dire","di","non","chiamare","pero","dovere","venire","prima"]},{id:"s10",text:"S\xec. Lo so. Sono in ritardo.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes","lo","sapere","essere","in","ritardo"]}]},{id:"p2",order:2,sentences:[{id:"s11",text:"Piva non apre un processo in due minuti. Dice che la scuola resta chiusa.",speakerId:null,kind:"narration",lemmas:["piva","non","aprire","un","processo","in","due","minuto","dire","che","la","scuola","restare","chiudere"]},{id:"s12",text:"Non \xe8 una storia per la televisione. \xc8 un paese. \xc8 locale.",speakerId:"piva",kind:"dialogue",lemmas:["non","essere","una","storia","per","la","televisione","essere","un","paese","essere","locale"]},{id:"s13",text:"Controlleremo le carte. Lei ha detto la verit\xe0. Questo basta, per stasera.",speakerId:"piva",kind:"dialogue",lemmas:["controllare","le","carta","lei","avere","dire","la","verita","questo","bastare","per","stasera"]},{id:"s14",text:"Irene lascia una copia dei fatti, non vende niente. Esce. Non \xe8 una festa.",speakerId:null,kind:"narration",lemmas:["irene","lasciare","una","copia","dei","fatto","non","vendere","niente","uscire","non","essere","una","festa"]},{id:"s15",text:"Vicino alla scuola, di sera, c'\xe8 Sara. La borsa c'\xe8. La rabbia c'\xe8.",speakerId:null,kind:"narration",lemmas:["vicino","alla","scuola","di","sera","ce","sara","la","borsa","ce","la","rabbia","ce"]},{id:"s16",text:"Ha chiamato i carabinieri.",speakerId:"sara-neri",kind:"dialogue",lemmas:["avere","chiamare","i","carabinieri"]},{id:"s17",text:"S\xec. Tardi. Dopo Alme. Dopo la macchina.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["si_yes","tardi","dopo","alme","dopo","la","macchina"]},{id:"s18",text:"Sara parla in fretta, con rabbia. Poi si ferma. Respira.",speakerId:null,kind:"narration",lemmas:["sara","parlare","in","fretta","con","rabbia","poi","si","fermare","respirare"]},{id:"s19",text:"I registri. Una scatola. Non tutto. Per\xf2 non tutto \xe8 morto.",speakerId:"sara-neri",kind:"dialogue",lemmas:["i","registro","una","scatola","non","tutto","pero","non","tutto","essere","morto"]},{id:"s20",text:"Irene non chiede un grazie. Sara non lo d\xe0 subito. Poi, piano: va bene. Quasi.",speakerId:null,kind:"narration",lemmas:["irene","non","chiedere","un","grazie","sara","non","lo","dare","subito","poi","piano","andare","bene","quasi"]},{id:"s21",text:"La scuola resta chiusa. Nessuno entra a festeggiare. Due donne in strada, venerd\xec sera.",speakerId:null,kind:"narration",lemmas:["la","scuola","restare","chiudere","nessuno","entrare","a","festeggiare","due","donna","in","strada","venerdi","sera"]}]},{id:"p3",order:3,sentences:[{id:"s22",text:"Piva, prima, ha detto una cosa, alla porta.",speakerId:null,kind:"narration",lemmas:["piva","prima","avere","dire","una","cosa","alla","porta"]},{id:"s23",text:"Le finestre non sono mai state il reato. La carta s\xec.",speakerId:"piva",kind:"dialogue",lemmas:["le","finestra","non","essere","mai","stato","il","reato","la","carta","si_yes"]},{id:"s24",text:"Irene tiene quella frase. Non la mette sul quaderno come un trionfo.",speakerId:null,kind:"narration",lemmas:["irene","tenere","quello","frase","non","la","mettere","sul","quaderno","come","un","trionfo"]},{id:"s25",text:"Sara se ne va verso la palestra, senza lampada. Irene va verso casa.",speakerId:null,kind:"narration",lemmas:["sara","se","ne","andare","verso","la","palestra","senza","lampada","irene","andare","verso","casa"]},{id:"s26",text:"Non \xe8 la fine della scuola. \xc8 la fine di questa sera. Locale. Tardi. Vero abbastanza.",speakerId:null,kind:"narration",lemmas:["non","essere","la","fine","della","scuola","essere","la","fine","di","questo","sera","locale","tardi","vero","abbastanza"]},{id:"s27",text:"Piva non ha detto: lei \xe8 pi\xf9 intelligente di noi. Ha scritto. Ha detto: locale. Ha detto: tardi.",speakerId:null,kind:"narration",lemmas:["piva","non","avere","dire","lei","essere","piu","intelligente","di","noi","avere","scrivere","avere","dire","locale","avere","dire","tardi"]},{id:"s28",text:"Irene non porta una vittoria a casa. Porta una denuncia semplice: ho detto la verit\xe0, tardi.",speakerId:null,kind:"narration",lemmas:["irene","non","portare","una","vittoria","a","casa","portare","una","denuncia","semplice","avere","dire","la","verita","tardi"]},{id:"s29",text:"Sara \xe8 andata via senza lampada. Questo \xe8 un fatto nuovo, piccolo. Non \xe8 un lieto fine.",speakerId:null,kind:"narration",lemmas:["sara","essere","andare","via","senza","lampada","questo","essere","un","fatto","nuovo","piccolo","non","essere","un","lieto","fine"]},{id:"s30",text:"La scuola resta chiusa. I bambini non tornano luned\xec. Irene lo sapeva. Piva lo ha detto senza enfasi.",speakerId:null,kind:"narration",lemmas:["la","scuola","restare","chiudere","i","bambino","non","tornare","lunedi","irene","lo","sapere","piva","lo","avere","dire","senza","enfasi"]},{id:"s31",text:"Venerd\xec \xe8 lungo. Mattina la macchina, pomeriggio Alme, sera Piva, poi Sara. Un giorno, tre stanze, niente trionfo.",speakerId:null,kind:"narration",lemmas:["venerdi","essere","lungo","mattina","la","macchina","pomeriggio","alme","sera","piva","poi","sara","un","giorno","tre","stanza","niente","trionfo"]},{id:"s32",text:"Irene sale verso la mansarda. Non corre. Non chiama i giornali. Il paese resta il paese.",speakerId:null,kind:"narration",lemmas:["irene","salire","verso","la","mansarda","non","correre","non","chiamare","i","giornale","il","paese","restare","il","paese"]},{id:"s33",text:"Ha detto a Piva i fatti, non le teorie. Luce, orario, pausa, foglio, scatola, copia, Sara, Alme, Quinto. Poi ha taciuto.",speakerId:null,kind:"narration",lemmas:["avere","dire","a","piva","i","fatto","non","le","teoria","luce","orario","pausa","foglio","scatola","copia","sara","alme","quinto","poi","avere","tacere"]},{id:"s34",text:"Piva controller\xe0. Lei non \xe8 la legge. Questo pesa, e anche no.",speakerId:null,kind:"narration",lemmas:["piva","controllare","lei","non","essere","la","legge","questo","pesare","e","anche","no"]},{id:"s35",text:"Sara aveva rabbia perch\xe9 il foglio diceva di no. Poi ha visto che una scatola non \xe8 morta. Quasi va bene.",speakerId:null,kind:"narration",lemmas:["sara","avere","rabbia","perche","il","foglio","dire","di","no","poi","avere","vedere","che","una","scatola","non","essere","morto","quasi","andare","bene"]},{id:"s36",text:"Nessuno spara. Nessuno vince in piazza. Venerd\xec sera finisce cos\xec: locale, tardi, con le finestre ancora chiuse.",speakerId:null,kind:"narration",lemmas:["nessuno","sparare","nessuno","vincere","in","piazza","venerdi","sera","finire","cosi","locale","tardi","con","le","finestra","ancora","chiudere"]},{id:"s37",text:"Nella stanza dei carabinieri c'era un tavolo, una sedia, un uomo che scrive. Basta cos\xec. Non un tribunale.",speakerId:null,kind:"narration",lemmas:["nella","stanza","dei","carabinieri","ce","un","tavolo","una","sedia","un","uomo","che","scrivere","basta","cosi","non","un","tribunale"]},{id:"s38",text:"Irene ha usato lei, come si deve. Piva ha usato lei. Nessuno \xe8 diventato amico in venti minuti.",speakerId:null,kind:"narration",lemmas:["irene","avere","usare","lei","come","si","dovere","piva","avere","usare","lei","nessuno","essere","diventare","amico","in","venti","minuto"]},{id:"s39",text:"Dopo Sara, la strada \xe8 vuota di festa. C'\xe8 solo il buio che arriva, e una mansarda che aspetta.",speakerId:null,kind:"narration",lemmas:["dopo","sara","la","strada","essere","vuoto","di","festa","ce","solo","il","buio","che","arrivare","e","una","mansarda","che","aspettare"]},{id:"s40",text:"Ha detto la verit\xe0 tardi. Piva l'ha sentita. Sara l'ha sentita. Il paese, no, non tutto, non stasera.",speakerId:null,kind:"narration",lemmas:["avere","dire","la","verita","tardi","piva","avere","sentire","sara","avere","sentire","il","paese","no","non","tutto","non","stasera"]},{id:"s41",text:"Le finestre non erano il reato: Irene ripete la frase di Piva, senza farne un slogan.",speakerId:null,kind:"narration",lemmas:["le","finestra","non","essere","il","reato","irene","ripetere","la","frase","di","piva","senza","fare","un","slogan"]},{id:"s42",text:"Non c'\xe8 un verdetto stasera. C'\xe8 una denuncia, locale, tardi. C'\xe8 Sara quasi sollevata. C'\xe8 la scuola chiusa, come ieri.",speakerId:null,kind:"narration",lemmas:["non","ce","un","verdetto","stasera","ce","una","denuncia","locale","tardi","ce","sara","quasi","sollevare","ce","la","scuola","chiudere","come","ieri"]},{id:"s43",text:"Irene non festeggia. Sale le scale di casa. Venerd\xec \xe8 stato lungo. Questo \xe8 abbastanza per un capitolo di legge, non di eroi.",speakerId:null,kind:"narration",lemmas:["irene","non","festeggiare","salire","le","scala","di","casa","venerdi","essere","stato","lungo","questo","essere","abbastanza","per","un","capitolo","di","legge","non","di","eroe"]},{id:"s44",text:"Piva resta alla caserma. Sara resta nel paese, forse. Irene resta con il ritardo, e con la carta, e con le finestre che non erano il reato.",speakerId:null,kind:"narration",lemmas:["piva","restare","alla","caserma","sara","restare","nel","paese","forse","irene","restare","con","il","ritardo","e","con","la","carta","e","con","le","finestra","che","non","essere","il","reato"]},{id:"s45",text:"Ha parlato tardi. Lo sa. Piva lo sa. Sara lo sa. Non c'\xe8 uno sparo. C'\xe8 una stanza, e dei fatti, e via.",speakerId:null,kind:"narration",lemmas:["avere","parlare","tardi","lo","sapere","piva","lo","sapere","sara","lo","sapere","non","ce","uno","sparo","ce","una","stanza","e","dei","fatto","e","via"]},{id:"s46",text:"Locale. Tardi. La carta, non le finestre. Irene tiene tre cose, e va a letto senza festa.",speakerId:null,kind:"narration",lemmas:["locale","tardi","la","carta","non","le","finestra","irene","tenere","tre","cosa","e","andare","a","letto","senza","festa"]},{id:"s47",text:"Non \xe8 pi\xf9 intelligente della legge. \xc8 in ritardo, e ha parlato. Questo \xe8 il suo posto, stasera.",speakerId:null,kind:"narration",lemmas:["non","essere","piu","intelligente","della","legge","essere","in","ritardo","e","avere","parlare","questo","essere","il","suo","posto","stasera"]}]}],questions:[{id:"ch22_q01",chapterId:"la-casa-delle-finestre-22",type:"event",question:"What does Irene do?",choices:["She talks to Marshal Piva, later than she should have","She arrests Alme","She opens the school"],correctChoice:0,explanation:"Friday evening she goes to the Carabinieri. She is late.",difficulty:2},{id:"ch22_q02",chapterId:"la-casa-delle-finestre-22",type:"character",question:"How does Sara react?",choices:["She is angry, then almost relieved","She celebrates on television","She takes Quinto\u2019s keys"],correctChoice:0,explanation:"Anger first. Then: all right. Almost. The school stays closed.",difficulty:2},{id:"ch22_q03",chapterId:"la-casa-delle-finestre-22",type:"direct",question:"Will this be a national TV story?",choices:["No. It stays local. The school stays closed","Yes. Piva calls the news","Yes. Irene sells the USB"],correctChoice:0,explanation:"It is not a story for television. It is a town. It is local.",difficulty:2},{id:"ch22_q04",chapterId:"la-casa-delle-finestre-22",type:"inference",question:"What does Piva say about the windows?",choices:["They were never the crime; the paper was","The lamp was a ghost","Irene is smarter than the police"],correctChoice:0,explanation:"The windows were never the crime. The paper was.",difficulty:2}]}},1025,[]);
__d(function(e,a,r,n,o,i,s){o.exports={id:"la-casa-delle-finestre-23",storyId:"la-casa-delle-finestre",number:23,title:"Without light",titleIt:"Senza luce",locationIds:["mansarda-irene","scuola-media"],characterIds:["irene-colombo"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-23",summary:"At night the school grid is dark. Irene looks anyway. She opens the notebook, does not add a number, and closes it. She cannot sleep. The facing window stays dark. She is not sure she prefers this.",characterIds:["irene-colombo"],locationIds:["mansarda-irene"],rememberedFacts:["There is no night lamp now","Irene still looks","She closes the notebook without adding a number","She is not sure she prefers the dark"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Di sera Irene \xe8 in mansarda. Ha spento la luce della stanza.",speakerId:null,kind:"narration",lemmas:["di","sera","irene","essere","in","mansarda","avere","spegnere","la","luce","della","stanza"]},{id:"s02",text:"Guarda la scuola. La griglia \xe8 scura. Tutte le finestre. Anche la tre, di fronte.",speakerId:null,kind:"narration",lemmas:["guardare","la","scuola","la","griglia","essere","scuro","tutto","le","finestra","anche","la","tre","di","fronte"]},{id:"s03",text:"Non c'\xe8 una lampada. Non c'\xe8 una pausa. Non c'\xe8 un orario.",speakerId:null,kind:"narration",lemmas:["non","ce","una","lampada","non","ce","una","pausa","non","ce","un","orario"]},{id:"s04",text:"Sembra vuota. Lo sembrava anche prima. Adesso lo \xe8, di notte, in un altro modo.",speakerId:null,kind:"narration",lemmas:["sembrare","vuoto","lo","sembrare","anche","prima","adesso","lo","essere","di","notte","in","un","altro","modo"]},{id:"s05",text:"Irene aspetta le nove, per abitudine. Poi le nove e dieci. Niente.",speakerId:null,kind:"narration",lemmas:["irene","aspettare","le","nove","per","abitudine","poi","le","nove","e","dieci","niente"]},{id:"s06",text:"Ancora guarda. Non perch\xe9 \xe8 una detective. Perch\xe9 i suoi occhi hanno imparato quella riga.",speakerId:null,kind:"narration",lemmas:["ancora","guardare","non","perche","essere","una","detective","perche","i","suo","occhio","avere","imparare","quello","riga"]}]},{id:"p2",order:2,sentences:[{id:"s07",text:"Apre il quaderno sul tavolo. Le pagine coincidono ancora, sotto. I numeri ci sono.",speakerId:null,kind:"narration",lemmas:["aprire","il","quaderno","sul","tavolo","le","pagina","coincidere","ancora","sotto","i","numero","ci","essere"]},{id:"s08",text:"Prende la penna. Non scrive un numero nuovo. Non scrive stasera niente, come un fatto da mappa.",speakerId:null,kind:"narration",lemmas:["prendere","la","penna","non","scrivere","un","numero","nuovo","non","scrivere","stasera","niente","come","un","fatto","da","mappa"]},{id:"s09",text:"Chiude il quaderno. Lo lascia chiuso. L'abitudine si ferma qui, per scelta.",speakerId:null,kind:"narration",lemmas:["chiudere","il","quaderno","lo","lasciare","chiudere","abitudine","si","fermare","qui","per","scelta"]},{id:"s10",text:"Ha contato abbastanza. Ha capito abbastanza. Non tutto. Abbastanza per chiudere.",speakerId:null,kind:"narration",lemmas:["avere","contare","abbastanza","avere","capire","abbastanza","non","tutto","abbastanza","per","chiudere"]},{id:"s11",text:"Si mette a letto. Non dorme. Il buio della scuola entra nella stanza, senza luce.",speakerId:null,kind:"narration",lemmas:["si","mettere","a","letto","non","dormire","il","buio","della","scuola","entrare","nella","stanza","senza","luce"]},{id:"s12",text:"Ricorda le tre lente. Ricorda le due. Ricorda Sara di giorno, dietro la palestra.",speakerId:null,kind:"narration",lemmas:["ricordare","le","tre","lento","ricordare","le","due","ricordare","sara","di","giorno","dietro","la","palestra"]},{id:"s13",text:"Ricorda Loredana che piange sui numeri. Ricorda Quinto e le piante morte.",speakerId:null,kind:"narration",lemmas:["ricordare","loredana","che","piangere","sui","numero","ricordare","quinto","e","le","pianta","morto"]},{id:"s14",text:"Nessun fantasma torna. Nessuna luce nuova. Solo la griglia, nera, come il primo giorno, e diversa.",speakerId:null,kind:"narration",lemmas:["nessuno","fantasma","tornare","nessuno","luce","nuovo","solo","la","griglia","nero","come","il","primo","giorno","e","diverso"]}]},{id:"p3",order:3,sentences:[{id:"s15",text:"La finestra di fronte resta scura.",speakerId:null,kind:"narration",lemmas:["la","finestra","di","fronte","restare","scuro"]},{id:"s16",text:"Irene non \xe8 sicura di preferire questo.",speakerId:null,kind:"narration",lemmas:["irene","non","essere","sicuro","di","preferire","questo"]},{id:"s17",text:"Prima aveva paura della luce. Adesso ha un buio onesto, e non dorme lo stesso.",speakerId:null,kind:"narration",lemmas:["prima","avere","paura","della","luce","adesso","avere","un","buio","onesto","e","non","dormire","lo","stesso"]},{id:"s18",text:"Non apre di nuovo il quaderno. Non accende la lampada verso la scuola.",speakerId:null,kind:"narration",lemmas:["non","aprire","di","nuovo","il","quaderno","non","accendere","la","lampada","verso","la","scuola"]},{id:"s19",text:"Ascolta le scale. Loredana non scende. Nessuno chiama. Venerd\xec \xe8 ancora oggi, o quasi.",speakerId:null,kind:"narration",lemmas:["ascoltare","le","scala","loredana","non","scendere","nessuno","chiamare","venerdi","essere","ancora","oggi","o","quasi"]},{id:"s20",text:"Resta a guardare un poco. Poi si gira verso il muro. Gli occhi restano aperti.",speakerId:null,kind:"narration",lemmas:["restare","a","guardare","un","poco","poi","si","girare","verso","il","muro","gli","occhio","restare","aprire"]},{id:"s21",text:"Senza luce. Con il quaderno chiuso. Con la scuola di fronte, vuota di lampada, non vuota di memoria.",speakerId:null,kind:"narration",lemmas:["senza","luce","con","il","quaderno","chiudere","con","la","scuola","di","fronte","vuoto","di","lampada","non","vuoto","di","memoria"]},{id:"s22",text:"Il primo giorno la luce si muoveva. Stasera no. L'immagine si \xe8 girata, e lei l'ha lasciata girare.",speakerId:null,kind:"narration",lemmas:["il","primo","giorno","la","luce","si","muovere","stasera","no","immagine","si","essere","girare","e","lei","avere","lasciare","girare"]},{id:"s23",text:"Apre gli occhi nel buio della mansarda. Conta, senza voce, le finestre che non accende nessuno.",speakerId:null,kind:"narration",lemmas:["aprire","gli","occhio","nel","buio","della","mansarda","contare","senza","voce","le","finestra","che","non","accendere","nessuno"]},{id:"s24",text:"Poi smette. Non \xe8 pi\xf9 il suo lavoro, quella riga. \xc8 una casa di fronte, di notte.",speakerId:null,kind:"narration",lemmas:["poi","smettere","non","essere","piu","il","suo","lavoro","quello","riga","essere","una","casa","di","fronte","di","notte"]},{id:"s25",text:"Non vuole un nuovo mistero. Non arriva. Il silenzio \xe8 solo silenzio, e basta.",speakerId:null,kind:"narration",lemmas:["non","volere","un","nuovo","mistero","non","arrivare","il","silenzio","essere","solo","silenzio","e","basta"]},{id:"s26",text:"Si gira ancora. La finestra tre resta scura. Lei non preferisce, non ancora. Resta in mezzo al sonno.",speakerId:null,kind:"narration",lemmas:["si","girare","ancora","la","finestra","tre","restare","scuro","lei","non","preferire","non","ancora","restare","in","mezzo","al","sonno"]},{id:"s27",text:"Il quaderno \xe8 sul tavolo, chiuso. Domani forse parte. Stasera resta, senza luce, di proposito.",speakerId:null,kind:"narration",lemmas:["il","quaderno","essere","sul","tavolo","chiudere","domani","forse","partire","stasera","restare","senza","luce","di","proposito"]},{id:"s28",text:"Ha aperto il quaderno una volta. Ha visto i numeri vecchi. Non ne ha aggiunti. Ha chiuso. Questo \xe8 il gesto.",speakerId:null,kind:"narration",lemmas:["avere","aprire","il","quaderno","una","volta","avere","vedere","i","numero","vecchio","non","ne","avere","aggiungere","avere","chiudere","questo","essere","il","gesto"]},{id:"s29",text:"Non dorme perch\xe9 il corpo ricorda le nove. Non perch\xe9 un fantasma bussa. Il cuore va, poi no, poi di nuovo.",speakerId:null,kind:"narration",lemmas:["non","dormire","perche","il","corpo","ricordare","le","nove","non","perche","un","fantasma","bussare","il","cuore","andare","poi","no","poi","di","nuovo"]},{id:"s30",text:"Di fronte, buio. Lei non \xe8 sicura. Preferire il buio sarebbe facile, e non \xe8 facile.",speakerId:null,kind:"narration",lemmas:["di","fronte","buio","lei","non","essere","sicuro","preferire","il","buio","essere","facile","e","non","essere","facile"]},{id:"s31",text:"Resta cos\xec fino a tardi. Poi, forse, dorme un poco, senza mappa.",speakerId:null,kind:"narration",lemmas:["restare","cosi","fino","a","tardi","poi","forse","dormire","un","poco","senza","mappa"]},{id:"s32",text:"Ha guardato la griglia come il primo giorno. Stavolta non ha contato per scrivere. Ha contato per smettere.",speakerId:null,kind:"narration",lemmas:["avere","guardare","la","griglia","come","il","primo","giorno","stavolta","non","avere","contare","per","scrivere","avere","contare","per","smettere"]},{id:"s33",text:"La finestra di fronte \xe8 scura. Lei non sa se \xe8 meglio. Sa che il quaderno \xe8 chiuso. Questo basta, per il gesto.",speakerId:null,kind:"narration",lemmas:["la","finestra","di","fronte","essere","scuro","lei","non","sapere","se","essere","meglio","sapere","che","il","quaderno","essere","chiudere","questo","bastare","per","il","gesto"]},{id:"s34",text:"Nessun mostro nuovo. Nessuna luce che torna per un seguito. Solo sonno che non viene, e una scuola senza lampada.",speakerId:null,kind:"narration",lemmas:["nessuno","mostro","nuovo","nessuno","luce","che","tornare","per","un","seguito","solo","sonno","che","non","venire","e","una","scuola","senza","lampada"]},{id:"s35",text:"Senza luce: il titolo \xe8 vero. Lei guarda lo stesso. Poi chiude gli occhi, e la griglia resta fuori.",speakerId:null,kind:"narration",lemmas:["senza","luce","il","titolo","essere","vero","lei","guardare","lo","stesso","poi","chiudere","gli","occhio","e","la","griglia","restare","fuori"]},{id:"s36",text:"Il quaderno non riceve una riga nuova. Questa \xe8 la decisione della notte, piccola e chiara.",speakerId:null,kind:"narration",lemmas:["il","quaderno","non","ricevere","una","riga","nuovo","questo","essere","la","decisione","della","notte","piccolo","e","chiaro"]},{id:"s37",text:"Ha paura del buio onesto, un poco. Ha paura anche di riaprire i numeri. Non riapre. Questo \xe8 il costo, e il taglio.",speakerId:null,kind:"narration",lemmas:["avere","paura","del","buio","onesto","un","poco","avere","paura","anche","di","riaprire","i","numero","non","riaprire","questo","essere","il","costo","e","il","taglio"]},{id:"s38",text:"Sera senza luce. Mansarda. Scuola di fronte. Quaderno chiuso. Sonno che manca. Lei non \xe8 sicura di preferire. Fine della notte, quasi.",speakerId:null,kind:"narration",lemmas:["sera","senza","luce","mansarda","scuola","di","fronte","quaderno","chiudere","sonno","che","mancare","lei","non","essere","sicuro","di","preferire","fine","della","notte","quasi"]},{id:"s39",text:"Ha smesso di numerare. Questo cambia lei, pi\xf9 della griglia. La griglia \xe8 uguale. Lei no.",speakerId:null,kind:"narration",lemmas:["avere","smettere","di","numerare","questo","cambiare","lei","piu","della","griglia","la","griglia","essere","uguale","lei","no"]},{id:"s40",text:"Non aggiunge un numero. Non riapre. Non preferisce ancora. Guarda il buio di fronte, e resta. Questo \xe8 il capitolo, senza luce nuova.",speakerId:null,kind:"narration",lemmas:["non","aggiungere","un","numero","non","riaprire","non","preferire","ancora","guardare","il","buio","di","fronte","e","restare","questo","essere","il","capitolo","senza","luce","nuovo"]},{id:"s41",text:"Chiude gli occhi. La tre \xe8 scura. Lei non conta. Questo \xe8 abbastanza. Resta, senza luce nuova, e lei non \xe8 sicura.",speakerId:null,kind:"narration",lemmas:["chiudere","gli","occhio","la","tre","essere","scuro","lei","non","contare","questo","essere","abbastanza","restare","senza","luce","nuovo","e","lei","non","essere","sicuro"]}]}],questions:[{id:"ch23_q01",chapterId:"la-casa-delle-finestre-23",type:"direct",question:"What does Irene see at the school at night?",choices:["No lamp. The grid is dark","The three slow flashes again","A ghost"],correctChoice:0,explanation:"The grid is dark. There is no lamp.",difficulty:2},{id:"ch23_q02",chapterId:"la-casa-delle-finestre-23",type:"event",question:"What does she do with the notebook?",choices:["She opens it, does not add a number, and closes it","She writes a new grid","She burns it"],correctChoice:0,explanation:"She takes the pen. She does not write a new number. She closes it.",difficulty:2},{id:"ch23_q03",chapterId:"la-casa-delle-finestre-23",type:"inference",question:"Does she sleep well?",choices:["No. She is not sure she prefers the dark","Yes, at once","She sleeps at Loredana\u2019s"],correctChoice:0,explanation:"She does not sleep. The facing window stays dark. She is not sure she prefers this.",difficulty:2}]}},1026,[]);
__d(function(e,a,n,o,r,i,s){r.exports={id:"la-casa-delle-finestre-24",storyId:"la-casa-delle-finestre",number:24,title:"The archive",titleIt:"L'archivio",locationIds:["ufficio-alme","mansarda-irene","via-della-scuola"],characterIds:["irene-colombo","alme","loredana"],difficultyLevel:2,events:[{id:"ev-la-casa-delle-finestre-24",summary:"The contract is not renewed. Irene leaves San Quirico. She does not sell the story. In daylight she looks at the grid once more: a building, one ordinary dark window.",characterIds:["irene-colombo","alme"],locationIds:["ufficio-alme","via-della-scuola"],rememberedFacts:["The contract is not renewed","Irene leaves town","She does not sell the story","She still glances at the windows"]}],paragraphs:[{id:"p1",order:1,sentences:[{id:"s01",text:"Dopo qualche giorno Alme la chiama in ufficio. Non \xe8 venerd\xec. \xc8 un giorno normale, di lavoro.",speakerId:null,kind:"narration",lemmas:["dopo","qualche","giorno","alme","la","chiamare","in","ufficio","non","essere","venerdi","essere","un","giorno","normale","di","lavoro"]},{id:"s02",text:"Il contratto \xe8 corto. Non lo rinnoviamo.",speakerId:"alme",kind:"dialogue",lemmas:["il","contratto","essere","corto","non","lo","rinnovare"]},{id:"s03",text:"Irene lo sapeva, quasi. Non \xe8 un premio. Non \xe8 un arresto. \xc8 un no, amministrativo.",speakerId:null,kind:"narration",lemmas:["irene","lo","sapere","quasi","non","essere","un","premio","non","essere","un","arresto","essere","un","no","amministrativo"]},{id:"s04",text:"Alme non sorride come all'inizio. Dice: ha fatto il lavoro. Poi basta.",speakerId:null,kind:"narration",lemmas:["alme","non","sorridere","come","inizio","dire","avere","fare","il","lavoro","poi","basta"]},{id:"s05",text:"Grazie, dice Irene. Non \xe8 mio, questo paese. Non vendo la storia.",speakerId:"irene-colombo",kind:"dialogue",lemmas:["grazie","dire","irene","non","essere","mio","questo","paese","non","vendere","la","storia"]},{id:"s06",text:"Alme annuisce. Non aiuta due volte. Non offre un altro posto.",speakerId:null,kind:"narration",lemmas:["alme","annuire","non","aiutare","due","volta","non","offrire","un","altro","posto"]},{id:"s07",text:"Irene lascia le chiavi del seminterrato, se c'erano. Lascia lo scanner. Lascia le scatole.",speakerId:null,kind:"narration",lemmas:["irene","lasciare","le","chiave","del","seminterrato","se","ce","lasciare","lo","scanner","lasciare","le","scatola"]},{id:"s08",text:"L'archivio resta al comune. Lei no.",speakerId:null,kind:"narration",lemmas:["archivio","restare","al","comune","lei","no"]}]},{id:"p2",order:2,sentences:[{id:"s09",text:"In mansarda mette i vestiti in una borsa. Il quaderno resta, chiuso, in fondo.",speakerId:null,kind:"narration",lemmas:["in","mansarda","mettere","i","vestito","in","una","borsa","il","quaderno","restare","chiudere","in","fondo"]},{id:"s10",text:"Non \xe8 un romanzo da vendere. \xc8 un quaderno di lavoro. Non \xe8 suo da vendere.",speakerId:null,kind:"narration",lemmas:["non","essere","un","romanzo","da","vendere","essere","un","quaderno","di","lavoro","non","essere","suo","da","vendere"]},{id:"s11",text:"Loredana \xe8 in cucina. Offre un caff\xe8. Non parla della figlia. Non parla delle finestre.",speakerId:null,kind:"narration",lemmas:["loredana","essere","in","cucina","offrire","un","caffe","non","parlare","della","figlia","non","parlare","delle","finestra"]},{id:"s12",text:"Buon viaggio, dice. Irene dice: mi dispiace, di nuovo, per i numeri.",speakerId:null,kind:"narration",lemmas:["buon","viaggio","dire","irene","dire","mi","dispiacere","di","nuovo","per","i","numero"]},{id:"s13",text:"Loredana scuote la testa. Va. La scuola \xe8 vuota, dice, per abitudine, e Irene non corregge.",speakerId:null,kind:"narration",lemmas:["loredana","scuotere","la","testa","andare","la","scuola","essere","vuoto","dire","per","abitudine","e","irene","non","correggere"]},{id:"s14",text:"Vuota: una parola che ha cambiato senso, e che il paese tiene uguale.",speakerId:null,kind:"narration",lemmas:["vuoto","una","parola","che","avere","cambiare","senso","e","che","il","paese","tenere","uguale"]}]},{id:"p3",order:3,sentences:[{id:"s15",text:"Irene scende in strada, di giorno, con la borsa. C'\xe8 un autobus, vicino alla piazza.",speakerId:null,kind:"narration",lemmas:["irene","scendere","in","strada","di","giorno","con","la","borsa","ce","un","autobus","vicino","alla","piazza"]},{id:"s16",text:"Prima guarda la scuola, un momento. La griglia \xe8 solo un edificio. Finestre, muro, cancello.",speakerId:null,kind:"narration",lemmas:["prima","guardare","la","scuola","un","momento","la","griglia","essere","solo","un","edificio","finestra","muro","cancello"]},{id:"s17",text:"Una finestra \xe8 scura, ordinaria. Non una lampada. Non un segnale. Una finestra.",speakerId:null,kind:"narration",lemmas:["una","finestra","essere","scuro","ordinario","non","una","lampada","non","un","segnale","una","finestra"]},{id:"s18",text:"Guarda in alto, come chi ha saputo. Poi guarda via. Parte.",speakerId:null,kind:"narration",lemmas:["guardare","in","alto","come","chi","avere","sapere","poi","guardare","via","partire"]},{id:"s19",text:"Non resta. Non \xe8 eroina di San Quirico. \xc8 un'archivista con un contratto finito.",speakerId:null,kind:"narration",lemmas:["non","restare","non","essere","eroina","di","san","quirico","essere","archivista","con","un","contratto","finire"]},{id:"s20",text:"L'autobus parte. La scuola resta. Sembra vuota. Qualcuno c'\xe8 stato. Lei no, pi\xf9.",speakerId:null,kind:"narration",lemmas:["autobus","partire","la","scuola","restare","sembrare","vuoto","qualcuno","ce","essere","lei","no","piu"]},{id:"s21",text:"Non c'\xe8 un lavoro nuovo come premio. Non c'\xe8 Alme in manette alla fermata.",speakerId:null,kind:"narration",lemmas:["non","ce","un","lavoro","nuovo","come","premio","non","ce","alme","in","manette","alla","fermata"]},{id:"s22",text:"La luce non torna nella griglia mentre l'autobus gira. Irene non la cerca.",speakerId:null,kind:"narration",lemmas:["la","luce","non","tornare","nella","griglia","mentre","autobus","girare","irene","non","la","cercare"]},{id:"s23",text:"Guarda un attimo il paese, poi la strada. Parte per davvero. L'archivio non \xe8 suo.",speakerId:null,kind:"narration",lemmas:["guardare","un","attimo","il","paese","poi","la","strada","partire","per","davvero","archivio","non","essere","suo"]},{id:"s24",text:"San Quirico resta con le sue finestre. Lei resta con un quaderno chiuso, in fondo a una borsa.",speakerId:null,kind:"narration",lemmas:["san","quirico","restare","con","le","suo","finestra","lei","restare","con","un","quaderno","chiudere","in","fondo","a","una","borsa"]},{id:"s25",text:"Non \xe8 un lieto fine da film. \xc8 un contratto finito, e uno sguardo in alto, e poi via.",speakerId:null,kind:"narration",lemmas:["non","essere","un","lieto","fine","da","film","essere","un","contratto","finire","e","uno","sguardo","in","alto","e","poi","via"]},{id:"s26",text:"Al comune ha lasciato l'archivio. In mansarda ha lasciato la stanza vuota, di lei, non della scuola.",speakerId:null,kind:"narration",lemmas:["al","comune","avere","lasciare","archivio","in","mansarda","avere","lasciare","la","stanza","vuoto","di","lei","non","della","scuola"]},{id:"s27",text:"Loredana ha detto vuota per abitudine. Irene \xe8 partita senza correggere la parola. Non era il momento di una lezione.",speakerId:null,kind:"narration",lemmas:["loredana","avere","dire","vuoto","per","abitudine","irene","essere","partire","senza","correggere","la","parola","non","essere","il","momento","di","una","lezione"]},{id:"s28",text:"Sull'autobus non apre il quaderno. Guarda fuori. Una finestra scura, ordinaria, e basta.",speakerId:null,kind:"narration",lemmas:["autobus","non","aprire","il","quaderno","guardare","fuori","una","finestra","scuro","ordinario","e","basta"]},{id:"s29",text:"Parte. Resta chi deve restare. Lei no. Questo \xe8 l'archivio che le resta: uno sguardo, e un no alla vendita.",speakerId:null,kind:"narration",lemmas:["partire","restare","chi","dovere","restare","lei","no","questo","essere","archivio","che","le","restare","uno","sguardo","e","un","no","alla","vendita"]},{id:"s30",text:"Il contratto non rinnovato non \xe8 una punizione da film. \xc8 un no del comune, dopo un lavoro corto.",speakerId:null,kind:"narration",lemmas:["il","contratto","non","rinnovare","non","essere","una","punizione","da","film","essere","un","no","del","comune","dopo","un","lavoro","corto"]},{id:"s31",text:"Irene non chiede di restare. Non \xe8 suo. Guarda le finestre come chi ha saputo, e poi sale sull'autobus.",speakerId:null,kind:"narration",lemmas:["irene","non","chiedere","di","restare","non","essere","suo","guardare","le","finestra","come","chi","avere","sapere","e","poi","salire","autobus"]},{id:"s32",text:"Fine. Una finestra scura, ordinaria. La scuola sembra vuota. Lei parte. Basta.",speakerId:null,kind:"narration",lemmas:["fine","una","finestra","scuro","ordinario","la","scuola","sembrare","vuoto","lei","partire","basta"]},{id:"s33",text:"Non resta per diventare la donna delle finestre. Non \xe8 il suo archivio. \xc8 un paese, e un autobus, e via.",speakerId:null,kind:"narration",lemmas:["non","restare","per","diventare","la","donna","delle","finestra","non","essere","il","suo","archivio","essere","un","paese","e","un","autobus","e","via"]},{id:"s34",text:"Guarda in alto un'ultima volta, di giorno. Poi non guarda pi\xf9. Parte.",speakerId:null,kind:"narration",lemmas:["guardare","in","alto","ultimo","volta","di","giorno","poi","non","guardare","piu","partire"]},{id:"s35",text:"L'archivio del comune resta l\xe0, con Alme, con le scatole, con una macchina ferma, ormai. Lei porta via solo il quaderno chiuso.",speakerId:null,kind:"narration",lemmas:["archivio","del","comune","restare","la","con","alme","con","le","scatola","con","una","macchina","fermo","ormai","lei","portare","via","solo","il","quaderno","chiudere"]},{id:"s36",text:"Non vende. Non resta. Non \xe8 eroina. Guarda le finestre, parte, e la scuola sembra vuota. Questo \xe8 tutto.",speakerId:null,kind:"narration",lemmas:["non","vendere","non","restare","non","essere","eroina","guardare","le","finestra","partire","e","la","scuola","sembrare","vuoto","questo","essere","tutto"]},{id:"s37",text:"Dopo qualche giorno il no al contratto. Poi la cucina. Poi la borsa. Poi l'autobus. Poi lo sguardo, e via. Niente luce che torna.",speakerId:null,kind:"narration",lemmas:["dopo","qualche","giorno","il","no","al","contratto","poi","la","cucina","poi","la","borsa","poi","autobus","poi","lo","sguardo","e","via","niente","luce","che","tornare"]},{id:"s38",text:"L'archivio non \xe8 suo da vendere. La scuola non \xe8 sua da salvare da sola. Guarda, parte. Una finestra scura, ordinaria. Fine.",speakerId:null,kind:"narration",lemmas:["archivio","non","essere","suo","da","vendere","la","scuola","non","essere","suo","da","salvare","da","sola","guardare","partire","una","finestra","scuro","ordinario","fine"]},{id:"s39",text:"Parte da San Quirico sul Nera di giorno. Non c'\xe8 premio. Non c'\xe8 arresto. C'\xe8 un autobus, e uno sguardo, e una scuola che sembra vuota.",speakerId:null,kind:"narration",lemmas:["partire","da","san","quirico","sul","nera","di","giorno","non","ce","premio","non","ce","arresto","ce","un","autobus","e","uno","sguardo","e","una","scuola","che","sembrare","vuoto"]},{id:"s40",text:"Resta il paese. Resta la griglia. Resta la parola vuota, mutata, uguale in bocca a Loredana. Irene parte lo stesso.",speakerId:null,kind:"narration",lemmas:["restare","il","paese","restare","la","griglia","restare","la","parola","vuoto","mutare","uguale","in","bocca","a","loredana","irene","partire","lo","stesso"]},{id:"s41",text:"Non torna. Non accende. Non vende. Guarda una volta, e basta. Poi il motore parte, e lei va via da questo piccolo paese.",speakerId:null,kind:"narration",lemmas:["non","tornare","non","accendere","non","vendere","guardare","una","volta","e","bastare","poi","il","motore","partire","e","lei","andare","via","da","questo","piccolo","paese"]}]}],questions:[{id:"ch24_q01",chapterId:"la-casa-delle-finestre-24",type:"event",question:"What happens to Irene\u2019s contract?",choices:["It is not renewed; she leaves","Alme gives her a permanent job","She is arrested on the platform"],correctChoice:0,explanation:"The contract is short. We are not renewing it.",difficulty:2},{id:"ch24_q02",chapterId:"la-casa-delle-finestre-24",type:"direct",question:"Does she sell the story?",choices:["No","Yes, to television","Yes, to Mimmo"],correctChoice:0,explanation:"This town is not mine. I do not sell the story.",difficulty:2},{id:"ch24_q03",chapterId:"la-casa-delle-finestre-24",type:"inference",question:"What does she see as she leaves?",choices:["The grid in daylight: a building, one ordinary dark window","The lamp returning","Alme in handcuffs"],correctChoice:0,explanation:"One window is dark, ordinary. Not a lamp. She looks up, then leaves.",difficulty:2}]}},1027,[]);
